BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';

-- -----------------------------------------------------------------------------
-- SECTION 0: Same-Name Semantic Diff Deltas (20260619) & Legacy Bypass Cleanup
-- -----------------------------------------------------------------------------
-- 0A. Helpers introduced in canonical 20260619 (hardened further by 20261011)
CREATE OR REPLACE FUNCTION public.get_user_role(user_id uuid)
RETURNS text AS $$
DECLARE
    u_role text;
BEGIN
    SELECT role INTO u_role FROM public.users_profile WHERE id = user_id AND active = true;
    RETURN u_role;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.get_user_tenant_id(user_id uuid)
RETURNS uuid AS $$
DECLARE
    u_tenant_id uuid;
BEGIN
    SELECT tenant_id INTO u_tenant_id FROM public.users_profile WHERE id = user_id AND active = true;
    RETURN u_tenant_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Align Tenant Admin SELECT policy on users_profile with canonical non-recursive helper form
DROP POLICY IF EXISTS "Tenant Admin - SELECT employee/customer profiles" ON public.users_profile;
CREATE POLICY "Tenant Admin - SELECT employee/customer profiles"
ON public.users_profile FOR SELECT TO authenticated
USING (
    public.get_user_role(auth.uid()) = 'tenant_owner'
    AND public.get_user_tenant_id(auth.uid()) = tenant_id
);

-- NOTE: Deliberately preserving public.clinic_check_and_consume_ai_allowance()
