-- 6. Hardened get_public_appointment_by_manage_token with rate limiting, zero-PII leak and tenant isolation
CREATE OR REPLACE FUNCTION public.get_public_appointment_by_manage_token(
    p_token text,
    p_client_fingerprint text DEFAULT NULL,
    p_client_ip text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_server_ip         text;
    v_clean_fp          text;
    v_rate_check        jsonb;
    v_token_hash        text;
    v_token_record      record;
    v_appointment       record;
    v_service           record;
    v_staff             record;
    v_branch            record;
    v_tenant            record;
BEGIN
    -- Step 1: Derive trusted primary IP bucket server-side
    v_server_ip := public.resolve_self_service_client_ip(p_client_ip);
    v_clean_fp  := NULLIF(trim(lower(p_client_fingerprint)), '');

    -- Step 1.5: Acquire transaction-scoped advisory locks in deterministic order to prevent concurrency races & deadlocks
    IF v_server_ip IS NOT NULL AND v_clean_fp IS NOT NULL THEN
        IF hashtext('self_service_ip:' || v_server_ip) < hashtext('self_service_fp:' || v_clean_fp) THEN
            PERFORM pg_advisory_xact_lock(hashtext('self_service_ip:' || v_server_ip));
            PERFORM pg_advisory_xact_lock(hashtext('self_service_fp:' || v_clean_fp));
        ELSE
            PERFORM pg_advisory_xact_lock(hashtext('self_service_fp:' || v_clean_fp));
            PERFORM pg_advisory_xact_lock(hashtext('self_service_ip:' || v_server_ip));
        END IF;
    ELSIF v_server_ip IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtext('self_service_ip:' || v_server_ip));
    ELSIF v_clean_fp IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtext('self_service_fp:' || v_clean_fp));
    END IF;

    -- Step 2: Enforce Rate Limiting & Lockout
    v_rate_check := public.check_self_service_token_rate_limit(v_server_ip, v_clean_fp);
    IF NOT (v_rate_check->>'allowed')::boolean THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'TOKEN_LOOKUP_RATE_LIMITED');
    END IF;

    -- Step 3: Input hygiene
    IF p_token IS NULL OR length(trim(p_token)) < 32 OR length(trim(p_token)) > 128 THEN
        PERFORM public.record_self_service_token_lookup_failure(v_server_ip, v_clean_fp);
        RETURN jsonb_build_object('success', false, 'reason_code', 'invalid_token');
    END IF;

    -- Step 4: Compute SHA-256 digest
    v_token_hash := encode(sha256(trim(p_token)::bytea), 'hex');

    -- Step 5: Match appointment_access_tokens
    SELECT id, tenant_id, appointment_id, expires_at, used_at
    INTO v_token_record
    FROM public.appointment_access_tokens
    WHERE token_hash = v_token_hash
    LIMIT 1;

    IF NOT FOUND THEN
        PERFORM public.record_self_service_token_lookup_failure(v_server_ip, v_clean_fp);
        RETURN jsonb_build_object('success', false, 'reason_code', 'invalid_token');
    END IF;

    -- Step 6: Check expired or used (Zero-PII leakage, records lookup failure)
    IF v_token_record.used_at IS NOT NULL OR v_token_record.expires_at <= now() THEN
        PERFORM public.record_self_service_token_lookup_failure(v_server_ip, v_clean_fp);
        RETURN jsonb_build_object('success', false, 'reason_code', 'TOKEN_EXPIRED');
    END IF;

    -- Step 7: Resolve appointment record with strict tenant isolation
    SELECT id, tenant_id, branch_id, customer_id, service_id, staff_id,
           user_name, user_email, phone, appointment_date, appointment_time,
           duration_minutes, status, notes
    INTO v_appointment
    FROM public.appointments
    WHERE id = v_token_record.appointment_id
      AND tenant_id::text = v_token_record.tenant_id;

    IF NOT FOUND THEN
        PERFORM public.record_self_service_token_lookup_failure(v_server_ip, v_clean_fp);
        RETURN jsonb_build_object('success', false, 'reason_code', 'invalid_token');
    END IF;

    -- Step 8: Reset failure count on verified success
    IF v_server_ip IS NOT NULL THEN
        UPDATE public.self_service_token_rate_limits
        SET failure_count = 0, locked_until = NULL, updated_at = now()
        WHERE identifier_type = 'ip' AND client_identifier = v_server_ip
          AND (locked_until IS NULL OR locked_until <= now());
    END IF;
    IF v_clean_fp IS NOT NULL THEN
        UPDATE public.self_service_token_rate_limits
        SET failure_count = 0, locked_until = NULL, updated_at = now()
        WHERE identifier_type = 'fingerprint' AND client_identifier = v_clean_fp
          AND (locked_until IS NULL OR locked_until <= now());
    END IF;

    -- Step 9: Join service, staff, branch, tenant details (strictly tenant-isolated)
    SELECT id, name, name_tr, duration, price
    INTO v_service
    FROM public.services
    WHERE id = v_appointment.service_id
      AND tenant_id = v_appointment.tenant_id;

    SELECT id, name, title
    INTO v_staff
    FROM public.staff
    WHERE id = v_appointment.staff_id
      AND tenant_id = v_appointment.tenant_id;

    SELECT id, name, timezone
    INTO v_branch
    FROM public.branches
    WHERE id = v_appointment.branch_id
      AND tenant_id = v_appointment.tenant_id;

    SELECT id, name, official_business_name
    INTO v_tenant
    FROM public.tenants
    WHERE id = v_appointment.tenant_id;

    -- Step 10: Return sanitized response contract
    RETURN jsonb_build_object(
        'success', true,
        'reason_code', 'ok',
        'appointment', jsonb_build_object(
            'id', v_appointment.id,
            'status', v_appointment.status,
            'appointment_date', v_appointment.appointment_date,
            'appointment_time', v_appointment.appointment_time,
            'duration_minutes', COALESCE(v_appointment.duration_minutes, v_service.duration, 30),
            'customer_name', v_appointment.user_name,
            'customer_phone', v_appointment.phone,
            'notes', v_appointment.notes,
            'service', CASE WHEN v_service.id IS NOT NULL THEN jsonb_build_object(
                'id', v_service.id,
                'name', v_service.name,
                'name_tr', COALESCE(v_service.name_tr, v_service.name),
                'price', v_service.price
            ) ELSE NULL END,
            'staff', CASE WHEN v_staff.id IS NOT NULL THEN jsonb_build_object(
                'id', v_staff.id,
                'name', v_staff.name,
                'title', v_staff.title
            ) ELSE NULL END,
            'branch', CASE WHEN v_branch.id IS NOT NULL THEN jsonb_build_object(
                'id', v_branch.id,
                'name', v_branch.name,
                'timezone', COALESCE(v_branch.timezone, 'Europe/Istanbul')
            ) ELSE jsonb_build_object(
                'name', COALESCE(v_tenant.official_business_name, v_tenant.name, 'Güzellik Salonu'),
                'timezone', 'Europe/Istanbul'
            ) END
        ),
        'allowed_actions', jsonb_build_object(
            'can_cancel', false,
            'can_reschedule', false
        )
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'reason_code', 'invalid_token');
END;
$$;

REVOKE ALL ON FUNCTION public.get_public_appointment_by_manage_token(text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_appointment_by_manage_token(text, text, text) TO anon, authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260905_p2a_atomic_tenant_provisioning_rpc.sql
-- =============================================================================
-- 20260905_p2a_atomic_tenant_provisioning_rpc.sql
-- Parallel Lane P2A — Server-Authoritative Hardened Atomic Tenant Provisioning & Onboarding Initialization RPC (P2A.0-R2)
-- Governance: FILE ONLY. DO NOT APPLY TO LIVE STAGING DATABASE.
-- Note: Ported from 72911e4 (20260901_p2a_atomic_tenant_provisioning_rpc.sql) with conflict-free sequential prefix 20260905
--       preserving HEAD's 20260901..20260904 Pilot 3/4/5 security migrations untouched.
-- Description:
--   Provisions a new tenant atomically and idempotently for an authenticated user (auth.uid()).
--   P2A.0-R2 Schema Truth & Privacy Safeguards:
--     1. Populates canonical public.tenants columns (owner_user_id, official_business_name, public_display_name, category, city, phone, name, slug).
--     2. Business profile draft privacy: tenant_business_profiles.is_public_profile_enabled set to FALSE initially.
--     3. Forward-hardens public SELECT policy on tenant_business_profiles so anonymous public reads require is_public_profile_enabled = true AND tenant.public_site_status = 'published' AND tenant.onboarding_status = 'completed'.
--     4. Neutral initial business profile description (no premature 'online randevu kabul etmeye başlamıştır' claims).
--     5. Concurrency: Dual pg_advisory_xact_lock (owner-scoped & base-slug-scoped) preventing both same-owner and cross-owner slug race conditions.
--     6. Canonical plan request validation & effective plan_version resolution. Pre-commercial subscription status set to 'pending_onboarding' (billing_mode = 'manual').
-- Security:
--   - SECURITY DEFINER hardened with search_path = pg_catalog, public
--   - Strict auth.uid() identity binding
--   - REVOKE EXECUTE from PUBLIC and anon; GRANT EXECUTE to authenticated

CREATE TABLE IF NOT EXISTS public.tenant_provisioning_idempotency (
    idempotency_key TEXT NOT NULL CHECK (trim(idempotency_key) != ''),
    owner_user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    result_payload JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_user_id, idempotency_key)
);

ALTER TABLE public.tenant_provisioning_idempotency ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.tenant_provisioning_idempotency FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.provision_tenant_for_authenticated_owner(
    p_business_name TEXT,
    p_business_display_name TEXT DEFAULT NULL,
    p_business_category TEXT DEFAULT 'Hair Salon',
    p_city TEXT DEFAULT NULL,
    p_phone TEXT DEFAULT NULL,
    p_requested_plan_code TEXT DEFAULT 'baslangic',
    p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_id UUID;
    v_caller_email TEXT;
    v_existing_profile RECORD;
    v_tenant_id UUID;
    v_base_slug TEXT;
    v_slug TEXT;
    v_counter INT := 0;
    v_plan_id UUID;
    v_plan_ver_id UUID;
    v_resolved_plan_code TEXT;
    v_effective_version_count INT;
    v_sub_id UUID;
    v_result JSONB;
    v_cached_payload JSONB;
    v_clean_idempotency_key TEXT;
    v_official_name TEXT;
    v_display_name TEXT;
    v_category TEXT;
BEGIN
    -- 1. Authentication check
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Must be authenticated to provision a tenant.' USING ERRCODE = 'P0001';
    END IF;

    -- 2. Owner-Scoped Concurrency Serialization
    PERFORM pg_advisory_xact_lock(hashtextextended(v_caller_id::text, 9283741));

    -- Extract caller email from auth.users
    SELECT email INTO v_caller_email FROM auth.users WHERE id = v_caller_id;

    -- 3. Idempotency Check (Owner-Scoped)
    v_clean_idempotency_key := trim(COALESCE(p_idempotency_key, ''));
    IF v_clean_idempotency_key = '' THEN
        RAISE EXCEPTION 'MISSING_IDEMPOTENCY_KEY: Self-service tenant provisioning requires a valid non-empty idempotency key.' USING ERRCODE = 'P0001';
    END IF;

    SELECT result_payload INTO v_cached_payload
    FROM public.tenant_provisioning_idempotency
    WHERE owner_user_id = v_caller_id
      AND idempotency_key = v_clean_idempotency_key;

    IF v_cached_payload IS NOT NULL THEN
        RETURN v_cached_payload;
    END IF;

    -- 4. Existing Profile Safety Check
    SELECT id, tenant_id, role, active INTO v_existing_profile
    FROM public.users_profile
    WHERE id = v_caller_id;

    IF v_existing_profile.id IS NOT NULL THEN
        -- If profile already has a tenant_id, or is super_admin, staff, or tenant_owner, reject provisioning
        IF v_existing_profile.tenant_id IS NOT NULL THEN
            RAISE EXCEPTION 'USER_ALREADY_HAS_TENANT: User profile % already belongs to tenant %.', v_caller_id, v_existing_profile.tenant_id USING ERRCODE = 'P0001';
        END IF;

        IF v_existing_profile.role IN ('super_admin', 'staff', 'tenant_owner') THEN
            RAISE EXCEPTION 'PROFILE_NOT_PROVISIONABLE: Profile role % is not eligible for self-service tenant provisioning.', v_existing_profile.role USING ERRCODE = 'P0001';
        END IF;
    END IF;

    -- Validate business name
    v_official_name := trim(COALESCE(p_business_name, ''));
    IF v_official_name = '' THEN
        RAISE EXCEPTION 'INVALID_BUSINESS_NAME: Business name cannot be empty.' USING ERRCODE = 'P0001';
    END IF;

    v_display_name := trim(COALESCE(p_business_display_name, v_official_name));
    v_category := COALESCE(trim(p_business_category), 'Hair Salon');

    -- 5. Canonical Plan Selection & Authorization Validation
    v_resolved_plan_code := lower(trim(COALESCE(p_requested_plan_code, 'baslangic')));

    SELECT id INTO v_plan_id
    FROM public.plans
    WHERE code = v_resolved_plan_code
      AND is_active = true
      AND is_assignable = true
      AND is_public = true;

    IF v_plan_id IS NULL THEN
        RAISE EXCEPTION 'PLAN_NOT_ASSIGNABLE: Requested plan code % is invalid, inactive, non-public, or not assignable for public self-service.', v_resolved_plan_code USING ERRCODE = 'P0001';
    END IF;

    -- Resolve currently effective published plan_version_id
    SELECT count(*) INTO v_effective_version_count
    FROM public.plan_versions
    WHERE plan_id = v_plan_id
      AND lifecycle_status = 'published'
      AND effective_from <= now()
      AND (effective_to IS NULL OR effective_to > now());

    IF v_effective_version_count = 0 THEN
        RAISE EXCEPTION 'NO_EFFECTIVE_PLAN_VERSION: No currently effective published plan version found for plan %.', v_resolved_plan_code USING ERRCODE = 'P0001';
    ELSIF v_effective_version_count > 1 THEN
        RAISE EXCEPTION 'MULTIPLE_EFFECTIVE_PLAN_VERSIONS: Ambiguous published plan versions detected for plan %.', v_resolved_plan_code USING ERRCODE = 'P0001';
    END IF;

    SELECT id INTO v_plan_ver_id
    FROM public.plan_versions
    WHERE plan_id = v_plan_id
      AND lifecycle_status = 'published'
      AND effective_from <= now()
      AND (effective_to IS NULL OR effective_to > now())
    LIMIT 1;

    -- 6. Deterministic and Unique Slug Generation with Cross-Owner Advisory Lock
    v_base_slug := lower(regexp_replace(v_display_name, '[^a-zA-Z0-9]+', '-', 'g'));
    v_base_slug := regexp_replace(v_base_slug, '^-+|-+$', '', 'g');
    IF v_base_slug = '' THEN
        v_base_slug := 'salon';
    END IF;

    -- Lock slug namespace to prevent cross-owner slug generation race conditions
    PERFORM pg_advisory_xact_lock(hashtextextended(v_base_slug, 8823910));

    v_slug := v_base_slug;
    LOOP
        PERFORM 1 FROM public.tenants WHERE slug = v_slug;
        EXIT WHEN NOT FOUND;
        v_counter := v_counter + 1;
        v_slug := v_base_slug || '-' || v_counter;
    END LOOP;

    -- 7. Create Tenant Row (Populating Complete Canonical Identity & Draft Status)
    v_tenant_id := gen_random_uuid();
    INSERT INTO public.tenants (
        id,
        slug,
        name,
        official_business_name,
        public_display_name,
        owner_user_id,
        category,
        city,
        phone,
        status,
        provisioning_status,
        go_live_status,
        onboarding_status,
        public_site_status,
        verification_status,
        business_risk_status,
        created_at,
        updated_at
    ) VALUES (
        v_tenant_id,
        v_slug,
        v_display_name,
        v_official_name,
        v_display_name,
        v_caller_id,
        v_category,
        p_city,
        p_phone,
        'active',
        'onboarding_required',
        'draft',
        'onboarding_required',
        'draft',
        'not_submitted',
        'normal',
        now(),
        now()
    );

    -- 8. Upsert/Bind users_profile as tenant_owner
    INSERT INTO public.users_profile (
        id,
        tenant_id,
        name,
        role,
        active,
        created_at,
        updated_at
    ) VALUES (
        v_caller_id,
        v_tenant_id,
        v_display_name || ' Owner',
        'tenant_owner',
        true,
        now(),
        now()
    )
    ON CONFLICT (id) DO UPDATE SET
        tenant_id = v_tenant_id,
        role = 'tenant_owner',
        active = true,
        updated_at = now();

    -- 9. Create Business Profile Details (Neutral Initial Copy & is_public_profile_enabled = false)
    INSERT INTO public.tenant_business_profiles (
        tenant_id,
        short_description,
        about_text,
        business_category,
        address,
        city,
        phone,
        email,
        is_public_profile_enabled,
        created_at,
        updated_at
    ) VALUES (
        v_tenant_id,
        NULL,
        NULL,
        v_category,
        p_city,
        p_city,
        p_phone,
        v_caller_email,
        false, -- Draft business profile MUST NOT be public initially
        now(),
        now()
    )
    ON CONFLICT (tenant_id) DO NOTHING;

    -- 10. Create Default Branding
    INSERT INTO public.tenant_branding (
        tenant_id,
        business_name,
        primary_color,
        address,
        created_at,
        updated_at
    ) VALUES (
        v_tenant_id,
        v_display_name,
        '#4f46e5',
        p_city,
        now(),
        now()
    )
    ON CONFLICT (tenant_id) DO NOTHING;

    -- 11. Assign Non-Entitlement-Active Baseline Subscription Record
    v_sub_id := gen_random_uuid();
    INSERT INTO public.subscriptions (
        id,
        tenant_id,
        plan_id,
        plan_version_id,
        status,
        billing_mode,
        current_period_start,
        current_period_end,
        created_at,
        updated_at
    ) VALUES (
        v_sub_id,
        v_tenant_id,
        v_resolved_plan_code,
        v_plan_ver_id,
        'pending_onboarding',
        'manual',
        now(),
        now() + interval '1 year',
        now(),
        now()
    );

    -- 12. Initialize Onboarding State Machine (Checklist Starts Incomplete)
    INSERT INTO public.tenant_onboarding_progress (
        tenant_id,
        salon_info_completed,
        branding_completed,
        whatsapp_completed,
        services_completed,
        staff_completed,
        calendar_completed,
        test_appointment_completed,
        reviewed_by_admin,
        live_enabled,
        created_at,
        updated_at
    ) VALUES (
        v_tenant_id,
        false,
        false,
        false,
        false,
        false,
        false,
        false,
        false,
        false,
        now(),
        now()
    )
    ON CONFLICT (tenant_id) DO NOTHING;

    -- 13. Audit Log Entry
    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_tenant_id::text,
        v_caller_id::text,
        'tenant_owner',
        'tenant_provisioned',
        'tenants',
        v_tenant_id::text,
        jsonb_build_object(
            'slug', v_slug,
            'plan_code', v_resolved_plan_code,
            'plan_version_id', v_plan_ver_id,
            'subscription_status', 'pending_onboarding'
        )
    );

    -- 14. Build Response JSON
    v_result := jsonb_build_object(
        'success', true,
        'tenant_id', v_tenant_id,
        'slug', v_slug,
        'role', 'tenant_owner',
        'onboarding_status', 'onboarding_required',
        'subscription_id', v_sub_id,
        'plan_code', v_resolved_plan_code,
        'plan_version_id', v_plan_ver_id,
        'subscription_status', 'pending_onboarding'
    );

    -- 15. Record Idempotency Result
    INSERT INTO public.tenant_provisioning_idempotency (
        idempotency_key,
        owner_user_id,
        tenant_id,
        result_payload,
        created_at
    ) VALUES (
        v_clean_idempotency_key,
        v_caller_id,
        v_tenant_id,
        v_result,
        now()
    ) ON CONFLICT (owner_user_id, idempotency_key) DO NOTHING;

    RETURN v_result;
END;
$$;

-- Forward-Harden Public RLS Policy on tenant_business_profiles
DROP POLICY IF EXISTS "Public can view enabled business profiles" ON public.tenant_business_profiles;
DROP POLICY IF EXISTS "Public can view enabled and published business profiles" ON public.tenant_business_profiles;
DROP POLICY IF EXISTS "Public can view enabled and published business profiles" ON public.tenant_business_profiles;
CREATE POLICY "Public can view enabled and published business profiles"
    ON public.tenant_business_profiles
    FOR SELECT TO public
    USING (
        is_public_profile_enabled = true
        AND EXISTS (
            SELECT 1 FROM public.tenants t
            WHERE t.id = tenant_business_profiles.tenant_id
              AND t.status IN ('active', 'manual_active')
              AND t.onboarding_status = 'completed'
              AND t.public_site_status = 'published'
        )
    );

-- Revoke public execution permissions
REVOKE EXECUTE ON FUNCTION public.provision_tenant_for_authenticated_owner(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.provision_tenant_for_authenticated_owner(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) FROM anon;

-- Grant execution to authenticated users
GRANT EXECUTE ON FUNCTION public.provision_tenant_for_authenticated_owner(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) TO authenticated;

-- =============================================================================
-- SOURCE: 20260906_p2a_publish_commercial_contract_alignment.sql
-- =============================================================================
-- 20260906_p2a_publish_commercial_contract_alignment.sql
-- Parallel Lane P2A — Forward-Hardened Admin Publish & Commercial Contract Alignment RPC
-- Governance: FILE ONLY. DO NOT APPLY TO LIVE STAGING DATABASE.
-- Note: Ported from 72911e4 (20260902_p2a_publish_commercial_contract_alignment.sql) with conflict-free sequential prefix 20260906
--       preserving HEAD's 20260901..20260904 Pilot 3/4/5 security migrations untouched.
-- Description:
--   Hardens public.approve_and_publish_tenant(uuid) to preserve the tenant's selected
--   canonical plan_id and matching plan_version_id upon operator publish/activation.
--   P2A.0-R2 Improvements:
--     1. Eliminates legacy 'premium_monthly' forced plan rewrite.
--     2. Preserves tenant's selected canonical plan_id and plan_version_id.
--     3. Transitions subscription status from 'pending_onboarding' to 'manual_active'.
--     4. Preserves all readiness checklist checks (business profile, active service, active staff, staff-service mapping, availability rules).
--     5. Updates tenant status = 'active', onboarding_status = 'completed', public_site_status = 'published', provisioning_status = 'live', go_live_status = 'live', verification_status = 'approved'.
--     6. Writes an audit event to public.audit_events.
-- Security:
--   - SECURITY DEFINER hardened with search_path = pg_catalog, public
--   - Strict super_admin caller authorization check
--   - REVOKE EXECUTE from PUBLIC and anon; GRANT EXECUTE to authenticated

CREATE OR REPLACE FUNCTION public.approve_and_publish_tenant(p_tenant_id uuid)
RETURNS jsonb AS $$
DECLARE
    v_caller_role text;
    v_caller_tenant_id uuid;
    v_has_profile boolean;
    v_has_service boolean;
    v_has_staff boolean;
    v_has_staff_service boolean;
    v_has_availability boolean;
    v_current_plan_id text;
    v_current_plan_ver_id uuid;
    v_selected_sub_id uuid;
    v_fallback_ver_id uuid;
    v_result jsonb;
    v_persisted_tenant jsonb;
    v_persisted_sub jsonb;
BEGIN
    -- 1. Security check: Caller must be super_admin with NULL tenant_id
    SELECT role, tenant_id INTO v_caller_role, v_caller_tenant_id
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF v_caller_role IS DISTINCT FROM 'super_admin' OR v_caller_tenant_id IS NOT NULL THEN
        RAISE EXCEPTION 'UNAUTHORIZED: Only platform super_admin can approve and publish a tenant.' USING ERRCODE = 'P0001';
    END IF;

    -- 2. Lock/Load tenant row
    PERFORM 1 FROM public.tenants WHERE id = p_tenant_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'TENANT_NOT_FOUND: Specified tenant % does not exist.', p_tenant_id USING ERRCODE = 'P0001';
    END IF;

    -- 3. Readiness checklist verification
    -- A. Business profile exists
    SELECT EXISTS (
        SELECT 1 FROM public.tenant_business_profiles WHERE tenant_id = p_tenant_id
    ) INTO v_has_profile;
    IF NOT v_has_profile THEN
        RAISE EXCEPTION 'ONBOARDING_NOT_READY: Business profile (tenant_business_profiles) missing.' USING ERRCODE = 'P0001';
    END IF;

    -- B. Active service exists
    SELECT EXISTS (
        SELECT 1 FROM public.services WHERE tenant_id = p_tenant_id AND active = true
    ) INTO v_has_service;
    IF NOT v_has_service THEN
        RAISE EXCEPTION 'ONBOARDING_NOT_READY: No active service configured for tenant.' USING ERRCODE = 'P0001';
    END IF;

    -- C. Active staff exists
    SELECT EXISTS (
        SELECT 1 FROM public.staff WHERE tenant_id = p_tenant_id AND active = true
    ) INTO v_has_staff;
    IF NOT v_has_staff THEN
        RAISE EXCEPTION 'ONBOARDING_NOT_READY: No active staff member configured for tenant.' USING ERRCODE = 'P0001';
    END IF;

    -- D. Staff-service assignment exists
    SELECT EXISTS (
        SELECT 1 FROM public.staff_services ss
        JOIN public.services s ON s.id = ss.service_id
        JOIN public.staff st ON st.id = ss.staff_id
        WHERE s.tenant_id = p_tenant_id AND st.tenant_id = p_tenant_id AND s.active = true AND st.active = true
    ) INTO v_has_staff_service;
    IF NOT v_has_staff_service THEN
        RAISE EXCEPTION 'ONBOARDING_NOT_READY: No valid staff-service assignment found for tenant.' USING ERRCODE = 'P0001';
    END IF;

    -- E. Active availability rules exist
    SELECT EXISTS (
        SELECT 1 FROM public.availability_rules ar
        JOIN public.staff st ON st.id = ar.staff_id
        WHERE ar.tenant_id = p_tenant_id AND st.tenant_id = p_tenant_id AND st.active = true
    ) INTO v_has_availability;
    IF NOT v_has_availability THEN
        RAISE EXCEPTION 'ONBOARDING_NOT_READY: No active availability rules configured for tenant.' USING ERRCODE = 'P0001';
    END IF;

    -- 4. Preserve canonical plan selection and update ONLY the selected current subscription to manual_active
    SELECT id, plan_id, plan_version_id
    INTO v_selected_sub_id, v_current_plan_id, v_current_plan_ver_id
    FROM public.subscriptions
    WHERE tenant_id = p_tenant_id
      AND status NOT IN ('cancelled', 'expired')
    ORDER BY (status = 'pending_onboarding') DESC, created_at DESC, id DESC
    LIMIT 1
    FOR UPDATE;

    IF v_selected_sub_id IS NOT NULL THEN
        UPDATE public.subscriptions
        SET
            status = 'manual_active',
            billing_mode = 'manual',
            payment_reference_note = 'Approved and published by Super Admin'
        WHERE id = v_selected_sub_id;
    ELSE
        -- Fallback to baslangic (resolving current effective published plan_version_id if available)
        SELECT pv.id INTO v_fallback_ver_id
        FROM public.plans p
        JOIN public.plan_versions pv ON pv.plan_id = p.id
        WHERE p.code = 'baslangic'
          AND pv.lifecycle_status = 'published'
          AND pv.effective_from <= now()
          AND (pv.effective_to IS NULL OR pv.effective_to > now())
        ORDER BY pv.version_number DESC
        LIMIT 1;

        v_selected_sub_id := gen_random_uuid();
        INSERT INTO public.subscriptions (
            id,
            tenant_id,
            plan_id,
            plan_version_id,
            status,
            billing_mode,
            payment_reference_note
        ) VALUES (
            v_selected_sub_id,
            p_tenant_id,
            'baslangic',
            v_fallback_ver_id,
            'manual_active',
            'manual',
            'Approved and published by Super Admin'
        );

        v_current_plan_id := 'baslangic';
        v_current_plan_ver_id := v_fallback_ver_id;
    END IF;

    -- 5. Update tenant publish & onboarding state
    UPDATE public.tenants
    SET
        status = 'active',
        onboarding_status = 'completed',
        public_site_status = 'published',
        provisioning_status = 'live',
        go_live_status = 'live',
        verification_status = 'approved'
    WHERE id = p_tenant_id;

    -- 6. Enable business profile public visibility
    UPDATE public.tenant_business_profiles
    SET is_public_profile_enabled = true
    WHERE tenant_id = p_tenant_id;

    -- 7. Audit log entry
    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        p_tenant_id::text,
        auth.uid()::text,
        'super_admin',
        'tenant_approved_and_published',
        'tenants',
        p_tenant_id::text,
        jsonb_build_object(
            'plan_id', v_current_plan_id,
            'plan_version_id', v_current_plan_ver_id,
            'status', 'manual_active'
        )
    );

    -- 8. Retrieve actual persisted state
    SELECT row_to_json(t)::jsonb INTO v_persisted_tenant FROM public.tenants t WHERE t.id = p_tenant_id;
    SELECT row_to_json(s)::jsonb INTO v_persisted_sub FROM public.subscriptions s WHERE s.id = v_selected_sub_id;

    v_result := jsonb_build_object(
        'tenant', v_persisted_tenant,
        'subscription', v_persisted_sub
    );

    RETURN v_result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public;

