GRANT EXECUTE ON FUNCTION public.create_owner_first_staff(TEXT, UUID[], INT[], TIME, TIME) TO authenticated;

REVOKE EXECUTE ON FUNCTION public.get_owner_onboarding_state() FROM PUBLIC, anon;
