-- SOURCE: 20260913_phase3_reporting_analytics_foundation.sql
-- =============================================================================
-- ===========================================================================
-- Ported from 72911e4: 20260922_phase3_reporting_analytics_foundation.sql
-- Conflict-free sequential prefix: 20260913 (ADIM-033 / Faz D1)
-- Implementation Authority ID: LARI-PROGRAM-V2-PHASE3-REPORTING-ANALYTICS-FOUNDATION-20260911-01
-- Correction Authority ID: LARI-PROGRAM-V2-PHASE3-R1-CORRECTIONS-AND-PHASE4-CONTINUATION-20260911-01
-- Program ID: LARI-PROGRAM-V2-REAL-PRODUCT-20260908-01
--
-- R1 Hardening Requirements:
-- 1. Schema Truth: Strictly use services.price INTEGER NOT NULL. Nonexistent price column references eliminated.
-- 2. Financial Semantics: Strictly labelled ESTIMATED_REVENUE. Zero representation as collected, settled, or accounting revenue.
--    Limitation explicitly noted: derived from current service catalog price.
-- 3. Metric naming accuracy:
--    - Use occupied_minutes and appointment_load.
--    - Does not misname raw volume as "utilization" unless a real schedule capacity denominator is present.
-- 4. Branch access control:
--    - Staff calling analytics are restricted to branches they are assigned to via public.staff_branches.
-- 5. Bounded pagination & Top-N controls (p_limit, p_offset) to prevent unbounded memory aggregation.
-- 6. Unimplemented capabilities (acquisition / campaign attribution) classified honestly as:
--    NOT_AVAILABLE_IN_CURRENT_SOURCE_TRUTH rather than fabricating synthetic data.
-- 7. Security:
--    - Strict tenant-scoped and role-authorized (tenant_owner, staff, super_admin).
--    - Date horizon bounds enforced (max 366 days window).
--    - Revoked from PUBLIC and anon.
-- ===========================================================================

-- =========================================================================
-- 1. RPC: public.get_tenant_booking_analytics
-- =========================================================================

CREATE OR REPLACE FUNCTION public.get_tenant_booking_analytics(
    p_tenant_id  UUID,
    p_branch_id  UUID DEFAULT NULL,
    p_start_date DATE DEFAULT (CURRENT_DATE - INTERVAL '30 days')::DATE,
    p_end_date   DATE DEFAULT CURRENT_DATE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user                 RECORD;
    v_total_bookings       BIGINT := 0;
    v_confirmed_count      BIGINT := 0;
    v_completed_count      BIGINT := 0;
    v_cancelled_count      BIGINT := 0;
    v_no_show_count        BIGINT := 0;
    v_total_occupied_min   BIGINT := 0;
    v_estimated_revenue    NUMERIC := 0.00;
    v_avg_duration_min     NUMERIC := 0.00;
BEGIN
    -- Authorization check
    SELECT role, tenant_id, id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Unauthenticated' USING ERRCODE = '42501';
    END IF;

    IF v_user.role NOT IN ('super_admin', 'tenant_owner', 'staff') THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Role not authorized' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND v_user.tenant_id IS DISTINCT FROM p_tenant_id THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Tenant mismatch' USING ERRCODE = '42501';
    END IF;

    -- Staff branch restriction check
    IF v_user.role = 'staff' AND p_branch_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.staff_branches sb
            JOIN public.staff s ON s.id = sb.staff_id
            WHERE s.user_profile_id = v_user.id AND sb.branch_id = p_branch_id AND sb.tenant_id = p_tenant_id
        ) THEN
            RAISE EXCEPTION 'PERMISSION_DENIED: Staff not assigned to branch' USING ERRCODE = '42501';
        END IF;
    END IF;

    -- Date horizon bounds
    IF p_end_date < p_start_date THEN
        RAISE EXCEPTION 'INVALID_DATE_RANGE: p_end_date must be greater than or equal to p_start_date' USING ERRCODE = 'P0001';
    END IF;
    IF (p_end_date - p_start_date) > 366 THEN
        RAISE EXCEPTION 'DATE_RANGE_EXCEEDED: Maximum analytics query window is 366 days' USING ERRCODE = 'P0001';
    END IF;

    SELECT
        COALESCE(count(*), 0),
        COALESCE(count(*) FILTER (WHERE a.status = 'confirmed'), 0),
        COALESCE(count(*) FILTER (WHERE a.status = 'completed'), 0),
        COALESCE(count(*) FILTER (WHERE a.status IN ('cancelled', 'cancelled_by_customer', 'cancelled_by_salon', 'cancelled_by_system')), 0),
        COALESCE(count(*) FILTER (WHERE a.status = 'no_show'), 0),
        COALESCE(SUM(COALESCE(a.duration_minutes, 30)), 0),
        COALESCE(AVG(COALESCE(a.duration_minutes, 30)), 0.00),
        COALESCE(SUM(
            CASE
                WHEN a.status IN ('confirmed', 'completed') THEN COALESCE(s.price, 0)
                ELSE 0
            END
        ), 0.00)
    INTO
        v_total_bookings,
        v_confirmed_count,
        v_completed_count,
        v_cancelled_count,
        v_no_show_count,
        v_total_occupied_min,
        v_avg_duration_min,
        v_estimated_revenue
    FROM public.appointments a
    LEFT JOIN public.services s ON s.id = a.service_id AND s.tenant_id = a.tenant_id
    WHERE a.tenant_id = p_tenant_id
      AND (
          (p_branch_id IS NOT NULL AND a.branch_id = p_branch_id)
          OR
          (p_branch_id IS NULL AND (
              v_user.role IN ('super_admin', 'tenant_owner')
              OR
              (v_user.role = 'staff' AND a.branch_id IN (
                  SELECT sb.branch_id FROM public.staff_branches sb
                  JOIN public.staff st ON st.id = sb.staff_id
                  WHERE st.user_profile_id = v_user.id AND sb.tenant_id = p_tenant_id
              ))
          ))
      )
      AND a.appointment_date >= p_start_date
      AND a.appointment_date <= p_end_date;

    RETURN jsonb_build_object(
        'tenant_id', p_tenant_id,
        'branch_id', p_branch_id,
        'start_date', p_start_date,
        'end_date', p_end_date,
        'metrics', jsonb_build_object(
            'total_bookings', v_total_bookings,
            'confirmed_bookings', v_confirmed_count,
            'completed_bookings', v_completed_count,
            'cancelled_bookings', v_cancelled_count,
            'no_show_bookings', v_no_show_count,
            'total_occupied_minutes', v_total_occupied_min,
            'avg_duration_minutes', ROUND(v_avg_duration_min, 1),
            'financial_metric_classification', 'ESTIMATED_REVENUE',
            'financial_metric_limitation', 'Estimated revenue derived from current service catalog price. Does not represent settled, collected, or accounting revenue.',
            'estimated_revenue', v_estimated_revenue
        ),
        'funnel', jsonb_build_object(
            'completion_rate', CASE WHEN v_total_bookings > 0 THEN ROUND((v_completed_count::NUMERIC / v_total_bookings::NUMERIC) * 100, 2) ELSE 0.00 END,
            'cancellation_rate', CASE WHEN v_total_bookings > 0 THEN ROUND((v_cancelled_count::NUMERIC / v_total_bookings::NUMERIC) * 100, 2) ELSE 0.00 END,
            'no_show_rate', CASE WHEN v_total_bookings > 0 THEN ROUND((v_no_show_count::NUMERIC / v_total_bookings::NUMERIC) * 100, 2) ELSE 0.00 END
        ),
        'attribution', jsonb_build_object(
            'acquisition_source_status', 'NOT_AVAILABLE_IN_CURRENT_SOURCE_TRUTH',
            'campaign_attribution_status', 'NOT_AVAILABLE_IN_CURRENT_SOURCE_TRUTH'
        )
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_tenant_booking_analytics(UUID, UUID, DATE, DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_booking_analytics(UUID, UUID, DATE, DATE) TO authenticated, service_role;

-- =========================================================================
-- 2. RPC: public.get_tenant_staff_performance_analytics
-- =========================================================================

CREATE OR REPLACE FUNCTION public.get_tenant_staff_performance_analytics(
    p_tenant_id  UUID,
    p_branch_id  UUID DEFAULT NULL,
    p_start_date DATE DEFAULT (CURRENT_DATE - INTERVAL '30 days')::DATE,
    p_end_date   DATE DEFAULT CURRENT_DATE,
    p_limit      INTEGER DEFAULT 50,
    p_offset     INTEGER DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user       RECORD;
    v_staff_list JSONB;
    v_total_cnt  BIGINT := 0;
BEGIN
    SELECT role, tenant_id, id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Unauthenticated' USING ERRCODE = '42501';
    END IF;

    IF v_user.role NOT IN ('super_admin', 'tenant_owner', 'staff') THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Role not authorized' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND v_user.tenant_id IS DISTINCT FROM p_tenant_id THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Tenant mismatch' USING ERRCODE = '42501';
    END IF;

    IF v_user.role = 'staff' AND p_branch_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.staff_branches sb
            JOIN public.staff s ON s.id = sb.staff_id
            WHERE s.user_profile_id = v_user.id AND sb.branch_id = p_branch_id AND sb.tenant_id = p_tenant_id
        ) THEN
            RAISE EXCEPTION 'PERMISSION_DENIED: Staff not assigned to branch' USING ERRCODE = '42501';
        END IF;
    END IF;

    IF p_end_date < p_start_date OR (p_end_date - p_start_date) > 366 THEN
        RAISE EXCEPTION 'INVALID_DATE_RANGE' USING ERRCODE = 'P0001';
    END IF;

    SELECT count(*) INTO v_total_cnt
    FROM public.staff st
    WHERE st.tenant_id = p_tenant_id
      AND (
          v_user.role IN ('super_admin', 'tenant_owner')
          OR
          (v_user.role = 'staff' AND st.user_profile_id = v_user.id)
      );

    SELECT jsonb_agg(
        jsonb_build_object(
            'staff_id', q.id,
            'staff_name', q.name,
            'is_active', q.active,
            'total_appointments', COALESCE(q.total_appts, 0),
            'completed_appointments', COALESCE(q.completed_appts, 0),
            'cancelled_appointments', COALESCE(q.cancelled_appts, 0),
            'occupied_minutes', COALESCE(q.total_duration, 0),
            'financial_metric_classification', 'ESTIMATED_REVENUE',
            'financial_metric_limitation', 'Estimated revenue derived from current service catalog price. Does not represent settled, collected, or accounting revenue.',
            'estimated_revenue', COALESCE(q.est_revenue, 0.00)
        )
    )
    INTO v_staff_list
    FROM (
        SELECT
            st.id,
            st.name,
            st.active,
            s_agg.total_appts,
            s_agg.completed_appts,
            s_agg.cancelled_appts,
            s_agg.total_duration,
            s_agg.est_revenue
        FROM public.staff st
        LEFT JOIN (
            SELECT
                a.staff_id,
                count(*) AS total_appts,
                count(*) FILTER (WHERE a.status = 'completed') AS completed_appts,
                count(*) FILTER (WHERE a.status IN ('cancelled', 'cancelled_by_customer', 'cancelled_by_salon', 'cancelled_by_system')) AS cancelled_appts,
                SUM(COALESCE(a.duration_minutes, 30)) AS total_duration,
                SUM(CASE WHEN a.status IN ('confirmed', 'completed') THEN COALESCE(svc.price, 0) ELSE 0 END) AS est_revenue
            FROM public.appointments a
            LEFT JOIN public.services svc ON svc.id = a.service_id AND svc.tenant_id = a.tenant_id
            WHERE a.tenant_id = p_tenant_id
              AND (p_branch_id IS NULL OR a.branch_id = p_branch_id)
              AND (
                  v_user.role IN ('super_admin', 'tenant_owner')
                  OR (
                      v_user.role = 'staff' AND a.branch_id IN (
                          SELECT sb.branch_id FROM public.staff_branches sb
                          JOIN public.staff st_own ON st_own.id = sb.staff_id
                          WHERE st_own.user_profile_id = v_user.id AND sb.tenant_id = p_tenant_id
                      )
                  )
              )
              AND a.appointment_date >= p_start_date
              AND a.appointment_date <= p_end_date
            GROUP BY a.staff_id
        ) s_agg ON s_agg.staff_id = st.id
        WHERE st.tenant_id = p_tenant_id
          AND (
              v_user.role IN ('super_admin', 'tenant_owner')
              OR
              (v_user.role = 'staff' AND st.user_profile_id = v_user.id)
          )
        ORDER BY COALESCE(s_agg.total_appts, 0) DESC, st.name ASC
        LIMIT LEAST(GREATEST(1, p_limit), 100)
        OFFSET GREATEST(0, p_offset)
    ) q;

    RETURN jsonb_build_object(
        'tenant_id', p_tenant_id,
        'branch_id', p_branch_id,
        'start_date', p_start_date,
        'end_date', p_end_date,
        'total_staff_count', v_total_cnt,
        'limit', p_limit,
        'offset', p_offset,
        'staff_performance', COALESCE(v_staff_list, '[]'::jsonb)
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_tenant_staff_performance_analytics(UUID, UUID, DATE, DATE, INTEGER, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_staff_performance_analytics(UUID, UUID, DATE, DATE, INTEGER, INTEGER) TO authenticated, service_role;

-- =========================================================================
-- 3. RPC: public.get_tenant_service_performance_analytics
-- =========================================================================

CREATE OR REPLACE FUNCTION public.get_tenant_service_performance_analytics(
    p_tenant_id  UUID,
    p_branch_id  UUID DEFAULT NULL,
    p_start_date DATE DEFAULT (CURRENT_DATE - INTERVAL '30 days')::DATE,
    p_end_date   DATE DEFAULT CURRENT_DATE,
    p_limit      INTEGER DEFAULT 50,
    p_offset     INTEGER DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user         RECORD;
    v_service_list JSONB;
    v_total_cnt    BIGINT := 0;
BEGIN
    SELECT role, tenant_id, id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Unauthenticated' USING ERRCODE = '42501';
    END IF;

    IF v_user.role NOT IN ('super_admin', 'tenant_owner', 'staff') THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Role not authorized' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND v_user.tenant_id IS DISTINCT FROM p_tenant_id THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Tenant mismatch' USING ERRCODE = '42501';
    END IF;

    IF v_user.role = 'staff' AND p_branch_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.staff_branches sb
            JOIN public.staff s ON s.id = sb.staff_id
            WHERE s.user_profile_id = v_user.id AND sb.branch_id = p_branch_id AND sb.tenant_id = p_tenant_id
        ) THEN
            RAISE EXCEPTION 'PERMISSION_DENIED: Staff not assigned to branch' USING ERRCODE = '42501';
        END IF;
    END IF;

    IF p_end_date < p_start_date OR (p_end_date - p_start_date) > 366 THEN
        RAISE EXCEPTION 'INVALID_DATE_RANGE' USING ERRCODE = 'P0001';
    END IF;

    SELECT count(*) INTO v_total_cnt
    FROM public.services s
    WHERE s.tenant_id = p_tenant_id
      AND (
          v_user.role IN ('super_admin', 'tenant_owner')
          OR (
              v_user.role = 'staff' AND EXISTS (
                  SELECT 1
                  FROM public.service_branches sb_svc
                  JOIN public.staff_branches sb_stf
                    ON sb_stf.branch_id = sb_svc.branch_id
                   AND sb_stf.tenant_id = sb_svc.tenant_id
                  JOIN public.staff stf
                    ON stf.id = sb_stf.staff_id
                  WHERE sb_svc.service_id = s.id
                    AND sb_svc.tenant_id = p_tenant_id
                    AND stf.user_profile_id = v_user.id
                    AND (p_branch_id IS NULL OR sb_svc.branch_id = p_branch_id)
              )
          )
      );

    SELECT jsonb_agg(
        jsonb_build_object(
            'service_id', q.id,
            'service_name', q.name,
            'duration_minutes', q.duration,
            'catalog_price', q.price,
            'total_bookings', COALESCE(q.total_bookings, 0),
            'completed_bookings', COALESCE(q.completed_bookings, 0),
            'occupied_minutes', COALESCE(q.total_duration, 0),
            'financial_metric_classification', 'ESTIMATED_REVENUE',
            'financial_metric_limitation', 'Estimated revenue derived from current service catalog price. Does not represent settled, collected, or accounting revenue.',
            'estimated_revenue', COALESCE(q.est_revenue, 0.00)
        )
    )
    INTO v_service_list
    FROM (
        SELECT
            s.id,
            s.name,
            s.duration,
            s.price,
            svc_agg.total_bookings,
            svc_agg.completed_bookings,
            svc_agg.total_duration,
            svc_agg.est_revenue
        FROM public.services s
        LEFT JOIN (
            SELECT
                a.service_id,
                count(*) AS total_bookings,
                count(*) FILTER (WHERE a.status = 'completed') AS completed_bookings,
                SUM(COALESCE(a.duration_minutes, 30)) AS total_duration,
                SUM(CASE WHEN a.status IN ('confirmed', 'completed') THEN COALESCE(svc.price, 0) ELSE 0 END) AS est_revenue
            FROM public.appointments a
            LEFT JOIN public.services svc ON svc.id = a.service_id AND svc.tenant_id = a.tenant_id
            WHERE a.tenant_id = p_tenant_id
              AND (p_branch_id IS NULL OR a.branch_id = p_branch_id)
              AND (
                  v_user.role IN ('super_admin', 'tenant_owner')
                  OR (
                      v_user.role = 'staff' AND a.branch_id IN (
                          SELECT sb.branch_id FROM public.staff_branches sb
                          JOIN public.staff st_own ON st_own.id = sb.staff_id
                          WHERE st_own.user_profile_id = v_user.id AND sb.tenant_id = p_tenant_id
                      )
                  )
              )
              AND a.appointment_date >= p_start_date
              AND a.appointment_date <= p_end_date
            GROUP BY a.service_id
        ) svc_agg ON svc_agg.service_id = s.id
        WHERE s.tenant_id = p_tenant_id
          AND (
              v_user.role IN ('super_admin', 'tenant_owner')
              OR (
                  v_user.role = 'staff' AND EXISTS (
                      SELECT 1
                      FROM public.service_branches sb_svc
                      JOIN public.staff_branches sb_stf
                        ON sb_stf.branch_id = sb_svc.branch_id
                       AND sb_stf.tenant_id = sb_svc.tenant_id
                      JOIN public.staff stf
                        ON stf.id = sb_stf.staff_id
                      WHERE sb_svc.service_id = s.id
                        AND sb_svc.tenant_id = p_tenant_id
                        AND stf.user_profile_id = v_user.id
                        AND (p_branch_id IS NULL OR sb_svc.branch_id = p_branch_id)
                  )
              )
          )
        ORDER BY COALESCE(svc_agg.total_bookings, 0) DESC, s.name ASC
        LIMIT LEAST(GREATEST(1, p_limit), 100)
        OFFSET GREATEST(0, p_offset)
    ) q;

    RETURN jsonb_build_object(
        'tenant_id', p_tenant_id,
        'branch_id', p_branch_id,
        'start_date', p_start_date,
        'end_date', p_end_date,
        'total_services_count', v_total_cnt,
        'limit', p_limit,
        'offset', p_offset,
        'service_performance', COALESCE(v_service_list, '[]'::jsonb)
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_tenant_service_performance_analytics(UUID, UUID, DATE, DATE, INTEGER, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_service_performance_analytics(UUID, UUID, DATE, DATE, INTEGER, INTEGER) TO authenticated, service_role;

-- =========================================================================
-- 4. RPC: public.get_tenant_branch_comparison_analytics
-- =========================================================================

CREATE OR REPLACE FUNCTION public.get_tenant_branch_comparison_analytics(
    p_tenant_id  UUID,
    p_start_date DATE DEFAULT (CURRENT_DATE - INTERVAL '30 days')::DATE,
    p_end_date   DATE DEFAULT CURRENT_DATE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user        RECORD;
    v_branch_list JSONB;
BEGIN
    SELECT role, tenant_id, id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Unauthenticated' USING ERRCODE = '42501';
    END IF;

    IF v_user.role NOT IN ('super_admin', 'tenant_owner', 'staff') THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Role not authorized' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND v_user.tenant_id IS DISTINCT FROM p_tenant_id THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Tenant mismatch' USING ERRCODE = '42501';
    END IF;

    IF p_end_date < p_start_date OR (p_end_date - p_start_date) > 366 THEN
        RAISE EXCEPTION 'INVALID_DATE_RANGE' USING ERRCODE = 'P0001';
    END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'branch_id', b.id,
            'branch_name', b.name,
            'is_primary', b.is_primary,
            'is_active', b.is_active,
            'total_appointments', COALESCE(b_agg.total_appts, 0),
            'completed_appointments', COALESCE(b_agg.completed_appts, 0),
            'occupied_minutes', COALESCE(b_agg.total_duration, 0),
            'financial_metric_classification', 'ESTIMATED_REVENUE',
            'financial_metric_limitation', 'Estimated revenue derived from current service catalog price. Does not represent settled, collected, or accounting revenue.',
            'estimated_revenue', COALESCE(b_agg.est_revenue, 0.00)
        )
        ORDER BY b.is_primary DESC, b.name ASC
    )
    INTO v_branch_list
    FROM public.branches b
    LEFT JOIN (
        SELECT
            a.branch_id,
            count(*) AS total_appts,
            count(*) FILTER (WHERE a.status = 'completed') AS completed_appts,
            SUM(COALESCE(a.duration_minutes, 30)) AS total_duration,
            SUM(CASE WHEN a.status IN ('confirmed', 'completed') THEN COALESCE(svc.price, 0) ELSE 0 END) AS est_revenue
        FROM public.appointments a
        LEFT JOIN public.services svc ON svc.id = a.service_id AND svc.tenant_id = a.tenant_id
        WHERE a.tenant_id = p_tenant_id
          AND (
              v_user.role IN ('super_admin', 'tenant_owner')
              OR (
                  v_user.role = 'staff' AND a.branch_id IN (
                      SELECT sb.branch_id FROM public.staff_branches sb
                      JOIN public.staff st_own ON st_own.id = sb.staff_id
                      WHERE st_own.user_profile_id = v_user.id AND sb.tenant_id = p_tenant_id
                  )
              )
          )
          AND a.appointment_date >= p_start_date
          AND a.appointment_date <= p_end_date
        GROUP BY a.branch_id
    ) b_agg ON b_agg.branch_id = b.id
    WHERE b.tenant_id = p_tenant_id
      AND (
          v_user.role IN ('super_admin', 'tenant_owner')
          OR (
              v_user.role = 'staff' AND b.id IN (
                  SELECT sb.branch_id FROM public.staff_branches sb
                  JOIN public.staff st_own ON st_own.id = sb.staff_id
                  WHERE st_own.user_profile_id = v_user.id AND sb.tenant_id = p_tenant_id
              )
          )
      );

    RETURN jsonb_build_object(
        'tenant_id', p_tenant_id,
        'start_date', p_start_date,
        'end_date', p_end_date,
        'branch_comparison', COALESCE(v_branch_list, '[]'::jsonb)
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_tenant_branch_comparison_analytics(UUID, DATE, DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_branch_comparison_analytics(UUID, DATE, DATE) TO authenticated, service_role;

-- =========================================================================
-- 5. RPC: public.get_tenant_customer_retention_analytics
-- =========================================================================

CREATE OR REPLACE FUNCTION public.get_tenant_customer_retention_analytics(
    p_tenant_id  UUID,
    p_start_date DATE DEFAULT (CURRENT_DATE - INTERVAL '90 days')::DATE,
    p_end_date   DATE DEFAULT CURRENT_DATE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user                   RECORD;
    v_total_unique_customers BIGINT := 0;
    v_first_time_customers   BIGINT := 0;
    v_repeat_customers       BIGINT := 0;
BEGIN
    SELECT role, tenant_id, id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Unauthenticated' USING ERRCODE = '42501';
    END IF;

    IF v_user.role NOT IN ('super_admin', 'tenant_owner', 'staff') THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Role not authorized' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND v_user.tenant_id IS DISTINCT FROM p_tenant_id THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: Tenant mismatch' USING ERRCODE = '42501';
    END IF;

    IF p_end_date < p_start_date OR (p_end_date - p_start_date) > 366 THEN
        RAISE EXCEPTION 'INVALID_DATE_RANGE' USING ERRCODE = 'P0001';
    END IF;

    WITH customer_counts AS (
        SELECT
            a.customer_id,
            count(*) AS appt_count
        FROM public.appointments a
        WHERE a.tenant_id = p_tenant_id
          AND a.customer_id IS NOT NULL
          AND (
              v_user.role IN ('super_admin', 'tenant_owner')
              OR (
                  v_user.role = 'staff' AND a.branch_id IN (
                      SELECT sb.branch_id FROM public.staff_branches sb
                      JOIN public.staff st_own ON st_own.id = sb.staff_id
                      WHERE st_own.user_profile_id = v_user.id AND sb.tenant_id = p_tenant_id
                  )
              )
          )
          AND a.appointment_date >= p_start_date
          AND a.appointment_date <= p_end_date
          AND a.status NOT IN ('cancelled', 'cancelled_by_customer', 'cancelled_by_salon', 'cancelled_by_system')
        GROUP BY a.customer_id
    )
    SELECT
        COALESCE(count(*), 0),
        COALESCE(count(*) FILTER (WHERE appt_count = 1), 0),
        COALESCE(count(*) FILTER (WHERE appt_count > 1), 0)
    INTO
        v_total_unique_customers,
        v_first_time_customers,
        v_repeat_customers
    FROM customer_counts;

    RETURN jsonb_build_object(
        'tenant_id', p_tenant_id,
        'start_date', p_start_date,
        'end_date', p_end_date,
        'retention_metrics', jsonb_build_object(
            'total_active_customers', v_total_unique_customers,
            'first_time_customers', v_first_time_customers,
            'repeat_customers', v_repeat_customers,
            'repeat_booking_rate', CASE WHEN v_total_unique_customers > 0 THEN ROUND((v_repeat_customers::NUMERIC / v_total_unique_customers::NUMERIC) * 100, 2) ELSE 0.00 END
        )
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_tenant_customer_retention_analytics(UUID, DATE, DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_customer_retention_analytics(UUID, DATE, DATE) TO authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260914_phase3_custom_domain_verification_foundation.sql
-- =============================================================================
-- =========================================================================
-- Ported from 72911e4: 20260923_phase3_custom_domain_verification_foundation.sql
-- Conflict-free sequential prefix: 20260914 (ADIM-033 / Faz D1)
-- MIGRATION: Phase 3 Lane 4 Custom Domain Verification Foundation (R1 Hardened)
-- Target: Supabase / PostgreSQL
-- Implementation Authority: LARI-PROGRAM-V2-PHASE3-CUSTOM-DOMAIN-VERIFICATION-20260911-01
-- Correction Authority: LARI-PROGRAM-V2-PHASE3-R1-CORRECTIONS-AND-PHASE4-CONTINUATION-20260911-01
-- Constraints:
--   - public.custom_domains is the single authoritative lifecycle and verification source
--   - public.tenants.custom_domain is synchronized ONLY as a derived verified value (no split-brain)
--   - Reconciles any pre-existing tenants.custom_domain rows into public.custom_domains safely
--   - Explicit application role & tenant checks from public.users_profile (fail closed on NULL)
--   - Only tenant_owner for exact tenant or super_admin may mutate custom domains
--   - Fixed search_path = pg_catalog, public
--   - Sanitized tenant-scoped read RPC (get_tenant_custom_domains) with challenge rows secured
--   - Deterministic test verification (TEST_PROVIDER_SIMULATED_VERIFIED) is service_role only
--     and NEVER satisfies public live tenant-domain resolution (only REAL_PROVIDER_VERIFIED resolves;
--     live DNS/custom domain verification remains EXTERNAL_HOLD until provider connected)
--   - No DNS network calls, no Vercel mutations, no randevulari.com changes
-- =========================================================================

-- 1. CUSTOM DOMAINS TABLE
CREATE TABLE IF NOT EXISTS public.custom_domains (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    requested_hostname TEXT NOT NULL,
    normalized_hostname TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending_verification',
    verification_method TEXT NOT NULL DEFAULT 'dns_txt',
    verification_token TEXT NOT NULL DEFAULT ('lari-verify-' || replace(gen_random_uuid()::text, '-', '')),
    verification_record_name TEXT NOT NULL,
    verification_expected_value TEXT NOT NULL,
    provider_status TEXT NOT NULL DEFAULT 'DOMAIN_PROVIDER_READY_NOT_CONNECTED',
    error_code TEXT NULL,
    error_message TEXT NULL,
    last_checked_at TIMESTAMPTZ NULL,
    verified_at TIMESTAMPTZ NULL,
    expires_at TIMESTAMPTZ NULL,
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_custom_domains_status CHECK (
        status IN (
            'pending_verification',
            'verified',
            'failed',
            'revoked',
            'expired'
        )
    ),
    CONSTRAINT chk_custom_domains_provider_status CHECK (
        provider_status IN (
            'DOMAIN_PROVIDER_READY_NOT_CONNECTED',
            'TEST_PROVIDER_SIMULATED_VERIFIED',
            'TEST_PROVIDER_SIMULATED_FAILED',
            'REAL_PROVIDER_VERIFIED'
        )
    ),
    CONSTRAINT chk_custom_domains_hostname_format CHECK (
        normalized_hostname ~* '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$'
    )
);

-- Unique index ensuring single-domain ownership across tenants (domain conflict protection)
CREATE UNIQUE INDEX IF NOT EXISTS uq_custom_domains_normalized_hostname
    ON public.custom_domains(normalized_hostname);

-- Tenant lookup index
CREATE INDEX IF NOT EXISTS idx_custom_domains_tenant_id
    ON public.custom_domains(tenant_id);

CREATE INDEX IF NOT EXISTS idx_custom_domains_status
    ON public.custom_domains(status);

-- Enable RLS
ALTER TABLE public.custom_domains ENABLE ROW LEVEL SECURITY;

-- Deny raw table access from anon and authenticated; internal / RPC access only
REVOKE ALL ON TABLE public.custom_domains FROM PUBLIC, anon, authenticated;

-- 2. RECONCILE PRE-EXISTING tenants.custom_domain VALUES SAFELY
DO $$
DECLARE
    v_rec RECORD;
BEGIN
    FOR v_rec IN
        SELECT id AS t_id, lower(trim(custom_domain)) AS c_dom
        FROM public.tenants
        WHERE custom_domain IS NOT NULL AND trim(custom_domain) <> ''
          AND lower(trim(custom_domain)) ~* '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$'
          AND lower(trim(custom_domain)) <> 'localhost'
          AND lower(trim(custom_domain)) NOT LIKE '%.localhost'
          AND lower(trim(custom_domain)) NOT LIKE '%.local'
    LOOP
        -- Insert into custom_domains if not already tracked as non-live LEGACY_UNVERIFIED
        INSERT INTO public.custom_domains (
            tenant_id,
            requested_hostname,
            normalized_hostname,
            status,
            verification_method,
            verification_token,
            verification_record_name,
            verification_expected_value,
            provider_status,
            verified_at,
            metadata
        ) VALUES (
            v_rec.t_id,
            v_rec.c_dom,
            v_rec.c_dom,
            'pending_verification',
            'dns_txt',
            'lari-legacy-migrated',
            '_lari-challenge.' || v_rec.c_dom,
            'legacy-migrated-unverified',
            'DOMAIN_PROVIDER_READY_NOT_CONNECTED',
            NULL,
            jsonb_build_object('source', 'legacy_tenants_custom_domain', 'verification_status', 'LEGACY_UNVERIFIED')
        )
        ON CONFLICT (normalized_hostname) DO NOTHING;
    END LOOP;
END;
$$;

-- 3. DOMAIN NORMALIZATION HELPER FUNCTION
CREATE OR REPLACE FUNCTION public.normalize_custom_hostname(p_hostname TEXT)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_norm TEXT;
BEGIN
    IF p_hostname IS NULL OR trim(p_hostname) = '' THEN
        RAISE EXCEPTION 'HOSTNAME_REQUIRED' USING ERRCODE = 'P0001';
    END IF;

    -- Strip leading http:// or https://, port, trailing slashes, whitespace, and lowercase
    v_norm := lower(trim(p_hostname));
    v_norm := regexp_replace(v_norm, '^https?://', '', 'i');
    v_norm := regexp_replace(v_norm, '/.*$', '', 'i');
    v_norm := regexp_replace(v_norm, ':[0-9]+$', '', 'i');
    v_norm := trim(v_norm);

    -- Reject forbidden system/apex domains or localhost
    IF v_norm = 'localhost' OR v_norm LIKE '%.localhost' OR v_norm LIKE '%.local' THEN
        RAISE EXCEPTION 'FORBIDDEN_LOCAL_DOMAIN' USING ERRCODE = 'P0002';
    END IF;

    -- Reject randevulari platform subdomains or apex to prevent hijacking
    IF v_norm = 'randevulari.com' OR v_norm = 'www.randevulari.com' OR v_norm = 'app.randevulari.com' OR v_norm LIKE '%.randevulari.com' THEN
        RAISE EXCEPTION 'FORBIDDEN_PLATFORM_DOMAIN' USING ERRCODE = 'P0003';
    END IF;

    -- Basic domain format check
    IF NOT (v_norm ~* '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$') THEN
        RAISE EXCEPTION 'INVALID_HOSTNAME_FORMAT' USING ERRCODE = 'P0004';
    END IF;

    RETURN v_norm;
END;
$$;

-- 4. REQUEST CUSTOM DOMAIN RPC
CREATE OR REPLACE FUNCTION public.request_custom_domain(
    p_tenant_id UUID,
    p_hostname TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user RECORD;
    v_normalized TEXT;
    v_token TEXT;
    v_rec_name TEXT;
    v_expected_val TEXT;
    v_domain_id UUID;
    v_existing_id UUID;
    v_existing_tenant UUID;
    v_existing_status TEXT;
BEGIN
    -- Fail closed on NULL tenant or caller
    IF p_tenant_id IS NULL THEN
        RAISE EXCEPTION 'TENANT_REQUIRED' USING ERRCODE = '42501';
    END IF;

    -- Authorize against users_profile
    SELECT role, tenant_id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND (v_user.role <> 'tenant_owner' OR v_user.tenant_id <> p_tenant_id) THEN
        RAISE EXCEPTION 'PERMISSION_DENIED: tenant_owner access required' USING ERRCODE = '42501';
    END IF;

    -- Normalize hostname
    v_normalized := public.normalize_custom_hostname(p_hostname);

    -- Check domain conflict / single-domain ownership invariant
    SELECT id, tenant_id, status
    INTO v_existing_id, v_existing_tenant, v_existing_status
    FROM public.custom_domains
    WHERE normalized_hostname = v_normalized;

    IF v_existing_id IS NOT NULL THEN
        IF v_existing_tenant <> p_tenant_id THEN
            RAISE EXCEPTION 'DOMAIN_ALREADY_REGISTERED_BY_OTHER_TENANT' USING ERRCODE = '23505';
        ELSE
            IF v_existing_status = 'verified' THEN
                RAISE EXCEPTION 'DOMAIN_ALREADY_VERIFIED' USING ERRCODE = 'P0005';
            END IF;

            v_token := 'lari-verify-' || replace(gen_random_uuid()::text, '-', '');
            v_rec_name := '_lari-challenge.' || v_normalized;
            v_expected_val := v_token;

            UPDATE public.custom_domains
            SET verification_token = v_token,
                verification_record_name = v_rec_name,
                verification_expected_value = v_expected_val,
                status = 'pending_verification',
                error_code = NULL,
                error_message = NULL,
                updated_at = now()
            WHERE id = v_existing_id
            RETURNING id INTO v_domain_id;

            RETURN jsonb_build_object(
                'success', true,
                'domain_id', v_domain_id,
                'requested_hostname', p_hostname,
                'normalized_hostname', v_normalized,
                'status', 'pending_verification',
                'verification_record_type', 'TXT',
                'verification_record_name', v_rec_name,
                'verification_expected_value', v_expected_val,
                'provider_status', 'DOMAIN_PROVIDER_READY_NOT_CONNECTED',
                'message', 'Verification challenge refreshed'
            );
        END IF;
    END IF;

    v_token := 'lari-verify-' || replace(gen_random_uuid()::text, '-', '');
    v_rec_name := '_lari-challenge.' || v_normalized;
    v_expected_val := v_token;

    INSERT INTO public.custom_domains (
        tenant_id,
        requested_hostname,
        normalized_hostname,
        status,
        verification_method,
        verification_token,
        verification_record_name,
        verification_expected_value,
        provider_status
    ) VALUES (
        p_tenant_id,
        p_hostname,
        v_normalized,
        'pending_verification',
        'dns_txt',
        v_token,
        v_rec_name,
        v_expected_val,
        'DOMAIN_PROVIDER_READY_NOT_CONNECTED'
    )
    RETURNING id INTO v_domain_id;

    RETURN jsonb_build_object(
        'success', true,
        'domain_id', v_domain_id,
        'requested_hostname', p_hostname,
        'normalized_hostname', v_normalized,
        'status', 'pending_verification',
        'verification_record_type', 'TXT',
        'verification_record_name', v_rec_name,
        'verification_expected_value', v_expected_val,
        'provider_status', 'DOMAIN_PROVIDER_READY_NOT_CONNECTED',
        'message', 'Domain registered, pending TXT record verification'
    );
END;
$$;

-- 5. SIMULATED TEST VERIFIER (SERVICE_ROLE ONLY)
-- Deterministic test verification; STRICTLY RESTRICTED to service_role test harnesses.
-- Results in TEST_PROVIDER_SIMULATED_VERIFIED which is NOT live-resolved.
CREATE OR REPLACE FUNCTION public.simulate_verify_custom_domain_for_testing(
    p_tenant_id UUID,
    p_domain_id UUID,
    p_simulated_txt_value TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_domain RECORD;
    v_is_valid BOOLEAN := false;
BEGIN
    SELECT * INTO v_domain
    FROM public.custom_domains
    WHERE id = p_domain_id AND tenant_id = p_tenant_id;

    IF v_domain.id IS NULL THEN
        RAISE EXCEPTION 'DOMAIN_NOT_FOUND' USING ERRCODE = 'P0006';
    END IF;

    IF p_simulated_txt_value IS NOT NULL AND trim(p_simulated_txt_value) = v_domain.verification_expected_value THEN
        v_is_valid := true;
    END IF;

    IF v_is_valid THEN
        UPDATE public.custom_domains
        SET status = 'verified',
            provider_status = 'TEST_PROVIDER_SIMULATED_VERIFIED',
            verified_at = now(),
            last_checked_at = now(),
            error_code = NULL,
            error_message = NULL,
            updated_at = now()
        WHERE id = p_domain_id;

        RETURN jsonb_build_object(
            'success', true,
            'domain_id', p_domain_id,
            'status', 'verified',
            'normalized_hostname', v_domain.normalized_hostname,
            'provider_status', 'TEST_PROVIDER_SIMULATED_VERIFIED',
            'verified_at', now(),
            'message', 'Domain test-verified in simulation mode (not active on live platform)'
        );
    ELSE
        UPDATE public.custom_domains
        SET status = 'failed',
            provider_status = 'TEST_PROVIDER_SIMULATED_FAILED',
            last_checked_at = now(),
            error_code = 'DNS_RECORD_MISMATCH',
            error_message = 'Simulated DNS TXT record did not match expected verification challenge value',
            updated_at = now()
        WHERE id = p_domain_id;

        RETURN jsonb_build_object(
            'success', false,
            'domain_id', p_domain_id,
            'status', 'failed',
            'normalized_hostname', v_domain.normalized_hostname,
            'provider_status', 'TEST_PROVIDER_SIMULATED_FAILED',
            'error_code', 'DNS_RECORD_MISMATCH'
        );
    END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.simulate_verify_custom_domain_for_testing(UUID, UUID, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.simulate_verify_custom_domain_for_testing(UUID, UUID, TEXT) TO service_role;

-- Backward compatible verify_custom_domain for test harnesses
CREATE OR REPLACE FUNCTION public.verify_custom_domain(
    p_tenant_id UUID,
    p_domain_id UUID,
    p_simulated_txt_value TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
    RETURN public.simulate_verify_custom_domain_for_testing(p_tenant_id, p_domain_id, p_simulated_txt_value);
END;
$$;

REVOKE ALL ON FUNCTION public.verify_custom_domain(UUID, UUID, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.verify_custom_domain(UUID, UUID, TEXT) TO service_role;

-- 6. SANITIZED TENANT-SCOPED READ RPC
CREATE OR REPLACE FUNCTION public.get_tenant_custom_domains(
    p_tenant_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user RECORD;
    v_domains JSONB;
BEGIN
    SELECT role, tenant_id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND (v_user.role <> 'tenant_owner' OR v_user.tenant_id <> p_tenant_id) THEN
        RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE = '42501';
    END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'id', cd.id,
            'tenant_id', cd.tenant_id,
            'requested_hostname', cd.requested_hostname,
            'normalized_hostname', cd.normalized_hostname,
            'status', cd.status,
            'provider_status', cd.provider_status,
            'verification_record_type', 'TXT',
            'verification_record_name', cd.verification_record_name,
            'verification_expected_value', cd.verification_expected_value,
            'last_checked_at', cd.last_checked_at,
            'verified_at', cd.verified_at,
            'error_code', cd.error_code,
            'error_message', cd.error_message,
            'created_at', cd.created_at
        )
        ORDER BY cd.created_at DESC
    )
    INTO v_domains
    FROM public.custom_domains cd
    WHERE cd.tenant_id = p_tenant_id;

    RETURN jsonb_build_object('success', true, 'domains', COALESCE(v_domains, '[]'::jsonb));
END;
$$;

REVOKE ALL ON FUNCTION public.get_tenant_custom_domains(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_custom_domains(UUID) TO authenticated, service_role;

-- 7. RECHECK / RENEW CUSTOM DOMAIN STATUS RPC
CREATE OR REPLACE FUNCTION public.recheck_custom_domain(
    p_tenant_id UUID,
    p_domain_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user RECORD;
    v_domain RECORD;
BEGIN
    SELECT role, tenant_id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND (v_user.role <> 'tenant_owner' OR v_user.tenant_id <> p_tenant_id) THEN
        RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_domain
    FROM public.custom_domains
    WHERE id = p_domain_id AND tenant_id = p_tenant_id;

    IF v_domain.id IS NULL THEN
        RAISE EXCEPTION 'DOMAIN_NOT_FOUND' USING ERRCODE = 'P0006';
    END IF;

    RETURN jsonb_build_object(
        'domain_id', v_domain.id,
        'tenant_id', v_domain.tenant_id,
        'requested_hostname', v_domain.requested_hostname,
        'normalized_hostname', v_domain.normalized_hostname,
        'status', v_domain.status,
        'verification_record_name', v_domain.verification_record_name,
        'verification_expected_value', v_domain.verification_expected_value,
        'provider_status', v_domain.provider_status,
        'last_checked_at', v_domain.last_checked_at,
        'verified_at', v_domain.verified_at,
        'error_code', v_domain.error_code,
        'error_message', v_domain.error_message
    );
END;
$$;

-- 8. REMOVE / REVOKE CUSTOM DOMAIN RPC
CREATE OR REPLACE FUNCTION public.remove_custom_domain(
    p_tenant_id UUID,
    p_domain_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user RECORD;
    v_deleted RECORD;
BEGIN
    SELECT role, tenant_id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND (v_user.role <> 'tenant_owner' OR v_user.tenant_id <> p_tenant_id) THEN
        RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE = '42501';
    END IF;

    DELETE FROM public.custom_domains
    WHERE id = p_domain_id AND tenant_id = p_tenant_id
    RETURNING id, normalized_hostname INTO v_deleted;

    IF v_deleted.id IS NULL THEN
        RAISE EXCEPTION 'DOMAIN_NOT_FOUND' USING ERRCODE = 'P0006';
    END IF;

    -- Synchronize derived custom_domain on tenants table (clear if this domain was set)
    UPDATE public.tenants
    SET custom_domain = NULL, updated_at = now()
    WHERE id = p_tenant_id AND lower(custom_domain) = v_deleted.normalized_hostname;

    RETURN jsonb_build_object(
        'success', true,
        'domain_id', v_deleted.id,
        'normalized_hostname', v_deleted.normalized_hostname,
        'status', 'removed'
    );
END;
$$;

-- 9. RESOLVE TENANT BY CUSTOM DOMAIN RPC
-- Resolves ONLY when domain is REAL_PROVIDER_VERIFIED.
-- Test simulation state (TEST_PROVIDER_SIMULATED_VERIFIED) or DOMAIN_PROVIDER_READY_NOT_CONNECTED
-- will NOT be resolved as live public domain truth.
CREATE OR REPLACE FUNCTION public.resolve_tenant_by_custom_domain(
    p_hostname TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_norm TEXT;
    v_record RECORD;
BEGIN
    v_norm := public.normalize_custom_hostname(p_hostname);

    SELECT cd.id, cd.tenant_id, cd.status, cd.normalized_hostname, t.slug AS tenant_slug, t.name AS tenant_name
    INTO v_record
    FROM public.custom_domains cd
    JOIN public.tenants t ON t.id = cd.tenant_id
    WHERE cd.normalized_hostname = v_norm
      AND cd.status = 'verified'
      AND cd.provider_status = 'REAL_PROVIDER_VERIFIED';

    IF v_record.id IS NULL THEN
        RETURN jsonb_build_object(
            'resolved', false,
            'normalized_hostname', v_norm,
            'message', 'Domain not verified by real connected provider'
        );
    END IF;

    RETURN jsonb_build_object(
        'resolved', true,
        'domain_id', v_record.id,
        'tenant_id', v_record.tenant_id,
        'tenant_slug', v_record.tenant_slug,
        'tenant_name', v_record.tenant_name,
        'normalized_hostname', v_record.normalized_hostname
    );
END;
$$;

REVOKE ALL ON FUNCTION public.normalize_custom_hostname(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.request_custom_domain(UUID, TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.recheck_custom_domain(UUID, UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.remove_custom_domain(UUID, UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.resolve_tenant_by_custom_domain(TEXT) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION public.normalize_custom_hostname(TEXT) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.request_custom_domain(UUID, TEXT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.recheck_custom_domain(UUID, UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.remove_custom_domain(UUID, UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.resolve_tenant_by_custom_domain(TEXT) TO anon, authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260915_phase5_scheduling_buffer_parity_hardening.sql
-- =============================================================================
-- ===========================================================================
-- Ported from 72911e4: 20260929_phase5_scheduling_buffer_parity_hardening.sql
-- Conflict-free sequential prefix: 20260915 (ADIM-033 / Faz D1)
-- LARI PROGRAM V2 PHASE 5 ADDITIVE CORRECTION MIGRATION
--
-- Restores canonical Phase 2 asymmetric buffer collision logic (EV055-R3) within evaluate_booking_slot
-- while strictly preserving Phase 3 resource/capacity evaluation, security/branch scoping,
-- timezone past checks, and SECURITY DEFINER execution contracts.
--
-- Root Cause Addressed:
-- Phase 3 resource capacity migration replaced evaluate_booking_slot
-- but omitted the existing appointment's service/default buffer rules from its collision query.
-- This caused requested slots inside an active appointment's buffer_after window to incorrectly pass.
-- ===========================================================================

CREATE OR REPLACE FUNCTION public.evaluate_booking_slot(
    p_tenant_id                UUID,
    p_branch_id                UUID,
    p_service_id               UUID,
    p_staff_id                 UUID,
    p_date                     DATE,
    p_time                     TIME,
    p_exclude_appointment_id   UUID DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, extensions
AS $$
DECLARE
    v_branch_active        BOOLEAN;
    v_branch_tenant        UUID;
    v_svc_tenant           UUID;
    v_svc_active           BOOLEAN;
    v_svc_duration         INTEGER;
    v_svc_branch_match     BOOLEAN;
    v_staff_tenant         UUID;
    v_staff_active         BOOLEAN;
    v_staff_branch_match   BOOLEAN;
    v_staff_svc_match      BOOLEAN;
    v_weekday              INTEGER;
    v_avail_start          TIME;
    v_avail_end            TIME;
    v_req_start            TIMESTAMP;
    v_req_end              TIMESTAMP;
    v_tz                   TEXT := 'Europe/Istanbul';
    v_now_in_tz            TIMESTAMP;
    v_slot_conflict        BOOLEAN;
    v_sched_res            JSONB;
    v_req_buf_before       INTEGER := 0;
    v_req_buf_after        INTEGER := 0;
    v_res_eval             JSONB;
BEGIN
    -- 1. Validate Branch (canonical public.branches)
    SELECT tenant_id, is_active, COALESCE(timezone, 'Europe/Istanbul')
    INTO v_branch_tenant, v_branch_active, v_tz
    FROM public.branches
    WHERE id = p_branch_id;

    IF NOT FOUND OR v_branch_tenant IS DISTINCT FROM p_tenant_id OR v_branch_active IS NOT TRUE THEN
        RETURN jsonb_build_object('allowed', false, 'reason_code', 'invalid_branch', 'duration_minutes', 0);
    END IF;

    -- 2. Validate Service (canonical public.services)
    SELECT tenant_id, active, duration
    INTO v_svc_tenant, v_svc_active, v_svc_duration
    FROM public.services
    WHERE id = p_service_id;

    IF NOT FOUND OR v_svc_tenant IS DISTINCT FROM p_tenant_id OR v_svc_active IS NOT TRUE OR v_svc_duration IS NULL OR v_svc_duration <= 0 THEN
        RETURN jsonb_build_object('allowed', false, 'reason_code', 'invalid_service', 'duration_minutes', 0);
    END IF;

    -- Service-Branch Fail-Closed Check: exact service_branches mapping required
    SELECT EXISTS (
        SELECT 1 FROM public.service_branches 
        WHERE service_id = p_service_id AND branch_id = p_branch_id AND tenant_id = p_tenant_id
    ) INTO v_svc_branch_match;

    IF NOT v_svc_branch_match THEN
        RETURN jsonb_build_object('allowed', false, 'reason_code', 'invalid_service', 'duration_minutes', 0);
    END IF;

    -- 3. Validate Staff (canonical public.staff)
    SELECT tenant_id, active
    INTO v_staff_tenant, v_staff_active
    FROM public.staff
    WHERE id = p_staff_id;

    IF NOT FOUND OR v_staff_tenant IS DISTINCT FROM p_tenant_id OR v_staff_active IS NOT TRUE THEN
        RETURN jsonb_build_object('allowed', false, 'reason_code', 'invalid_staff', 'duration_minutes', 0);
    END IF;

    -- Staff-Branch Fail-Closed Check: exact staff_branches mapping required
    SELECT EXISTS (
        SELECT 1 FROM public.staff_branches 
        WHERE staff_id = p_staff_id AND branch_id = p_branch_id AND tenant_id = p_tenant_id
    ) INTO v_staff_branch_match;

    IF NOT v_staff_branch_match THEN
        RETURN jsonb_build_object('allowed', false, 'reason_code', 'invalid_staff', 'duration_minutes', 0);
    END IF;

    -- 4. Validate Staff-Service Mapping (canonical public.staff_services)
    SELECT EXISTS (
        SELECT 1 FROM public.staff_services
        WHERE staff_id = p_staff_id AND service_id = p_service_id
    ) INTO v_staff_svc_match;

    IF NOT v_staff_svc_match THEN
        RETURN jsonb_build_object('allowed', false, 'reason_code', 'invalid_staff', 'duration_minutes', 0);
    END IF;

    -- 5. Validate Schedule Constraints (EV055-R3: Holidays, Time-Off, Breaks, Buffers)
    IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'evaluate_schedule_constraints') THEN
        v_sched_res := public.evaluate_schedule_constraints(
            p_tenant_id,
            p_branch_id,
            p_service_id,
            p_staff_id,
            p_date,
            p_time,
            v_svc_duration
        );

        IF (v_sched_res->>'allowed')::BOOLEAN IS NOT TRUE THEN
            RETURN jsonb_build_object(
                'allowed', false,
                'reason_code', v_sched_res->>'reason_code',
                'duration_minutes', v_svc_duration
            );
        END IF;

        v_req_buf_before := COALESCE((v_sched_res->>'buffer_before')::INTEGER, 0);
        v_req_buf_after  := COALESCE((v_sched_res->>'buffer_after')::INTEGER, 0);
    END IF;

    -- 6. Validate Availability Rules (ISO Weekday: 1=Mon..7=Sun)
    v_weekday := EXTRACT(DOW FROM p_date)::INTEGER;
    IF v_weekday = 0 THEN v_weekday := 7; END IF;

    SELECT start_time, end_time
    INTO v_avail_start, v_avail_end
    FROM public.availability_rules
    WHERE staff_id = p_staff_id
      AND tenant_id = p_tenant_id
      AND weekday = v_weekday
      AND is_active = true
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('allowed', false, 'reason_code', 'outside_availability', 'duration_minutes', v_svc_duration);
    END IF;

    v_req_start := p_date + p_time;
    v_req_end   := v_req_start + (v_svc_duration || ' minutes')::INTERVAL;

    IF p_time < v_avail_start OR (p_time + (v_svc_duration || ' minutes')::INTERVAL) > v_avail_end THEN
        RETURN jsonb_build_object('allowed', false, 'reason_code', 'outside_availability', 'duration_minutes', v_svc_duration);
    END IF;

    -- 7. Validate Future Slot (Timezone aware)
    v_now_in_tz := now() AT TIME ZONE v_tz;
    IF v_req_start <= v_now_in_tz THEN
        RETURN jsonb_build_object('allowed', false, 'reason_code', 'slot_in_past', 'duration_minutes', v_svc_duration);
    END IF;

    -- 8. Validate Overlapping Active Appointments with Asymmetric Buffer Consideration (EV055-R3 parity)
    -- For each existing active appointment:
    --   occupied_start = a.start - existing_buf_before
    --   occupied_end   = a.end   + existing_buf_after
    -- Collision condition: (requested_start - req_buf_before) < occupied_end
    --                  AND (requested_end   + req_buf_after)  > occupied_start
    SELECT EXISTS (
        SELECT 1
        FROM public.appointments a
        LEFT JOIN public.booking_buffer_rules bbr_exist_svc
            ON bbr_exist_svc.tenant_id = a.tenant_id
           AND bbr_exist_svc.service_id = a.service_id
           AND bbr_exist_svc.is_active = true
        LEFT JOIN public.booking_buffer_rules bbr_exist_def
            ON bbr_exist_def.tenant_id = a.tenant_id
           AND bbr_exist_def.service_id IS NULL
           AND bbr_exist_def.is_active = true
        WHERE a.staff_id = p_staff_id
          AND a.tenant_id = p_tenant_id
          AND a.appointment_date = p_date
          AND (p_exclude_appointment_id IS NULL OR a.id <> p_exclude_appointment_id)
          AND a.status NOT IN ('cancelled', 'cancelled_by_customer', 'cancelled_by_salon', 'cancelled_by_system', 'completed', 'no_show')
          AND (v_req_start - (v_req_buf_before || ' minutes')::INTERVAL) < (
              (a.appointment_date + a.appointment_time) + (COALESCE(a.duration_minutes, 30) || ' minutes')::INTERVAL
              + (COALESCE(bbr_exist_svc.buffer_after, bbr_exist_def.buffer_after, 0) || ' minutes')::INTERVAL
          )
          AND (v_req_end + (v_req_buf_after || ' minutes')::INTERVAL) > (
              (a.appointment_date + a.appointment_time)
              - (COALESCE(bbr_exist_svc.buffer_before, bbr_exist_def.buffer_before, 0) || ' minutes')::INTERVAL
          )
    ) INTO v_slot_conflict;

    IF v_slot_conflict THEN
        RETURN jsonb_build_object('allowed', false, 'reason_code', 'slot_conflict', 'duration_minutes', v_svc_duration);
    END IF;

    -- 9. Validate Resource & Capacity Constraints (LARI Phase 3 Extension)
    v_res_eval := public.evaluate_and_lock_resource_plan(
        p_tenant_id,
        p_branch_id,
        p_service_id,
        p_date,
        p_time,
        v_svc_duration,
        p_exclude_appointment_id,
        FALSE
    );

    IF NOT (v_res_eval->>'allowed')::boolean THEN
        RETURN jsonb_build_object(
            'allowed', false,
            'reason_code', v_res_eval->>'reason_code',
            'duration_minutes', v_svc_duration,
            'resource_details', v_res_eval
        );
    END IF;

    RETURN jsonb_build_object(
        'allowed', true,
        'reason_code', 'ok',
        'duration_minutes', v_svc_duration,
        'slot_start', p_time::text,
        'slot_end', (p_time + (v_svc_duration || ' minutes')::INTERVAL)::text,
        'allocation_plan', v_res_eval->'allocation_plan'
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('allowed', false, 'reason_code', 'temporary_failure', 'duration_minutes', 0);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.evaluate_booking_slot(UUID, UUID, UUID, UUID, DATE, TIME, UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.evaluate_booking_slot(UUID, UUID, UUID, UUID, DATE, TIME, UUID) TO authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260916_phase6_product_inventory_foundation.sql
-- =============================================================================
-- =========================================================================
-- Ported from 72911e4: 20260930_phase6_product_inventory_foundation.sql
-- Conflict-free sequential prefix: 20260916 (ADIM-034 / Faz D2)
-- Description: Phase 6 Node 1 — Product Catalog & Ledger-Safe Branch Inventory Foundation
-- Target: Disposable PostgreSQL database / Supabase
--
-- Directives & Domain Architecture:
-- 1. NO DUPLICATE DOMAIN MODELS:
--    Reuses canonical public.tenants, public.branches, public.staff,
--    public.users_profile, public.audit_events.
-- 2. CANONICAL MONEY MODEL:
--    INTEGER minor units (price_minor_units >= 0, cost_minor_units >= 0).
--    ISO uppercase 3-char currency (CHECK currency ~ '^[A-Z]{3}$').
-- 3. LEDGER-SAFE APPEND-ONLY STOCK MOVEMENTS:
--    Inventory source of truth is public.inventory_movements (immutable append-only).
--    public.inventory_balances caches current stock atomically via RPC transactions.
--    Compensating movements for adjustments and refunds (no historical mutation).
-- 4. CONCURRENCY-SAFE ATOMIC DECREMENTS:
--    Serialized per (branch_id, product_id) via pg_advisory_xact_lock.
--    Enforces available stock >= decrement quantity (fails closed on insufficient stock).
-- 5. IDEMPOTENT MUTATIONS:
--    Unique (tenant_id, idempotency_key) on stock operations prevents double consumption.
--    Idempotency check runs under lock and rejects cross-operation/cross-target reuse.
-- 6. TRUST BOUNDARY:
--    Direct table DML revoked from PUBLIC, anon, and authenticated.
--    Server-authoritative SECURITY DEFINER RPCs require active staff + active users_profile
--    with role IN ('tenant_owner', 'staff').
-- =========================================================================

-- =========================================================================
-- 1. TABLE: public.products (Product Catalog Domain)
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.products (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    name                TEXT NOT NULL CHECK (length(trim(name)) > 0),
    sku                 TEXT NOT NULL CHECK (length(trim(sku)) > 0),
    barcode             TEXT NULL,
    description         TEXT NULL,
    category            TEXT NOT NULL DEFAULT 'general' CHECK (length(trim(category)) > 0),
    brand               TEXT NULL,
    unit_of_measure     TEXT NOT NULL DEFAULT 'piece' CHECK (length(trim(unit_of_measure)) > 0),
    price_minor_units   INTEGER NOT NULL CHECK (price_minor_units >= 0),
    cost_minor_units    INTEGER NOT NULL DEFAULT 0 CHECK (cost_minor_units >= 0),
    currency            VARCHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    tax_rate_basis_points INTEGER NOT NULL DEFAULT 0 CHECK (tax_rate_basis_points >= 0 AND tax_rate_basis_points <= 10000),
    is_active           BOOLEAN NOT NULL DEFAULT true,
    is_retail           BOOLEAN NOT NULL DEFAULT true,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT uq_products_id_tenant UNIQUE (id, tenant_id),
    CONSTRAINT uq_products_tenant_sku UNIQUE (tenant_id, sku)
);

CREATE INDEX IF NOT EXISTS idx_products_tenant_active ON public.products(tenant_id, is_active);
CREATE INDEX IF NOT EXISTS idx_products_tenant_category ON public.products(tenant_id, category);
CREATE INDEX IF NOT EXISTS idx_products_barcode ON public.products(tenant_id, barcode) WHERE barcode IS NOT NULL;

DROP TRIGGER IF EXISTS update_products_modtime ON public.products;
CREATE TRIGGER update_products_modtime
BEFORE UPDATE ON public.products
FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;


-- =========================================================================
-- 2. TABLE: public.inventory_balances (Branch Inventory Projection)
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.inventory_balances (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    branch_id           UUID NOT NULL REFERENCES public.branches(id) ON DELETE CASCADE,
    product_id          UUID NOT NULL,
    on_hand_quantity    INTEGER NOT NULL DEFAULT 0 CHECK (on_hand_quantity >= 0),
    allocated_quantity  INTEGER NOT NULL DEFAULT 0 CHECK (allocated_quantity >= 0),
    reorder_point       INTEGER NOT NULL DEFAULT 0 CHECK (reorder_point >= 0),
    reorder_quantity    INTEGER NOT NULL DEFAULT 0 CHECK (reorder_quantity >= 0),
    last_movement_at    TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT uq_inventory_balances_branch_product UNIQUE (branch_id, product_id),
    CONSTRAINT fk_inventory_balances_product_tenant FOREIGN KEY (product_id, tenant_id)
        REFERENCES public.products(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT chk_inventory_balances_allocated CHECK (allocated_quantity <= on_hand_quantity)
);

CREATE INDEX IF NOT EXISTS idx_inventory_balances_lookup ON public.inventory_balances(tenant_id, branch_id, product_id);

DROP TRIGGER IF EXISTS update_inventory_balances_modtime ON public.inventory_balances;
CREATE TRIGGER update_inventory_balances_modtime
BEFORE UPDATE ON public.inventory_balances
FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE public.inventory_balances ENABLE ROW LEVEL SECURITY;


-- =========================================================================
-- 3. TABLE: public.inventory_movements (Append-Only Stock Ledger)
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.inventory_movements (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    branch_id           UUID NOT NULL REFERENCES public.branches(id) ON DELETE CASCADE,
    product_id          UUID NOT NULL,
    movement_type       TEXT NOT NULL CHECK (
        movement_type IN (
            'receipt',          -- Incoming supplier/purchase delivery
            'sale',             -- Decrement upon customer retail purchase
            'adjustment_gain',  -- Manual stock count correction (+)
            'adjustment_loss',  -- Manual stock count correction / damage (-)
            'return_restock',   -- Customer refund/return returned to inventory
            'transfer_out',     -- Multi-branch transit out
            'transfer_in'       -- Multi-branch transit in
        )
    ),
    quantity            INTEGER NOT NULL CHECK (quantity > 0),
    previous_balance    INTEGER NOT NULL CHECK (previous_balance >= 0),
    new_balance         INTEGER NOT NULL CHECK (new_balance >= 0),
    cost_minor_units    INTEGER NOT NULL DEFAULT 0 CHECK (cost_minor_units >= 0),
    currency            VARCHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    reference_id        TEXT NULL,
    reason              TEXT NULL,
    actor_staff_id      UUID NULL REFERENCES public.staff(id) ON DELETE SET NULL,
    idempotency_key     TEXT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT fk_inventory_movements_product_tenant FOREIGN KEY (product_id, tenant_id)
        REFERENCES public.products(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT uq_inventory_movements_idempotency UNIQUE (tenant_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS idx_inventory_movements_ledger ON public.inventory_movements(tenant_id, branch_id, product_id, created_at DESC);

ALTER TABLE public.inventory_movements ENABLE ROW LEVEL SECURITY;


-- =========================================================================
-- 4. HARDENED TRUST BOUNDARY: REVOKE DIRECT TABLE ACCESS
-- =========================================================================

REVOKE ALL ON TABLE public.products FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.inventory_balances FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.inventory_movements FROM PUBLIC, anon, authenticated;

GRANT SELECT ON TABLE public.products TO authenticated;
GRANT SELECT ON TABLE public.inventory_balances TO authenticated;
GRANT SELECT ON TABLE public.inventory_movements TO authenticated;


-- =========================================================================
-- 5. RLS POLICIES FOR DEFENSE IN DEPTH
-- =========================================================================

DROP POLICY IF EXISTS "Authorized tenant staff can view products" ON public.products;
DROP POLICY IF EXISTS "Authorized tenant staff can view products" ON public.products;
CREATE POLICY "Authorized tenant staff can view products"
ON public.products
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.users_profile up ON up.id = s.user_profile_id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = products.tenant_id
          AND s.active = true
          AND up.tenant_id = s.tenant_id
          AND up.active = true
          AND up.role IN ('tenant_owner', 'staff')
    )
    OR EXISTS (
        SELECT 1 FROM public.users_profile up
        WHERE up.id = auth.uid()
          AND up.tenant_id = products.tenant_id
          AND up.role = 'tenant_owner'
          AND up.active = true
    )
);

DROP POLICY IF EXISTS "Authorized tenant staff can view inventory balances" ON public.inventory_balances;
DROP POLICY IF EXISTS "Authorized tenant staff can view inventory balances" ON public.inventory_balances;
CREATE POLICY "Authorized tenant staff can view inventory balances"
ON public.inventory_balances
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.users_profile up ON up.id = s.user_profile_id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = inventory_balances.tenant_id
          AND s.active = true
          AND up.tenant_id = s.tenant_id
          AND up.active = true
          AND up.role IN ('tenant_owner', 'staff')
    )
    OR EXISTS (
        SELECT 1 FROM public.users_profile up
        WHERE up.id = auth.uid()
          AND up.tenant_id = inventory_balances.tenant_id
          AND up.role = 'tenant_owner'
          AND up.active = true
    )
);

DROP POLICY IF EXISTS "Authorized tenant staff can view inventory movements" ON public.inventory_movements;
DROP POLICY IF EXISTS "Authorized tenant staff can view inventory movements" ON public.inventory_movements;
CREATE POLICY "Authorized tenant staff can view inventory movements"
ON public.inventory_movements
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.users_profile up ON up.id = s.user_profile_id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = inventory_movements.tenant_id
          AND s.active = true
          AND up.tenant_id = s.tenant_id
          AND up.active = true
          AND up.role IN ('tenant_owner', 'staff')
    )
    OR EXISTS (
        SELECT 1 FROM public.users_profile up
        WHERE up.id = auth.uid()
          AND up.tenant_id = inventory_movements.tenant_id
          AND up.role = 'tenant_owner'
          AND up.active = true
    )
);


-- =========================================================================
-- 6. SERVER-AUTHORITATIVE RPC CONTRACTS
-- =========================================================================

-- A. pos_create_product: Register a new product in the catalog
CREATE OR REPLACE FUNCTION public.pos_create_product(
    p_name TEXT,
    p_sku TEXT,
    p_price_minor_units INTEGER,
    p_currency TEXT,
    p_category TEXT DEFAULT 'general',
    p_barcode TEXT DEFAULT NULL,
    p_description TEXT DEFAULT NULL,
    p_brand TEXT DEFAULT NULL,
    p_unit_of_measure TEXT DEFAULT 'piece',
    p_cost_minor_units INTEGER DEFAULT 0,
    p_tax_rate_basis_points INTEGER DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_clean_name TEXT;
    v_clean_sku TEXT;
    v_norm_currency VARCHAR(3);
    v_new_product RECORD;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    v_clean_name := trim(COALESCE(p_name, ''));
    v_clean_sku := upper(trim(COALESCE(p_sku, '')));
    v_norm_currency := upper(trim(COALESCE(p_currency, '')));

    IF length(v_clean_name) = 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Product name cannot be empty.';
    END IF;

    IF length(v_clean_sku) = 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: SKU cannot be empty.';
    END IF;

    IF p_price_minor_units IS NULL OR p_price_minor_units < 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Price minor units must be non-negative.';
    END IF;

    IF COALESCE(p_cost_minor_units, 0) < 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Cost minor units must be non-negative.';
    END IF;

    IF COALESCE(p_tax_rate_basis_points, 0) < 0 OR COALESCE(p_tax_rate_basis_points, 0) > 10000 THEN
        RAISE EXCEPTION 'INVALID_INPUT: tax_rate_basis_points must be between 0 and 10000.';
    END IF;

    IF v_norm_currency !~ '^[A-Z]{3}$' THEN
        RAISE EXCEPTION 'INVALID_INPUT: Invalid ISO 3-character currency.';
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.products
        WHERE tenant_id = v_staff.tenant_id
          AND sku = v_clean_sku
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_SKU: Product with SKU % already exists for tenant.', v_clean_sku;
    END IF;

    INSERT INTO public.products (
        tenant_id,
        name,
        sku,
        barcode,
        description,
        category,
        brand,
        unit_of_measure,
        price_minor_units,
        cost_minor_units,
        currency,
        tax_rate_basis_points,
        is_active,
        is_retail,
        created_at,
        updated_at
    ) VALUES (
        v_staff.tenant_id,
        v_clean_name,
        v_clean_sku,
        nullif(trim(p_barcode), ''),
        nullif(trim(p_description), ''),
        trim(COALESCE(p_category, 'general')),
        nullif(trim(p_brand), ''),
        trim(COALESCE(p_unit_of_measure, 'piece')),
        p_price_minor_units,
        COALESCE(p_cost_minor_units, 0),
        v_norm_currency,
        COALESCE(p_tax_rate_basis_points, 0),
        true,
        true,
        now(),
        now()
    )
    RETURNING * INTO v_new_product;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_staff.tenant_id::text,
        v_caller_uid::text,
        'staff',
        'product_created',
        'products',
        v_new_product.id::text,
        jsonb_build_object(
            'product_id', v_new_product.id,
            'sku', v_new_product.sku,
            'name', v_new_product.name,
            'price_minor_units', v_new_product.price_minor_units,
            'currency', v_new_product.currency
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'product_id', v_new_product.id,
        'tenant_id', v_new_product.tenant_id,
        'sku', v_new_product.sku,
        'name', v_new_product.name,
        'price_minor_units', v_new_product.price_minor_units,
        'currency', v_new_product.currency
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_create_product FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_create_product TO authenticated, service_role;


-- B. pos_record_stock_receipt: Ingest stock into a specific branch
CREATE OR REPLACE FUNCTION public.pos_record_stock_receipt(
    p_branch_id UUID,
    p_product_id UUID,
    p_quantity INTEGER,
    p_cost_minor_units INTEGER DEFAULT 0,
    p_reference_id TEXT DEFAULT NULL,
    p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_product RECORD;
    v_branch RECORD;
    v_clean_key TEXT := nullif(trim(COALESCE(p_idempotency_key, '')), '');
    v_norm_reference TEXT := nullif(trim(COALESCE(p_reference_id, '')), '');
    v_norm_cost INTEGER;
    v_existing_movement RECORD;
    v_prev_balance INTEGER := 0;
    v_new_balance INTEGER := 0;
    v_movement_id UUID;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    IF p_quantity IS NULL OR p_quantity <= 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Quantity must be greater than zero.';
    END IF;

    IF COALESCE(p_cost_minor_units, 0) < 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Cost minor units must be non-negative.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    SELECT * INTO v_product
    FROM public.products
    WHERE id = p_product_id;

    IF v_product.id IS NULL OR v_product.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Product not found or cross-tenant access denied.';
    END IF;

    IF v_product.is_active IS NOT TRUE THEN
        RAISE EXCEPTION 'PRODUCT_INACTIVE: Cannot receive stock for an inactive product.';
    END IF;

    SELECT * INTO v_branch
    FROM public.branches
    WHERE id = p_branch_id;

    IF v_branch.id IS NULL OR v_branch.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Branch not found or cross-tenant access denied.';
    END IF;

    IF v_branch.is_active IS NOT TRUE THEN
        RAISE EXCEPTION 'BRANCH_INACTIVE: Target branch is inactive.';
    END IF;

    v_norm_cost := COALESCE(p_cost_minor_units, v_product.cost_minor_units);

    -- Concurrency lock: serialize inventory operations for this (branch, product)
    PERFORM pg_advisory_xact_lock(
        hashtextextended(v_branch.id::text || ':' || v_product.id::text, 0)
    );

    -- Check idempotency under lock
    IF v_clean_key IS NOT NULL THEN
        SELECT * INTO v_existing_movement
        FROM public.inventory_movements
        WHERE tenant_id = v_staff.tenant_id
          AND idempotency_key = v_clean_key;

        IF v_existing_movement.id IS NOT NULL THEN
            IF v_existing_movement.branch_id <> v_branch.id
               OR v_existing_movement.product_id <> v_product.id
               OR v_existing_movement.movement_type <> 'receipt'
               OR v_existing_movement.quantity <> p_quantity
               OR v_existing_movement.cost_minor_units <> v_norm_cost
               OR v_existing_movement.reference_id IS DISTINCT FROM v_norm_reference
               OR v_existing_movement.reason IS DISTINCT FROM 'stock_receipt' THEN
                RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: Idempotency key already used for a different inventory operation.';
            END IF;

            RETURN jsonb_build_object(
                'success', true,
                'idempotent_replay', true,
                'movement_id', v_existing_movement.id,
                'product_id', v_existing_movement.product_id,
                'branch_id', v_existing_movement.branch_id,
                'quantity', v_existing_movement.quantity,
                'new_balance', v_existing_movement.new_balance
            );
        END IF;
    END IF;

    SELECT on_hand_quantity INTO v_prev_balance
    FROM public.inventory_balances
    WHERE branch_id = v_branch.id
      AND product_id = v_product.id;

    IF NOT FOUND THEN
        v_prev_balance := 0;
        v_new_balance := p_quantity;
        INSERT INTO public.inventory_balances (
            tenant_id,
            branch_id,
            product_id,
            on_hand_quantity,
            allocated_quantity,
            last_movement_at,
            created_at,
            updated_at
        ) VALUES (
            v_staff.tenant_id,
            v_branch.id,
            v_product.id,
            v_new_balance,
            0,
            now(),
            now(),
            now()
        );
    ELSE
        v_new_balance := v_prev_balance + p_quantity;
        UPDATE public.inventory_balances
        SET on_hand_quantity = v_new_balance,
            last_movement_at = now(),
            updated_at = now()
        WHERE branch_id = v_branch.id
          AND product_id = v_product.id;
    END IF;

    INSERT INTO public.inventory_movements (
        tenant_id,
        branch_id,
        product_id,
        movement_type,
        quantity,
        previous_balance,
        new_balance,
        cost_minor_units,
        currency,
        reference_id,
        reason,
        actor_staff_id,
        idempotency_key,
        created_at
    ) VALUES (
        v_staff.tenant_id,
        v_branch.id,
        v_product.id,
        'receipt',
        p_quantity,
        v_prev_balance,
        v_new_balance,
        v_norm_cost,
        v_product.currency,
        v_norm_reference,
        'stock_receipt',
        v_staff.id,
        v_clean_key,
        now()
    )
    RETURNING id INTO v_movement_id;

    RETURN jsonb_build_object(
        'success', true,
        'idempotent_replay', false,
        'movement_id', v_movement_id,
        'branch_id', v_branch.id,
        'product_id', v_product.id,
        'quantity', p_quantity,
        'previous_balance', v_prev_balance,
        'new_balance', v_new_balance
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_record_stock_receipt FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_record_stock_receipt TO authenticated, service_role;


-- C. pos_decrement_stock_for_sale: Concurrency-safe atomic sale decrement
CREATE OR REPLACE FUNCTION public.pos_decrement_stock_for_sale(
    p_branch_id UUID,
    p_product_id UUID,
    p_quantity INTEGER,
    p_reference_id TEXT DEFAULT NULL,
    p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_product RECORD;
    v_branch RECORD;
    v_clean_key TEXT := nullif(trim(COALESCE(p_idempotency_key, '')), '');
    v_norm_reference TEXT := nullif(trim(COALESCE(p_reference_id, '')), '');
    v_existing_movement RECORD;
    v_balance RECORD;
    v_prev_balance INTEGER;
    v_new_balance INTEGER;
    v_movement_id UUID;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    IF p_quantity IS NULL OR p_quantity <= 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Quantity must be greater than zero.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    SELECT * INTO v_product
    FROM public.products
    WHERE id = p_product_id;

    IF v_product.id IS NULL OR v_product.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Product not found or cross-tenant access denied.';
    END IF;

    IF v_product.is_active IS NOT TRUE THEN
        RAISE EXCEPTION 'PRODUCT_INACTIVE: Cannot sell an inactive product.';
    END IF;

    SELECT * INTO v_branch
    FROM public.branches
    WHERE id = p_branch_id;

    IF v_branch.id IS NULL OR v_branch.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Branch not found or cross-tenant access denied.';
    END IF;

    -- Concurrency lock: serialize inventory operations for this (branch, product)
    PERFORM pg_advisory_xact_lock(
        hashtextextended(v_branch.id::text || ':' || v_product.id::text, 0)
    );

    -- Check idempotency under lock
    IF v_clean_key IS NOT NULL THEN
        SELECT * INTO v_existing_movement
        FROM public.inventory_movements
        WHERE tenant_id = v_staff.tenant_id
          AND idempotency_key = v_clean_key;

        IF v_existing_movement.id IS NOT NULL THEN
            IF v_existing_movement.branch_id <> v_branch.id
               OR v_existing_movement.product_id <> v_product.id
               OR v_existing_movement.movement_type <> 'sale'
               OR v_existing_movement.quantity <> p_quantity
               OR v_existing_movement.cost_minor_units <> v_product.cost_minor_units
               OR v_existing_movement.reference_id IS DISTINCT FROM v_norm_reference
               OR v_existing_movement.reason IS DISTINCT FROM 'retail_sale' THEN
                RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: Idempotency key already used for a different inventory operation.';
            END IF;

            RETURN jsonb_build_object(
                'success', true,
                'idempotent_replay', true,
                'movement_id', v_existing_movement.id,
                'product_id', v_existing_movement.product_id,
                'branch_id', v_existing_movement.branch_id,
                'quantity', v_existing_movement.quantity,
                'new_balance', v_existing_movement.new_balance
            );
        END IF;
    END IF;

    SELECT * INTO v_balance
    FROM public.inventory_balances
    WHERE branch_id = v_branch.id
      AND product_id = v_product.id;

    IF v_balance.id IS NULL THEN
        RAISE EXCEPTION 'INSUFFICIENT_STOCK: No stock record exists for this product at the specified branch.';
    END IF;

    v_prev_balance := v_balance.on_hand_quantity;

    IF v_prev_balance < p_quantity THEN
        RAISE EXCEPTION 'INSUFFICIENT_STOCK: Requested quantity % exceeds available on-hand balance %.', p_quantity, v_prev_balance;
    END IF;

    v_new_balance := v_prev_balance - p_quantity;

    UPDATE public.inventory_balances
    SET on_hand_quantity = v_new_balance,
        last_movement_at = now(),
        updated_at = now()
    WHERE id = v_balance.id;

    INSERT INTO public.inventory_movements (
        tenant_id,
        branch_id,
        product_id,
        movement_type,
        quantity,
        previous_balance,
        new_balance,
        cost_minor_units,
        currency,
        reference_id,
        reason,
        actor_staff_id,
        idempotency_key,
        created_at
    ) VALUES (
        v_staff.tenant_id,
        v_branch.id,
        v_product.id,
        'sale',
        p_quantity,
        v_prev_balance,
        v_new_balance,
        v_product.cost_minor_units,
        v_product.currency,
        v_norm_reference,
        'retail_sale',
        v_staff.id,
        v_clean_key,
        now()
    )
    RETURNING id INTO v_movement_id;

    RETURN jsonb_build_object(
        'success', true,
        'idempotent_replay', false,
        'movement_id', v_movement_id,
        'branch_id', v_branch.id,
        'product_id', v_product.id,
        'quantity', p_quantity,
        'previous_balance', v_prev_balance,
        'new_balance', v_new_balance
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_decrement_stock_for_sale FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_decrement_stock_for_sale TO authenticated, service_role;


-- D. pos_adjust_stock: Compensating movement for manual stock audit corrections
CREATE OR REPLACE FUNCTION public.pos_adjust_stock(
    p_branch_id UUID,
    p_product_id UUID,
    p_adjustment_delta INTEGER,
    p_reason TEXT,
    p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_product RECORD;
    v_branch RECORD;
    v_clean_key TEXT := nullif(trim(COALESCE(p_idempotency_key, '')), '');
    v_norm_reason TEXT := trim(COALESCE(p_reason, ''));
    v_existing_movement RECORD;
    v_balance RECORD;
    v_prev_balance INTEGER := 0;
    v_new_balance INTEGER := 0;
    v_movement_type TEXT;
    v_abs_qty INTEGER;
    v_movement_id UUID;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    IF p_adjustment_delta IS NULL OR p_adjustment_delta = 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Adjustment delta must be non-zero.';
    END IF;

    IF p_reason IS NULL OR length(trim(p_reason)) = 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Reason must be provided for stock adjustment.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    SELECT * INTO v_product
    FROM public.products
    WHERE id = p_product_id;

    IF v_product.id IS NULL OR v_product.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Product not found or cross-tenant access denied.';
    END IF;

    SELECT * INTO v_branch
    FROM public.branches
    WHERE id = p_branch_id;

    IF v_branch.id IS NULL OR v_branch.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Branch not found or cross-tenant access denied.';
    END IF;

    IF p_adjustment_delta > 0 THEN
        v_movement_type := 'adjustment_gain';
        v_abs_qty := p_adjustment_delta;
    ELSE
        v_movement_type := 'adjustment_loss';
        v_abs_qty := -p_adjustment_delta;
    END IF;

    -- Concurrency lock: serialize inventory operations for this (branch, product)
    PERFORM pg_advisory_xact_lock(
        hashtextextended(v_branch.id::text || ':' || v_product.id::text, 0)
    );

    -- Check idempotency under lock
    IF v_clean_key IS NOT NULL THEN
        SELECT * INTO v_existing_movement
        FROM public.inventory_movements
        WHERE tenant_id = v_staff.tenant_id
          AND idempotency_key = v_clean_key;

        IF v_existing_movement.id IS NOT NULL THEN
            IF v_existing_movement.branch_id <> v_branch.id
               OR v_existing_movement.product_id <> v_product.id
               OR v_existing_movement.movement_type <> v_movement_type
               OR v_existing_movement.quantity <> v_abs_qty
               OR v_existing_movement.cost_minor_units <> v_product.cost_minor_units
               OR v_existing_movement.reference_id IS DISTINCT FROM NULL
               OR v_existing_movement.reason IS DISTINCT FROM v_norm_reason THEN
                RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: Idempotency key already used for a different inventory operation.';
            END IF;

            RETURN jsonb_build_object(
                'success', true,
                'idempotent_replay', true,
                'movement_id', v_existing_movement.id,
                'product_id', v_existing_movement.product_id,
                'branch_id', v_existing_movement.branch_id,
                'quantity', v_existing_movement.quantity,
                'new_balance', v_existing_movement.new_balance
            );
        END IF;
    END IF;

    SELECT * INTO v_balance
    FROM public.inventory_balances
    WHERE branch_id = v_branch.id
      AND product_id = v_product.id;

    IF v_balance.id IS NULL THEN
        v_prev_balance := 0;
    ELSE
        v_prev_balance := v_balance.on_hand_quantity;
    END IF;

    v_new_balance := v_prev_balance + p_adjustment_delta;
    IF v_new_balance < 0 THEN
        RAISE EXCEPTION 'INSUFFICIENT_STOCK: Adjustment would result in negative stock balance (current: %, delta: %).', v_prev_balance, p_adjustment_delta;
    END IF;

    IF v_balance.id IS NULL THEN
        INSERT INTO public.inventory_balances (
            tenant_id,
            branch_id,
            product_id,
            on_hand_quantity,
            allocated_quantity,
            last_movement_at,
            created_at,
            updated_at
        ) VALUES (
            v_staff.tenant_id,
            v_branch.id,
            v_product.id,
            v_new_balance,
            0,
            now(),
            now(),
            now()
        );
    ELSE
        UPDATE public.inventory_balances
        SET on_hand_quantity = v_new_balance,
            last_movement_at = now(),
            updated_at = now()
        WHERE id = v_balance.id;
    END IF;

    INSERT INTO public.inventory_movements (
        tenant_id,
        branch_id,
        product_id,
        movement_type,
        quantity,
        previous_balance,
        new_balance,
        cost_minor_units,
        currency,
        reference_id,
        reason,
        actor_staff_id,
        idempotency_key,
        created_at
    ) VALUES (
        v_staff.tenant_id,
        v_branch.id,
        v_product.id,
        v_movement_type,
        v_abs_qty,
        v_prev_balance,
        v_new_balance,
        v_product.cost_minor_units,
        v_product.currency,
        NULL,
        v_norm_reason,
        v_staff.id,
        v_clean_key,
        now()
    )
    RETURNING id INTO v_movement_id;

    RETURN jsonb_build_object(
        'success', true,
        'idempotent_replay', false,
        'movement_id', v_movement_id,
        'branch_id', v_branch.id,
        'product_id', v_product.id,
        'delta', p_adjustment_delta,
        'previous_balance', v_prev_balance,
        'new_balance', v_new_balance
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_adjust_stock FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_adjust_stock TO authenticated, service_role;


-- E. pos_return_restock: Compensating return of previously sold inventory
CREATE OR REPLACE FUNCTION public.pos_return_restock(
    p_branch_id UUID,
    p_product_id UUID,
    p_quantity INTEGER,
    p_reason TEXT,
    p_sale_reference_id TEXT DEFAULT NULL,
    p_idempotency_key TEXT DEFAULT NULL
