-- =========================================================================
-- 7. SERVER-AUTHORITATIVE RPC CONTRACTS
-- =========================================================================

-- A. pos_create_supplier: Register a new supplier in the tenant
CREATE OR REPLACE FUNCTION public.pos_create_supplier(
    p_name TEXT,
    p_contact_person TEXT DEFAULT NULL,
    p_email TEXT DEFAULT NULL,
    p_phone TEXT DEFAULT NULL,
    p_tax_identifier TEXT DEFAULT NULL,
    p_address TEXT DEFAULT NULL,
    p_is_active BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_clean_name TEXT;
    v_new_supplier RECORD;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    v_clean_name := trim(COALESCE(p_name, ''));

    IF length(v_clean_name) = 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Supplier name cannot be empty.';
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.suppliers
        WHERE tenant_id = v_staff.tenant_id
          AND lower(trim(name)) = lower(v_clean_name)
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_SUPPLIER: Supplier with name % already exists.', v_clean_name;
    END IF;

    INSERT INTO public.suppliers (
        tenant_id,
        name,
        contact_person,
        email,
        phone,
        tax_identifier,
        address,
        is_active,
        created_at,
        updated_at
    ) VALUES (
        v_staff.tenant_id,
        v_clean_name,
        nullif(trim(p_contact_person), ''),
        nullif(trim(p_email), ''),
        nullif(trim(p_phone), ''),
        nullif(trim(p_tax_identifier), ''),
        nullif(trim(p_address), ''),
        COALESCE(p_is_active, true),
        now(),
        now()
    )
    RETURNING * INTO v_new_supplier;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_staff.tenant_id::text,
        v_caller_uid::text,
        'staff',
        'supplier_created',
        'suppliers',
        v_new_supplier.id::text,
        jsonb_build_object(
            'supplier_id', v_new_supplier.id,
            'name', v_new_supplier.name
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'supplier_id', v_new_supplier.id,
        'tenant_id', v_new_supplier.tenant_id,
        'name', v_new_supplier.name,
        'is_active', v_new_supplier.is_active
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_create_supplier FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_create_supplier TO authenticated, service_role;


-- B. pos_create_purchase_order: Create a PO in draft status with line items
CREATE OR REPLACE FUNCTION public.pos_create_purchase_order(
    p_supplier_id UUID,
    p_destination_branch_id UUID,
    p_currency TEXT,
    p_items JSONB,
    p_notes TEXT DEFAULT NULL,
    p_po_number TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_supplier RECORD;
    v_branch RECORD;
    v_norm_currency VARCHAR(3);
    v_po_number TEXT;
    v_po_id UUID;
    v_total_amount INTEGER := 0;
    v_item RECORD;
    v_product RECORD;
    v_item_count INTEGER := 0;
    v_line_total INTEGER := 0;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Purchase order must contain at least one line item.';
    END IF;

    v_norm_currency := upper(trim(COALESCE(p_currency, '')));
    IF v_norm_currency !~ '^[A-Z]{3}$' THEN
        RAISE EXCEPTION 'INVALID_INPUT: Invalid ISO 3-character currency.';
    END IF;

    SELECT * INTO v_supplier
    FROM public.suppliers
    WHERE id = p_supplier_id;

    IF v_supplier.id IS NULL OR v_supplier.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Supplier not found or cross-tenant access denied.';
    END IF;

    IF v_supplier.is_active IS NOT TRUE THEN
        RAISE EXCEPTION 'SUPPLIER_INACTIVE: Cannot create purchase order for an inactive supplier.';
    END IF;

    SELECT * INTO v_branch
    FROM public.branches
    WHERE id = p_destination_branch_id;

    IF v_branch.id IS NULL OR v_branch.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Branch not found or cross-tenant access denied.';
    END IF;

    IF v_branch.is_active IS NOT TRUE THEN
        RAISE EXCEPTION 'BRANCH_INACTIVE: Destination branch is inactive.';
    END IF;

    IF p_po_number IS NOT NULL AND length(trim(p_po_number)) > 0 THEN
        v_po_number := upper(trim(p_po_number));
    ELSE
        v_po_number := 'PO-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substring(gen_random_uuid()::text, 1, 6));
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.purchase_orders
        WHERE tenant_id = v_staff.tenant_id
          AND po_number = v_po_number
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_PO_NUMBER: Purchase order number % already exists.', v_po_number;
    END IF;

    INSERT INTO public.purchase_orders (
        tenant_id,
        po_number,
        supplier_id,
        destination_branch_id,
        status,
        currency,
        total_amount_minor_units,
        notes,
        created_by_staff_id,
        created_at,
        updated_at
    ) VALUES (
        v_staff.tenant_id,
        v_po_number,
        v_supplier.id,
        v_branch.id,
        'draft',
        v_norm_currency,
        0,
        nullif(trim(p_notes), ''),
        v_staff.id,
        now(),
        now()
    )
    RETURNING id INTO v_po_id;

    FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS (
        product_id UUID,
        quantity INTEGER,
        unit_cost_minor_units INTEGER
    ) LOOP
        v_item_count := v_item_count + 1;

        IF v_item.product_id IS NULL THEN
            RAISE EXCEPTION 'INVALID_INPUT: Line item % missing product_id.', v_item_count;
        END IF;

        IF v_item.quantity IS NULL OR v_item.quantity <= 0 THEN
            RAISE EXCEPTION 'INVALID_INPUT: Quantity for line item % must be positive.', v_item_count;
        END IF;

        IF v_item.unit_cost_minor_units IS NULL OR v_item.unit_cost_minor_units < 0 THEN
            RAISE EXCEPTION 'INVALID_INPUT: Unit cost for line item % must be non-negative.', v_item_count;
        END IF;

        SELECT * INTO v_product
        FROM public.products
        WHERE id = v_item.product_id;

        IF v_product.id IS NULL OR v_product.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Product for line item % does not belong to tenant.', v_item_count;
        END IF;

        IF v_product.is_active IS NOT TRUE THEN
            RAISE EXCEPTION 'PRODUCT_INACTIVE: Product % is inactive.', v_product.sku;
        END IF;

        v_line_total := v_item.quantity * v_item.unit_cost_minor_units;
        v_total_amount := v_total_amount + v_line_total;

        INSERT INTO public.purchase_order_items (
            tenant_id,
            purchase_order_id,
            product_id,
            quantity_ordered,
            quantity_received,
            unit_cost_minor_units,
            total_cost_minor_units,
            created_at,
            updated_at
        ) VALUES (
            v_staff.tenant_id,
            v_po_id,
            v_product.id,
            v_item.quantity,
            0,
            v_item.unit_cost_minor_units,
            v_line_total,
            now(),
            now()
        );
    END LOOP;

    UPDATE public.purchase_orders
    SET total_amount_minor_units = v_total_amount,
        updated_at = now()
    WHERE id = v_po_id;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_staff.tenant_id::text,
        v_caller_uid::text,
        'staff',
        'purchase_order_created',
        'purchase_orders',
        v_po_id::text,
        jsonb_build_object(
            'po_id', v_po_id,
            'po_number', v_po_number,
            'supplier_id', v_supplier.id,
            'destination_branch_id', v_branch.id,
            'item_count', v_item_count,
            'total_amount_minor_units', v_total_amount
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'purchase_order_id', v_po_id,
        'po_number', v_po_number,
        'status', 'draft',
        'supplier_id', v_supplier.id,
        'destination_branch_id', v_branch.id,
        'currency', v_norm_currency,
        'total_amount_minor_units', v_total_amount,
        'item_count', v_item_count
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_create_purchase_order FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_create_purchase_order TO authenticated, service_role;


-- C. pos_approve_purchase_order: Move PO from 'draft' to 'approved'
CREATE OR REPLACE FUNCTION public.pos_approve_purchase_order(
    p_purchase_order_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_po RECORD;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    SELECT * INTO v_po
    FROM public.purchase_orders
    WHERE id = p_purchase_order_id
    FOR UPDATE;

    IF v_po.id IS NULL OR v_po.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Purchase order not found or cross-tenant access denied.';
    END IF;

    IF v_po.status <> 'draft' THEN
        RAISE EXCEPTION 'INVALID_STATE: Only draft purchase orders can be approved (current status: %).', v_po.status;
    END IF;

    UPDATE public.purchase_orders
    SET status = 'approved',
        approved_by_staff_id = v_staff.id,
        approved_at = now(),
        updated_at = now()
    WHERE id = v_po.id;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_staff.tenant_id::text,
        v_caller_uid::text,
        'staff',
        'purchase_order_approved',
        'purchase_orders',
        v_po.id::text,
        jsonb_build_object(
            'po_id', v_po.id,
            'approved_by', v_staff.id
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'purchase_order_id', v_po.id,
        'status', 'approved'
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_approve_purchase_order FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_approve_purchase_order TO authenticated, service_role;


-- D. pos_cancel_purchase_order: Cancel a PO (only allowed if no items received)
CREATE OR REPLACE FUNCTION public.pos_cancel_purchase_order(
    p_purchase_order_id UUID,
    p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_po RECORD;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    SELECT * INTO v_po
    FROM public.purchase_orders
    WHERE id = p_purchase_order_id
    FOR UPDATE;

    IF v_po.id IS NULL OR v_po.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Purchase order not found or cross-tenant access denied.';
    END IF;

    IF v_po.status = 'cancelled' THEN
        RAISE EXCEPTION 'INVALID_STATE: Purchase order is already cancelled.';
    END IF;

    IF v_po.status IN ('partially_received', 'received') THEN
        RAISE EXCEPTION 'INVALID_STATE: Cannot cancel purchase order with received goods (status: %).', v_po.status;
    END IF;

    UPDATE public.purchase_orders
    SET status = 'cancelled',
        cancelled_by_staff_id = v_staff.id,
        cancelled_at = now(),
        cancellation_reason = nullif(trim(p_reason), ''),
        updated_at = now()
    WHERE id = v_po.id;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_staff.tenant_id::text,
        v_caller_uid::text,
        'staff',
        'purchase_order_cancelled',
        'purchase_orders',
        v_po.id::text,
        jsonb_build_object(
            'po_id', v_po.id,
            'reason', p_reason
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'purchase_order_id', v_po.id,
        'status', 'cancelled'
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_cancel_purchase_order FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_cancel_purchase_order TO authenticated, service_role;


-- E. pos_receive_purchase_order_items: Atomic, concurrency-safe receiving
CREATE OR REPLACE FUNCTION public.pos_receive_purchase_order_items(
    p_purchase_order_id UUID,
    p_receipts JSONB,
    p_idempotency_key TEXT DEFAULT NULL,
    p_notes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_po RECORD;
    v_clean_key TEXT := nullif(trim(COALESCE(p_idempotency_key, '')), '');
    v_existing_event RECORD;
    v_incoming_canonical JSONB;
    v_existing_canonical JSONB;
    v_receipt RECORD;
    v_item RECORD;
    v_product RECORD;
    v_branch RECORD;
    v_new_item_received INTEGER;
    v_movement_id UUID;
    v_prev_stock INTEGER := 0;
    v_new_stock INTEGER := 0;
    v_balance RECORD;
    v_all_received BOOLEAN := true;
    v_any_received BOOLEAN := false;
    v_items_processed INTEGER := 0;
    v_total_units_received INTEGER := 0;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    IF p_receipts IS NULL OR jsonb_typeof(p_receipts) <> 'array' OR jsonb_array_length(p_receipts) = 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Receiving payload must contain at least one item receipt.';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_receipts) AS r(po_item_id UUID, quantity_received INTEGER)
        WHERE r.po_item_id IS NULL OR r.quantity_received IS NULL OR r.quantity_received <= 0
    ) THEN
        RAISE EXCEPTION 'INVALID_INPUT: Each receipt item must include a valid po_item_id and positive quantity_received.';
    END IF;

    -- Concurrency lock: serialize PO receiving operations via transaction advisory lock
    PERFORM pg_advisory_xact_lock(
        hashtextextended('po_receive:' || p_purchase_order_id::text, 0)
    );

    -- Check idempotency under lock
    IF v_clean_key IS NOT NULL THEN
        SELECT * INTO v_existing_event
        FROM public.purchase_order_receiving_events
        WHERE tenant_id = v_staff.tenant_id
          AND idempotency_key = v_clean_key
        LIMIT 1;

        IF v_existing_event.id IS NOT NULL THEN
            IF v_existing_event.purchase_order_id <> p_purchase_order_id THEN
                RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: Receiving idempotency key already used for a different purchase order.';
            END IF;

            SELECT COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'po_item_id', r.po_item_id,
                        'quantity_received', r.quantity_received
                    )
                    ORDER BY r.po_item_id ASC, r.quantity_received ASC
                ),
                '[]'::jsonb
            )
            INTO v_incoming_canonical
            FROM jsonb_to_recordset(p_receipts) AS r(po_item_id UUID, quantity_received INTEGER);

            SELECT COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'po_item_id', e.po_item_id,
                        'quantity_received', e.quantity_received
                    )
                    ORDER BY e.po_item_id ASC, e.quantity_received ASC
                ),
                '[]'::jsonb
            )
            INTO v_existing_canonical
            FROM public.purchase_order_receiving_events e
            WHERE e.tenant_id = v_staff.tenant_id
              AND e.idempotency_key = v_clean_key;

            IF v_incoming_canonical IS DISTINCT FROM v_existing_canonical THEN
                RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: Receiving idempotency key already used for a different receiving payload.';
            END IF;

            SELECT status INTO v_po FROM public.purchase_orders WHERE id = p_purchase_order_id;
            RETURN jsonb_build_object(
                'success', true,
                'idempotent_replay', true,
                'purchase_order_id', p_purchase_order_id,
                'status', v_po.status,
                'message', 'Receipt operation already recorded with idempotency key.'
            );
        END IF;
    END IF;

    SELECT * INTO v_po
    FROM public.purchase_orders
    WHERE id = p_purchase_order_id
    FOR UPDATE;

    IF v_po.id IS NULL OR v_po.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Purchase order not found or cross-tenant access denied.';
    END IF;

    IF v_po.status = 'cancelled' THEN
        RAISE EXCEPTION 'INVALID_STATE: Cannot receive items on a cancelled purchase order.';
    END IF;

    IF v_po.status = 'draft' THEN
        RAISE EXCEPTION 'INVALID_STATE: Purchase order must be approved before receiving items.';
    END IF;

    IF v_po.status = 'received' THEN
        RAISE EXCEPTION 'INVALID_STATE: Purchase order is already fully received.';
    END IF;

    SELECT * INTO v_branch
    FROM public.branches
    WHERE id = v_po.destination_branch_id;

    IF v_branch.id IS NULL OR v_branch.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Destination branch cross-tenant violation.';
    END IF;

    IF v_branch.is_active IS NOT TRUE THEN
        RAISE EXCEPTION 'BRANCH_INACTIVE: Destination branch is inactive.';
    END IF;

    FOR v_receipt IN SELECT * FROM jsonb_to_recordset(p_receipts) AS (
        po_item_id UUID,
        quantity_received INTEGER
    ) LOOP
        v_items_processed := v_items_processed + 1;

        IF v_receipt.po_item_id IS NULL THEN
            RAISE EXCEPTION 'INVALID_INPUT: Missing po_item_id in receipt item %.', v_items_processed;
        END IF;

        IF v_receipt.quantity_received IS NULL OR v_receipt.quantity_received <= 0 THEN
            RAISE EXCEPTION 'INVALID_INPUT: Received quantity must be greater than zero in item %.', v_items_processed;
        END IF;

        SELECT * INTO v_item
        FROM public.purchase_order_items
        WHERE id = v_receipt.po_item_id
          AND purchase_order_id = v_po.id
          AND tenant_id = v_staff.tenant_id
        FOR UPDATE;

        IF v_item.id IS NULL THEN
            RAISE EXCEPTION 'INVALID_INPUT: Purchase order line item % not found on this PO.', v_receipt.po_item_id;
        END IF;

        v_new_item_received := v_item.quantity_received + v_receipt.quantity_received;
        IF v_new_item_received > v_item.quantity_ordered THEN
            RAISE EXCEPTION 'OVER_RECEIPT: Receiving % exceeds remaining ordered quantity (ordered: %, already received: %, remaining: %).',
                v_receipt.quantity_received,
                v_item.quantity_ordered,
                v_item.quantity_received,
                (v_item.quantity_ordered - v_item.quantity_received);
        END IF;

        SELECT * INTO v_product
        FROM public.products
        WHERE id = v_item.product_id;

        IF v_product.id IS NULL OR v_product.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Product cross-tenant violation.';
        END IF;

        PERFORM pg_advisory_xact_lock(
            hashtextextended(v_branch.id::text || ':' || v_product.id::text, 0)
        );

        SELECT * INTO v_balance
        FROM public.inventory_balances
        WHERE branch_id = v_branch.id
          AND product_id = v_product.id;

        IF v_balance.id IS NULL THEN
            v_prev_stock := 0;
            v_new_stock := v_receipt.quantity_received;
            INSERT INTO public.inventory_balances (
                tenant_id,
                branch_id,
                product_id,
                on_hand_quantity,
                allocated_quantity,
                last_movement_at,
                created_at,
                updated_at
            ) VALUES (
                v_staff.tenant_id,
                v_branch.id,
                v_product.id,
                v_new_stock,
                0,
                now(),
                now(),
                now()
            );
        ELSE
            v_prev_stock := v_balance.on_hand_quantity;
            v_new_stock := v_prev_stock + v_receipt.quantity_received;
            UPDATE public.inventory_balances
            SET on_hand_quantity = v_new_stock,
                last_movement_at = now(),
                updated_at = now()
            WHERE id = v_balance.id;
        END IF;

        INSERT INTO public.inventory_movements (
            tenant_id,
            branch_id,
            product_id,
            movement_type,
            quantity,
            previous_balance,
            new_balance,
            cost_minor_units,
            currency,
            reference_id,
            reason,
            actor_staff_id,
            idempotency_key,
            created_at
        ) VALUES (
            v_staff.tenant_id,
            v_branch.id,
            v_product.id,
            'receipt',
            v_receipt.quantity_received,
            v_prev_stock,
            v_new_stock,
            v_item.unit_cost_minor_units,
            v_po.currency,
            v_po.po_number,
            'purchase_order_receipt',
            v_staff.id,
            CASE WHEN v_clean_key IS NOT NULL THEN v_clean_key || ':' || v_item.id::text ELSE NULL END,
            now()
        )
        RETURNING id INTO v_movement_id;

        UPDATE public.purchase_order_items
        SET quantity_received = v_new_item_received,
            updated_at = now()
        WHERE id = v_item.id;

        INSERT INTO public.purchase_order_receiving_events (
            tenant_id,
            purchase_order_id,
            po_item_id,
            product_id,
            branch_id,
            quantity_received,
            inventory_movement_id,
            receiver_staff_id,
            idempotency_key,
            notes,
            created_at
        ) VALUES (
            v_staff.tenant_id,
            v_po.id,
            v_item.id,
            v_product.id,
            v_branch.id,
            v_receipt.quantity_received,
            v_movement_id,
            v_staff.id,
            v_clean_key,
            nullif(trim(p_notes), ''),
            now()
        );

        v_total_units_received := v_total_units_received + v_receipt.quantity_received;
    END LOOP;

    SELECT
        bool_and(quantity_received = quantity_ordered),
        bool_or(quantity_received > 0)
    INTO v_all_received, v_any_received
    FROM public.purchase_order_items
    WHERE purchase_order_id = v_po.id;

    IF v_all_received THEN
        UPDATE public.purchase_orders
        SET status = 'received',
            updated_at = now()
        WHERE id = v_po.id;
    ELSIF v_any_received THEN
        UPDATE public.purchase_orders
        SET status = 'partially_received',
            updated_at = now()
        WHERE id = v_po.id;
    END IF;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_staff.tenant_id::text,
        v_caller_uid::text,
        'staff',
        'purchase_order_received',
        'purchase_orders',
        v_po.id::text,
        jsonb_build_object(
            'po_id', v_po.id,
            'po_number', v_po.po_number,
            'total_units_received', v_total_units_received,
            'status', CASE WHEN v_all_received THEN 'received' ELSE 'partially_received' END
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'idempotent_replay', false,
        'purchase_order_id', v_po.id,
        'po_number', v_po.po_number,
        'status', CASE WHEN v_all_received THEN 'received' ELSE 'partially_received' END,
        'total_units_received', v_total_units_received,
        'items_processed', v_items_processed
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_receive_purchase_order_items FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_receive_purchase_order_items TO authenticated, service_role;


-- F. pos_get_purchase_order: Retrieve PO details with line items and receiving
CREATE OR REPLACE FUNCTION public.pos_get_purchase_order(
    p_purchase_order_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_po RECORD;
    v_supplier RECORD;
    v_branch RECORD;
    v_items JSONB;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    SELECT * INTO v_po
    FROM public.purchase_orders
    WHERE id = p_purchase_order_id;

    IF v_po.id IS NULL OR v_po.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Purchase order not found or cross-tenant access denied.';
    END IF;

    SELECT * INTO v_supplier FROM public.suppliers WHERE id = v_po.supplier_id;
    SELECT * INTO v_branch FROM public.branches WHERE id = v_po.destination_branch_id;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'item_id', poi.id,
            'product_id', poi.product_id,
            'product_name', p.name,
            'sku', p.sku,
            'quantity_ordered', poi.quantity_ordered,
            'quantity_received', poi.quantity_received,
            'remaining_quantity', (poi.quantity_ordered - poi.quantity_received),
            'unit_cost_minor_units', poi.unit_cost_minor_units,
            'total_cost_minor_units', poi.total_cost_minor_units
        )
        ORDER BY p.name ASC
    ), '[]'::jsonb)
    INTO v_items
    FROM public.purchase_order_items poi
    JOIN public.products p ON p.id = poi.product_id
    WHERE poi.purchase_order_id = v_po.id;

    RETURN jsonb_build_object(
        'success', true,
        'purchase_order_id', v_po.id,
        'po_number', v_po.po_number,
        'status', v_po.status,
        'supplier', jsonb_build_object(
            'id', v_supplier.id,
            'name', v_supplier.name
        ),
        'destination_branch', jsonb_build_object(
            'id', v_branch.id,
            'name', v_branch.name
        ),
        'currency', v_po.currency,
        'total_amount_minor_units', v_po.total_amount_minor_units,
        'notes', v_po.notes,
        'items', v_items,
        'created_at', v_po.created_at,
        'updated_at', v_po.updated_at
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_get_purchase_order FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_get_purchase_order TO authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260918_phase6_node3_pos_mixed_cart_checkout.sql
-- =============================================================================
-- =========================================================================
-- Ported from 72911e4: 20261002_phase6_node3_pos_mixed_cart_checkout.sql
-- Conflict-free sequential prefix: 20260918 (ADIM-034 / Faz D2)
-- Description: Phase 6 Node 3 — POS Mixed Cart, Multi-Branch Stock Allocation & Checkout Foundation
-- Target: Disposable PostgreSQL database / Supabase
--
-- Directives & Domain Architecture:
-- 1. NO DUPLICATE DOMAIN MODELS:
--    Reuses canonical public.tenants, public.branches, public.staff, public.customers,
--    public.appointments, public.services, public.products,
--    public.inventory_balances, public.inventory_movements.
--    Note: package_id is stored as UUID NULL; FK to service_package_definitions is deferred
--    until ADIM-035 (Faz D3) provisions service_package_definitions, and runtime package
--    resolution uses to_regclass('public.service_package_definitions') fail-closed guard.
-- 2. MIXED CART MODEL:
--    A single transaction can compose services, products/retail items, packages, and custom items.
--    Item types: 'service', 'product', 'package', 'custom'.
-- 3. CANONICAL MONEY & PRICING:
--    INTEGER minor units (unit_price_minor_units >= 0, discount_minor_units >= 0, line_total_minor_units >= 0).
--    ISO uppercase 3-char currency (CHECK currency ~ '^[A-Z]{3}$').
--    Schema truth: public.services.price is INTEGER major currency units -> converted via price * 100.
-- 4. INVENTORY INTEGRATION INVARIANT:
--    Checkout automatically registers 'sale' ledger movements in public.inventory_movements,
--    updates public.inventory_balances (on_hand_quantity) per branch,
--    and acquires pg_advisory_xact_lock(hashtextextended(branch_id || ':' || product_id, 0)).
-- 5. PAYMENT & ORDER LIFECYCLE:
--    Order statuses: 'open', 'completed', 'voided', 'refunded'.
--    Payment methods: 'cash', 'card_present', 'card_terminal_adapter', 'customer_wallet', 'external'.
--    Live terminal PSP / wallet ledger remains EXTERNAL_HOLD / deferred until Faz D3.
-- 6. IDEMPOTENT ATOMIC CHECKOUT:
--    Unique (tenant_id, idempotency_key) on orders prevents double-charging and duplicate stock decrement.
--    Lock acquired before idempotency evaluation; cross-order key reuse raises IDEMPOTENCY_CONFLICT.
-- 7. TRUST BOUNDARY:
--    Direct table DML revoked from PUBLIC, anon, and authenticated.
--    SELECT permitted to authenticated with RLS defense-in-depth.
--    Server-authoritative SECURITY DEFINER RPCs require active staff + active users_profile
--    with role IN ('tenant_owner', 'staff').
-- =========================================================================

-- =========================================================================
-- 1. TABLE: public.pos_orders (Point of Sale Order Domain)
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.pos_orders (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id               UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    branch_id               UUID NOT NULL REFERENCES public.branches(id) ON DELETE CASCADE,
    order_number            TEXT NOT NULL CHECK (length(trim(order_number)) > 0),
    customer_id             UUID NULL REFERENCES public.customers(id) ON DELETE SET NULL,
    staff_id                UUID NOT NULL REFERENCES public.staff(id) ON DELETE RESTRICT,
    status                  TEXT NOT NULL DEFAULT 'open' CHECK (
        status IN ('open', 'completed', 'voided', 'refunded')
    ),
    currency                VARCHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    subtotal_minor_units    INTEGER NOT NULL DEFAULT 0 CHECK (subtotal_minor_units >= 0),
    discount_minor_units    INTEGER NOT NULL DEFAULT 0 CHECK (discount_minor_units >= 0),
    tax_minor_units         INTEGER NOT NULL DEFAULT 0 CHECK (tax_minor_units >= 0),
    tip_minor_units         INTEGER NOT NULL DEFAULT 0 CHECK (tip_minor_units >= 0),
    total_minor_units       INTEGER NOT NULL DEFAULT 0 CHECK (total_minor_units >= 0),
    notes                   TEXT NULL,
    idempotency_key         TEXT NULL,
    completed_at            TIMESTAMPTZ NULL,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT uq_pos_orders_id_tenant UNIQUE (id, tenant_id),
    CONSTRAINT uq_pos_orders_tenant_order_number UNIQUE (tenant_id, order_number),
    CONSTRAINT uq_pos_orders_tenant_idempotency UNIQUE (tenant_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS idx_pos_orders_tenant_branch ON public.pos_orders(tenant_id, branch_id, status);
CREATE INDEX IF NOT EXISTS idx_pos_orders_customer ON public.pos_orders(tenant_id, customer_id);

DROP TRIGGER IF EXISTS update_pos_orders_modtime ON public.pos_orders;
CREATE TRIGGER update_pos_orders_modtime
BEFORE UPDATE ON public.pos_orders
FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE public.pos_orders ENABLE ROW LEVEL SECURITY;


-- =========================================================================
-- 2. TABLE: public.pos_order_items (Mixed Cart Line Items)
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.pos_order_items (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id                UUID NOT NULL,
    tenant_id               UUID NOT NULL,
    item_type               TEXT NOT NULL CHECK (
        item_type IN ('service', 'product', 'package', 'custom')
    ),
    service_id              UUID NULL REFERENCES public.services(id) ON DELETE SET NULL,
    product_id              UUID NULL,
    package_id              UUID NULL,
    appointment_id          UUID NULL REFERENCES public.appointments(id) ON DELETE SET NULL,
    item_name               TEXT NOT NULL CHECK (length(trim(item_name)) > 0),
    sku                     TEXT NULL,
    quantity                INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0),
    unit_price_minor_units  INTEGER NOT NULL CHECK (unit_price_minor_units >= 0),
    discount_minor_units    INTEGER NOT NULL DEFAULT 0 CHECK (discount_minor_units >= 0),
    tax_rate_basis_points   INTEGER NOT NULL DEFAULT 0 CHECK (tax_rate_basis_points >= 0 AND tax_rate_basis_points <= 10000),
    tax_minor_units         INTEGER NOT NULL DEFAULT 0 CHECK (tax_minor_units >= 0),
    line_total_minor_units  INTEGER NOT NULL CHECK (line_total_minor_units >= 0),
    performing_staff_id     UUID NULL REFERENCES public.staff(id) ON DELETE SET NULL,
    inventory_movement_id   UUID NULL,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT fk_pos_order_items_order FOREIGN KEY (order_id, tenant_id)
        REFERENCES public.pos_orders(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT fk_pos_order_items_product FOREIGN KEY (product_id, tenant_id)
        REFERENCES public.products(id, tenant_id) ON DELETE RESTRICT,
    CONSTRAINT chk_pos_items_product_ref CHECK (
        (item_type = 'product' AND product_id IS NOT NULL) OR
        (item_type <> 'product')
    )
);

CREATE INDEX IF NOT EXISTS idx_pos_order_items_order ON public.pos_order_items(order_id);
CREATE INDEX IF NOT EXISTS idx_pos_order_items_product ON public.pos_order_items(tenant_id, product_id);

ALTER TABLE public.pos_order_items ENABLE ROW LEVEL SECURITY;


-- =========================================================================
-- 3. TABLE: public.pos_order_payments (Multi-Tender Payments)
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.pos_order_payments (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id                UUID NOT NULL,
    tenant_id               UUID NOT NULL,
    payment_method          TEXT NOT NULL CHECK (
        payment_method IN ('cash', 'card_present', 'card_terminal_adapter', 'customer_wallet', 'external')
    ),
    amount_minor_units      INTEGER NOT NULL CHECK (amount_minor_units > 0),
    currency                VARCHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    reference_identifier    TEXT NULL,
    staff_id                UUID NOT NULL REFERENCES public.staff(id) ON DELETE RESTRICT,
    notes                   TEXT NULL,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT fk_pos_order_payments_order FOREIGN KEY (order_id, tenant_id)
        REFERENCES public.pos_orders(id, tenant_id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_pos_order_payments_order ON public.pos_order_payments(order_id);

ALTER TABLE public.pos_order_payments ENABLE ROW LEVEL SECURITY;


-- =========================================================================
-- 4. HARDENED TRUST BOUNDARY: REVOKE DIRECT TABLE MUTATIONS
-- =========================================================================

REVOKE ALL ON TABLE public.pos_orders FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.pos_order_items FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.pos_order_payments FROM PUBLIC, anon, authenticated;

GRANT SELECT ON TABLE public.pos_orders TO authenticated;
GRANT SELECT ON TABLE public.pos_order_items TO authenticated;
GRANT SELECT ON TABLE public.pos_order_payments TO authenticated;


-- =========================================================================
-- 5. RLS POLICIES FOR DEFENSE IN DEPTH
-- =========================================================================

DROP POLICY IF EXISTS "Authorized tenant staff can view pos orders" ON public.pos_orders;
DROP POLICY IF EXISTS "Authorized tenant staff can view pos orders" ON public.pos_orders;
CREATE POLICY "Authorized tenant staff can view pos orders"
ON public.pos_orders
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.users_profile up ON up.id = s.user_profile_id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = pos_orders.tenant_id
          AND s.active = true
          AND up.tenant_id = s.tenant_id
          AND up.active = true
          AND up.role IN ('tenant_owner', 'staff')
    )
    OR EXISTS (
        SELECT 1 FROM public.users_profile up
        WHERE up.id = auth.uid()
          AND up.tenant_id = pos_orders.tenant_id
          AND up.role = 'tenant_owner'
          AND up.active = true
    )
);

DROP POLICY IF EXISTS "Authorized tenant staff can view pos order items" ON public.pos_order_items;
DROP POLICY IF EXISTS "Authorized tenant staff can view pos order items" ON public.pos_order_items;
CREATE POLICY "Authorized tenant staff can view pos order items"
ON public.pos_order_items
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.users_profile up ON up.id = s.user_profile_id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = pos_order_items.tenant_id
          AND s.active = true
          AND up.tenant_id = s.tenant_id
          AND up.active = true
          AND up.role IN ('tenant_owner', 'staff')
    )
    OR EXISTS (
        SELECT 1 FROM public.users_profile up
        WHERE up.id = auth.uid()
          AND up.tenant_id = pos_order_items.tenant_id
          AND up.role = 'tenant_owner'
          AND up.active = true
    )
);

DROP POLICY IF EXISTS "Authorized tenant staff can view pos order payments" ON public.pos_order_payments;
DROP POLICY IF EXISTS "Authorized tenant staff can view pos order payments" ON public.pos_order_payments;
CREATE POLICY "Authorized tenant staff can view pos order payments"
ON public.pos_order_payments
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.users_profile up ON up.id = s.user_profile_id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = pos_order_payments.tenant_id
          AND s.active = true
          AND up.tenant_id = s.tenant_id
          AND up.active = true
          AND up.role IN ('tenant_owner', 'staff')
    )
    OR EXISTS (
        SELECT 1 FROM public.users_profile up
        WHERE up.id = auth.uid()
          AND up.tenant_id = pos_order_payments.tenant_id
          AND up.role = 'tenant_owner'
          AND up.active = true
    )
);


-- =========================================================================
-- 6. SERVER-AUTHORITATIVE RPC CONTRACTS
-- =========================================================================

-- A. pos_create_order: Create an open POS order / cart
CREATE OR REPLACE FUNCTION public.pos_create_order(
    p_branch_id UUID,
    p_currency TEXT,
    p_customer_id UUID DEFAULT NULL,
    p_notes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_branch RECORD;
    v_customer RECORD;
    v_order_id UUID;
    v_order_number TEXT;
    v_clean_currency TEXT := upper(trim(COALESCE(p_currency, '')));
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    IF v_clean_currency !~ '^[A-Z]{3}$' THEN
        RAISE EXCEPTION 'INVALID_INPUT: Currency must be a 3-letter uppercase ISO code.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    SELECT * INTO v_branch
    FROM public.branches
    WHERE id = p_branch_id;

    IF v_branch.id IS NULL OR v_branch.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Branch not found or cross-tenant access denied.';
    END IF;

    IF v_branch.is_active IS NOT TRUE THEN
        RAISE EXCEPTION 'BRANCH_INACTIVE: Target branch is inactive.';
    END IF;

    IF p_customer_id IS NOT NULL THEN
        SELECT * INTO v_customer
        FROM public.customers
        WHERE id = p_customer_id;

        IF v_customer.id IS NULL OR v_customer.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Customer not found or cross-tenant access denied.';
        END IF;
    END IF;

    v_order_number := 'ORD-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(md5(gen_random_uuid()::text), 1, 6));

    INSERT INTO public.pos_orders (
        tenant_id,
        branch_id,
        order_number,
        customer_id,
        staff_id,
        status,
        currency,
        subtotal_minor_units,
        discount_minor_units,
        tax_minor_units,
        tip_minor_units,
        total_minor_units,
        notes,
        created_at,
        updated_at
    ) VALUES (
        v_staff.tenant_id,
        v_branch.id,
        v_order_number,
        p_customer_id,
        v_staff.id,
        'open',
        v_clean_currency,
        0, 0, 0, 0, 0,
        nullif(trim(p_notes), ''),
        now(),
        now()
    )
    RETURNING id INTO v_order_id;

    RETURN jsonb_build_object(
        'success', true,
        'order_id', v_order_id,
        'order_number', v_order_number,
        'status', 'open',
        'currency', v_clean_currency
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_create_order FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_create_order TO authenticated, service_role;


-- B. pos_add_cart_item: Add line item (service, product, package, custom) to order
CREATE OR REPLACE FUNCTION public.pos_add_cart_item(
    p_order_id UUID,
    p_item_type TEXT,
    p_quantity INTEGER,
    p_product_id UUID DEFAULT NULL,
    p_service_id UUID DEFAULT NULL,
    p_package_id UUID DEFAULT NULL,
    p_appointment_id UUID DEFAULT NULL,
    p_performing_staff_id UUID DEFAULT NULL,
    p_custom_name TEXT DEFAULT NULL,
    p_custom_price_minor_units INTEGER DEFAULT NULL,
    p_discount_minor_units INTEGER DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_order RECORD;
    v_product RECORD;
    v_service RECORD;
    v_perf_staff RECORD;
    v_apt RECORD;
    v_pkg_id UUID;
    v_pkg_tenant_id UUID;
    v_pkg_name TEXT;
    v_pkg_price INTEGER;
    v_item_name TEXT;
    v_sku TEXT := NULL;
    v_unit_price INTEGER := 0;
    v_tax_rate INTEGER := 0;
    v_tax_amount INTEGER := 0;
    v_line_total INTEGER := 0;
    v_item_id UUID;
    v_subtotal INTEGER;
    v_total_tax INTEGER;
    v_total_discount INTEGER;
    v_order_total INTEGER;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    IF p_quantity IS NULL OR p_quantity <= 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Quantity must be greater than zero.';
    END IF;

    IF COALESCE(p_discount_minor_units, 0) < 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: discount_minor_units must be non-negative.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    SELECT * INTO v_order
    FROM public.pos_orders
    WHERE id = p_order_id;

    IF v_order.id IS NULL OR v_order.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Order not found or cross-tenant access denied.';
    END IF;

    IF v_order.status <> 'open' THEN
        RAISE EXCEPTION 'INVALID_STATE: Cannot add items to an order with status %.', v_order.status;
    END IF;

    IF p_performing_staff_id IS NOT NULL THEN
        SELECT * INTO v_perf_staff
        FROM public.staff
        WHERE id = p_performing_staff_id;

        IF v_perf_staff.id IS NULL OR v_perf_staff.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Performing staff not found or cross-tenant access denied.';
        END IF;

        IF v_perf_staff.active IS NOT TRUE THEN
            RAISE EXCEPTION 'INVALID_STATE: Performing staff member is inactive.';
        END IF;
    END IF;

    IF p_appointment_id IS NOT NULL THEN
        SELECT id, tenant_id INTO v_apt
        FROM public.appointments
        WHERE id = p_appointment_id;

        IF v_apt.id IS NULL OR v_apt.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Appointment not found or cross-tenant access denied.';
        END IF;
    END IF;

    IF p_item_type = 'product' THEN
        IF p_product_id IS NULL THEN
            RAISE EXCEPTION 'INVALID_INPUT: product_id is required for product line items.';
        END IF;

        SELECT * INTO v_product
        FROM public.products
        WHERE id = p_product_id;

        IF v_product.id IS NULL OR v_product.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Product not found or cross-tenant access denied.';
        END IF;

        IF v_product.is_active IS NOT TRUE THEN
            RAISE EXCEPTION 'PRODUCT_INACTIVE: Cannot sell an inactive product.';
        END IF;

        v_item_name := v_product.name;
        v_sku := v_product.sku;
        v_unit_price := v_product.price_minor_units;
        v_tax_rate := v_product.tax_rate_basis_points;

    ELSIF p_item_type = 'service' THEN
        IF p_service_id IS NULL THEN
            RAISE EXCEPTION 'INVALID_INPUT: service_id is required for service line items.';
        END IF;

        SELECT * INTO v_service
        FROM public.services
        WHERE id = p_service_id;

        IF v_service.id IS NULL OR v_service.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Service not found or cross-tenant access denied.';
        END IF;

        IF v_service.active IS NOT TRUE THEN
            RAISE EXCEPTION 'SERVICE_INACTIVE: Cannot sell an inactive service.';
        END IF;

        v_item_name := v_service.name;
        -- public.services.price stores integer major currency units; convert to integer minor units
        v_unit_price := COALESCE(v_service.price, 0) * 100;

    ELSIF p_item_type = 'package' THEN
        IF p_package_id IS NULL THEN
            RAISE EXCEPTION 'INVALID_INPUT: package_id is required for package line items.';
        END IF;

        IF to_regclass('public.service_package_definitions') IS NULL THEN
            RAISE EXCEPTION 'FEATURE_NOT_AVAILABLE: Service package definitions catalog is not yet provisioned.';
        END IF;

        EXECUTE 'SELECT id, tenant_id, name, price_minor_units FROM public.service_package_definitions WHERE id = $1'
            INTO v_pkg_id, v_pkg_tenant_id, v_pkg_name, v_pkg_price
            USING p_package_id;

        IF v_pkg_id IS NULL OR v_pkg_tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Package not found or cross-tenant access denied.';
        END IF;

        v_item_name := v_pkg_name;
        v_unit_price := COALESCE(v_pkg_price, 0);

    ELSIF p_item_type = 'custom' THEN
        IF p_custom_name IS NULL OR length(trim(p_custom_name)) = 0 THEN
            RAISE EXCEPTION 'INVALID_INPUT: custom_name is required for custom line items.';
        END IF;
        IF p_custom_price_minor_units IS NULL OR p_custom_price_minor_units < 0 THEN
            RAISE EXCEPTION 'INVALID_INPUT: custom_price_minor_units must be non-negative.';
        END IF;

        v_item_name := trim(p_custom_name);
        v_unit_price := p_custom_price_minor_units;
    ELSE
        RAISE EXCEPTION 'INVALID_INPUT: Unsupported item_type %.', p_item_type;
    END IF;

    v_tax_amount := ((v_unit_price * p_quantity) * v_tax_rate) / 10000;
    v_line_total := (v_unit_price * p_quantity) - COALESCE(p_discount_minor_units, 0) + v_tax_amount;
    IF v_line_total < 0 THEN v_line_total := 0; END IF;

    INSERT INTO public.pos_order_items (
        order_id,
        tenant_id,
        item_type,
        service_id,
        product_id,
        package_id,
        appointment_id,
        item_name,
        sku,
        quantity,
        unit_price_minor_units,
        discount_minor_units,
        tax_rate_basis_points,
        tax_minor_units,
        line_total_minor_units,
        performing_staff_id,
        created_at
    ) VALUES (
        v_order.id,
        v_staff.tenant_id,
        p_item_type,
        p_service_id,
        p_product_id,
        p_package_id,
        p_appointment_id,
        v_item_name,
        v_sku,
        p_quantity,
        v_unit_price,
        COALESCE(p_discount_minor_units, 0),
        v_tax_rate,
        v_tax_amount,
        v_line_total,
        p_performing_staff_id,
        now()
    )
    RETURNING id INTO v_item_id;

    SELECT
        COALESCE(sum(unit_price_minor_units * quantity), 0),
        COALESCE(sum(tax_minor_units), 0),
        COALESCE(sum(discount_minor_units), 0),
        COALESCE(sum(line_total_minor_units), 0)
    INTO v_subtotal, v_total_tax, v_total_discount, v_order_total
    FROM public.pos_order_items
    WHERE order_id = v_order.id;

    UPDATE public.pos_orders
    SET subtotal_minor_units = v_subtotal,
        tax_minor_units = v_total_tax,
        discount_minor_units = v_total_discount,
        total_minor_units = v_order_total + COALESCE(tip_minor_units, 0),
        updated_at = now()
    WHERE id = v_order.id;

    RETURN jsonb_build_object(
        'success', true,
        'item_id', v_item_id,
        'item_name', v_item_name,
        'quantity', p_quantity,
        'line_total_minor_units', v_line_total,
        'order_total_minor_units', v_order_total + COALESCE(v_order.tip_minor_units, 0)
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_add_cart_item FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_add_cart_item TO authenticated, service_role;


-- C. pos_checkout_order: Atomic checkout, payment registration, and serialized stock decrement
CREATE OR REPLACE FUNCTION public.pos_checkout_order(
    p_order_id UUID,
    p_payment_method TEXT,
    p_amount_paid_minor_units INTEGER,
    p_reference_identifier TEXT DEFAULT NULL,
    p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_order RECORD;
    v_item RECORD;
    v_balance RECORD;
    v_prev_stock INTEGER;
    v_new_stock INTEGER;
    v_prod_cost INTEGER;
    v_clean_key TEXT := nullif(trim(COALESCE(p_idempotency_key, '')), '');
    v_existing_order RECORD;
    v_movement_id UUID;
    v_payment_id UUID;
    v_products_decremented INTEGER := 0;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    IF p_payment_method NOT IN ('cash', 'card_present', 'card_terminal_adapter', 'customer_wallet', 'external') THEN
        RAISE EXCEPTION 'INVALID_INPUT: Unsupported payment method %.', p_payment_method;
    END IF;

    IF p_amount_paid_minor_units IS NULL OR p_amount_paid_minor_units <= 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Amount paid must be greater than zero.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    -- Concurrency lock: serialize operations for this order
    PERFORM pg_advisory_xact_lock(
        hashtextextended('pos_order:' || p_order_id::text, 0)
    );

    -- Check idempotency under lock
    IF v_clean_key IS NOT NULL THEN
        SELECT * INTO v_existing_order
        FROM public.pos_orders
        WHERE tenant_id = v_staff.tenant_id
          AND idempotency_key = v_clean_key;

        IF v_existing_order.id IS NOT NULL THEN
            IF v_existing_order.id <> p_order_id THEN
                RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: Idempotency key already used for a different POS order.';
            END IF;

            RETURN jsonb_build_object(
                'success', true,
                'idempotent_replay', true,
                'order_id', v_existing_order.id,
                'order_number', v_existing_order.order_number,
                'status', v_existing_order.status,
                'total_minor_units', v_existing_order.total_minor_units
            );
        END IF;
    END IF;

    SELECT * INTO v_order
    FROM public.pos_orders
    WHERE id = p_order_id
    FOR UPDATE;

    IF v_order.id IS NULL OR v_order.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Order not found or cross-tenant access denied.';
    END IF;

    IF v_order.status <> 'open' THEN
        RAISE EXCEPTION 'INVALID_STATE: Order is not open for checkout (current status: %).', v_order.status;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.pos_order_items WHERE order_id = v_order.id) THEN
        RAISE EXCEPTION 'INVALID_STATE: Cannot checkout an order with zero line items.';
    END IF;

    IF p_amount_paid_minor_units < v_order.total_minor_units THEN
        RAISE EXCEPTION 'INSUFFICIENT_PAYMENT: Paid amount % is less than order total %.',
            p_amount_paid_minor_units, v_order.total_minor_units;
    END IF;

    FOR v_item IN
        SELECT * FROM public.pos_order_items
        WHERE order_id = v_order.id
          AND item_type = 'product'
        ORDER BY id
    LOOP
        PERFORM pg_advisory_xact_lock(
            hashtextextended(v_order.branch_id::text || ':' || v_item.product_id::text, 0)
        );

        SELECT * INTO v_balance
        FROM public.inventory_balances
        WHERE branch_id = v_order.branch_id
          AND product_id = v_item.product_id;

        IF v_balance.id IS NULL THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK: No inventory record for product % at branch %.',
                v_item.product_id, v_order.branch_id;
        END IF;

        v_prev_stock := v_balance.on_hand_quantity;

        IF v_prev_stock < v_item.quantity THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK: Product % has % on hand, but % requested in checkout.',
                v_item.item_name, v_prev_stock, v_item.quantity;
        END IF;

        v_new_stock := v_prev_stock - v_item.quantity;

        UPDATE public.inventory_balances
        SET on_hand_quantity = v_new_stock,
            last_movement_at = now(),
            updated_at = now()
        WHERE id = v_balance.id;

        SELECT COALESCE(cost_minor_units, 0) INTO v_prod_cost
        FROM public.products
        WHERE id = v_item.product_id;

        INSERT INTO public.inventory_movements (
            tenant_id,
            branch_id,
            product_id,
            movement_type,
            quantity,
            previous_balance,
            new_balance,
            cost_minor_units,
            currency,
            reference_id,
            reason,
            actor_staff_id,
            idempotency_key,
            created_at
        ) VALUES (
            v_staff.tenant_id,
            v_order.branch_id,
            v_item.product_id,
            'sale',
            v_item.quantity,
            v_prev_stock,
            v_new_stock,
            COALESCE(v_prod_cost, 0),
            v_order.currency,
            v_order.order_number,
            'pos_checkout',
            v_staff.id,
            COALESCE(v_clean_key || ':item:' || v_item.id::text, 'pos_sale:' || v_item.id::text),
            now()
        )
        RETURNING id INTO v_movement_id;

        UPDATE public.pos_order_items
        SET inventory_movement_id = v_movement_id
        WHERE id = v_item.id;

        v_products_decremented := v_products_decremented + 1;
    END LOOP;

    INSERT INTO public.pos_order_payments (
        order_id,
        tenant_id,
        payment_method,
        amount_minor_units,
        currency,
        reference_identifier,
        staff_id,
        notes,
        created_at
    ) VALUES (
        v_order.id,
        v_staff.tenant_id,
        p_payment_method,
        p_amount_paid_minor_units,
        v_order.currency,
        nullif(trim(p_reference_identifier), ''),
        v_staff.id,
        'checkout_payment',
        now()
    )
    RETURNING id INTO v_payment_id;

    UPDATE public.pos_orders
    SET status = 'completed',
        idempotency_key = v_clean_key,
        completed_at = now(),
        updated_at = now()
    WHERE id = v_order.id;

    RETURN jsonb_build_object(
        'success', true,
        'idempotent_replay', false,
        'order_id', v_order.id,
        'order_number', v_order.order_number,
        'status', 'completed',
        'total_minor_units', v_order.total_minor_units,
        'payment_id', v_payment_id,
        'products_decremented', v_products_decremented
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_checkout_order FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_checkout_order TO authenticated, service_role;


-- D. pos_get_order: Server-authoritative order retrieval with line items and payments
CREATE OR REPLACE FUNCTION public.pos_get_order(
    p_order_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_order RECORD;
    v_items JSONB;
    v_payments JSONB;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    SELECT * INTO v_order
    FROM public.pos_orders
    WHERE id = p_order_id;

    IF v_order.id IS NULL OR v_order.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Order not found or cross-tenant access denied.';
    END IF;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'item_id', poi.id,
            'item_type', poi.item_type,
            'item_name', poi.item_name,
            'sku', poi.sku,
            'quantity', poi.quantity,
            'unit_price_minor_units', poi.unit_price_minor_units,
            'discount_minor_units', poi.discount_minor_units,
            'tax_minor_units', poi.tax_minor_units,
            'line_total_minor_units', poi.line_total_minor_units,
            'performing_staff_id', poi.performing_staff_id,
            'inventory_movement_id', poi.inventory_movement_id
        )
        ORDER BY poi.created_at ASC
    ), '[]'::jsonb)
    INTO v_items
    FROM public.pos_order_items poi
    WHERE poi.order_id = v_order.id;

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'payment_id', pop.id,
            'payment_method', pop.payment_method,
            'amount_minor_units', pop.amount_minor_units,
            'currency', pop.currency,
            'reference_identifier', pop.reference_identifier,
            'created_at', pop.created_at
        )
        ORDER BY pop.created_at ASC
    ), '[]'::jsonb)
    INTO v_payments
    FROM public.pos_order_payments pop
    WHERE pop.order_id = v_order.id;

    RETURN jsonb_build_object(
        'success', true,
        'order_id', v_order.id,
        'order_number', v_order.order_number,
        'status', v_order.status,
        'currency', v_order.currency,
        'subtotal_minor_units', v_order.subtotal_minor_units,
        'discount_minor_units', v_order.discount_minor_units,
        'tax_minor_units', v_order.tax_minor_units,
        'tip_minor_units', v_order.tip_minor_units,
        'total_minor_units', v_order.total_minor_units,
        'items', v_items,
        'payments', v_payments,
        'created_at', v_order.created_at,
        'completed_at', v_order.completed_at
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_get_order FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_get_order TO authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260919_phase6_node4_staff_commissions_tips.sql
-- =============================================================================
-- =========================================================================
-- Ported from 72911e4: 20261003_phase6_node4_staff_commissions_tips.sql
-- Conflict-free sequential prefix: 20260919 (ADIM-034 / Faz D2)
-- Description: Phase 6 Node 4 — Staff Commissions, Tip Allocation & Earnings Ledger Foundation
-- Target: Disposable PostgreSQL database / Supabase
--
-- Directives & Domain Architecture:
-- 1. INTERNAL EARNINGS ACCOUNTING ONLY:
--    Does NOT implement payroll, bank payouts, payment-provider payouts, Iyzico payout flows,
--    Stripe Connect, tax withholding, payroll exports, or production activation.
-- 2. REUSE EXISTING POS & STAFF DOMAINS:
--    Builds directly on public.pos_orders, public.pos_order_items, public.pos_order_payments,
--    public.staff, public.users_profile, existing auth.uid() authority, and existing POS checkout.
-- 3. STAFF COMMISSION RULES:
--    public.staff_commission_rules with integer basis points (0..10000), unique (tenant_id, staff_id, item_type),
--    allowed item_types ('service', 'product', 'package', 'custom'). Managed strictly by tenant_owner.
-- 4. TIP ALLOCATION:
--    public.pos_tip_allocations for multi-staff tip splits per order. Unique (tenant_id, order_id, staff_id),
--    amount_minor_units > 0. Recomputes order tip_minor_units and total_minor_units under advisory lock.
-- 5. PERFORMING STAFF ATTRIBUTION HARDENING:
--    pos_add_cart_item enforces non-null performing_staff_id MUST be an active staff member
--    in the caller/order tenant. Foreign-tenant or inactive staff UUIDs fail closed.
-- 6. IMMUTABLE STAFF EARNINGS LEDGER:
--    public.staff_earnings_ledger records immutable commission and tip rows during atomic checkout.
--    Deterministic idempotency keys (commission:<order_id>:<order_item_id>, tip:<order_id>:<staff_id>).
--    Zero duplicate earnings on checkout replay. Failed/insufficient checkouts generate zero earnings.
-- 7. COMMISSION CALCULATION INVARIANT:
--    Commissionable base = GREATEST(unit_price_minor_units * quantity - discount_minor_units, 0).
--    Explicitly excludes tax and tip. Calculated as (commissionable_base::BIGINT * commission_basis_points) / 10000.
-- 8. TRUST BOUNDARY:
--    Direct table DML revoked from PUBLIC, anon, and authenticated on all new tables. RLS enabled.
--    NO implicit super_admin authority on business earnings or commission rules.
-- =========================================================================


-- =========================================================================
-- 1. TABLE: public.staff_commission_rules
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.staff_commission_rules (
    id                          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id                   UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    staff_id                    UUID NOT NULL REFERENCES public.staff(id) ON DELETE CASCADE,
    item_type                   TEXT NOT NULL CHECK (
        item_type IN ('service', 'product', 'package', 'custom')
    ),
    commission_basis_points     INTEGER NOT NULL CHECK (
        commission_basis_points >= 0 AND commission_basis_points <= 10000
    ),
    active                      BOOLEAN NOT NULL DEFAULT true,
    created_by_user_id          UUID NOT NULL,
    created_at                  TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at                  TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT uq_staff_commission_rules_logical UNIQUE (tenant_id, staff_id, item_type)
);

CREATE INDEX IF NOT EXISTS idx_staff_comm_rules_lookup
ON public.staff_commission_rules(tenant_id, staff_id, item_type, active);

DROP TRIGGER IF EXISTS update_staff_commission_rules_modtime ON public.staff_commission_rules;
CREATE TRIGGER update_staff_commission_rules_modtime
BEFORE UPDATE ON public.staff_commission_rules
FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE public.staff_commission_rules ENABLE ROW LEVEL SECURITY;


-- =========================================================================
-- 2. TABLE: public.pos_tip_allocations
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.pos_tip_allocations (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    order_id            UUID NOT NULL,
    staff_id            UUID NOT NULL REFERENCES public.staff(id) ON DELETE RESTRICT,
    amount_minor_units  INTEGER NOT NULL CHECK (amount_minor_units > 0),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT fk_pos_tip_alloc_order FOREIGN KEY (order_id, tenant_id)
        REFERENCES public.pos_orders(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT uq_pos_tip_alloc_order_staff UNIQUE (tenant_id, order_id, staff_id)
);

CREATE INDEX IF NOT EXISTS idx_pos_tip_alloc_order
ON public.pos_tip_allocations(tenant_id, order_id);

DROP TRIGGER IF EXISTS update_pos_tip_allocations_modtime ON public.pos_tip_allocations;
CREATE TRIGGER update_pos_tip_allocations_modtime
BEFORE UPDATE ON public.pos_tip_allocations
FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE public.pos_tip_allocations ENABLE ROW LEVEL SECURITY;


-- =========================================================================
-- 3. TABLE: public.staff_earnings_ledger
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.staff_earnings_ledger (
    id                          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id                   UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    staff_id                    UUID NOT NULL REFERENCES public.staff(id) ON DELETE RESTRICT,
    order_id                    UUID NOT NULL,
    order_item_id               UUID NULL,
    earning_type                TEXT NOT NULL CHECK (
        earning_type IN ('commission', 'tip')
    ),
    source_amount_minor_units   INTEGER NOT NULL CHECK (source_amount_minor_units >= 0),
    rate_basis_points           INTEGER NULL CHECK (
        rate_basis_points IS NULL OR (rate_basis_points >= 0 AND rate_basis_points <= 10000)
    ),
    earning_minor_units         INTEGER NOT NULL CHECK (earning_minor_units >= 0),
    currency                    VARCHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    idempotency_key             TEXT NOT NULL,
    created_at                  TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT fk_staff_earnings_order FOREIGN KEY (order_id, tenant_id)
        REFERENCES public.pos_orders(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT uq_staff_earnings_tenant_idempotency UNIQUE (tenant_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS idx_staff_earnings_staff_date
ON public.staff_earnings_ledger(tenant_id, staff_id, created_at);

CREATE INDEX IF NOT EXISTS idx_staff_earnings_order
ON public.staff_earnings_ledger(tenant_id, order_id);

ALTER TABLE public.staff_earnings_ledger ENABLE ROW LEVEL SECURITY;


-- =========================================================================
-- 4. HARDENED TRUST BOUNDARY: REVOKE DIRECT TABLE MUTATIONS
-- =========================================================================

REVOKE ALL ON TABLE public.staff_commission_rules FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.pos_tip_allocations FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.staff_earnings_ledger FROM PUBLIC, anon, authenticated;

GRANT SELECT ON TABLE public.staff_commission_rules TO authenticated;
GRANT SELECT ON TABLE public.pos_tip_allocations TO authenticated;
GRANT SELECT ON TABLE public.staff_earnings_ledger TO authenticated;


-- =========================================================================
-- 5. RLS POLICIES FOR DEFENSE IN DEPTH
-- =========================================================================

DROP POLICY IF EXISTS "Authorized tenant staff can view commission rules" ON public.staff_commission_rules;
DROP POLICY IF EXISTS "Authorized tenant staff can view commission rules" ON public.staff_commission_rules;
CREATE POLICY "Authorized tenant staff can view commission rules"
ON public.staff_commission_rules
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.users_profile up ON up.id = s.user_profile_id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = staff_commission_rules.tenant_id
          AND s.active = true
          AND up.tenant_id = s.tenant_id
          AND up.active = true
          AND up.role IN ('tenant_owner', 'staff')
    )
    OR EXISTS (
        SELECT 1 FROM public.users_profile up
        WHERE up.id = auth.uid()
          AND up.tenant_id = staff_commission_rules.tenant_id
          AND up.role = 'tenant_owner'
          AND up.active = true
    )
);

DROP POLICY IF EXISTS "Authorized tenant staff can view tip allocations" ON public.pos_tip_allocations;
DROP POLICY IF EXISTS "Authorized tenant staff can view tip allocations" ON public.pos_tip_allocations;
CREATE POLICY "Authorized tenant staff can view tip allocations"
ON public.pos_tip_allocations
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.users_profile up ON up.id = s.user_profile_id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = pos_tip_allocations.tenant_id
          AND s.active = true
          AND up.tenant_id = s.tenant_id
          AND up.active = true
          AND up.role IN ('tenant_owner', 'staff')
    )
    OR EXISTS (
        SELECT 1 FROM public.users_profile up
        WHERE up.id = auth.uid()
          AND up.tenant_id = pos_tip_allocations.tenant_id
          AND up.role = 'tenant_owner'
          AND up.active = true
    )
);

DROP POLICY IF EXISTS "Staff and tenant owners can view earnings ledger" ON public.staff_earnings_ledger;
DROP POLICY IF EXISTS "Staff and tenant owners can view earnings ledger" ON public.staff_earnings_ledger;
CREATE POLICY "Staff and tenant owners can view earnings ledger"
ON public.staff_earnings_ledger
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.users_profile up ON up.id = s.user_profile_id
        WHERE s.user_profile_id = auth.uid()
          AND s.id = staff_earnings_ledger.staff_id
          AND s.tenant_id = staff_earnings_ledger.tenant_id
          AND s.active = true
          AND up.tenant_id = s.tenant_id
          AND up.active = true
          AND up.role IN ('tenant_owner', 'staff')
    )
    OR EXISTS (
        SELECT 1 FROM public.users_profile up
        WHERE up.id = auth.uid()
          AND up.tenant_id = staff_earnings_ledger.tenant_id
          AND up.role = 'tenant_owner'
          AND up.active = true
    )
);


-- =========================================================================
-- 6. SERVER-AUTHORITATIVE RPC CONTRACTS
-- =========================================================================

-- A. pos_set_staff_commission_rule: Manage commission rules (tenant_owner only)
CREATE OR REPLACE FUNCTION public.pos_set_staff_commission_rule(
    p_staff_id UUID,
    p_item_type TEXT,
    p_commission_basis_points INTEGER,
    p_active BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_owner_profile RECORD;
    v_target_staff RECORD;
    v_clean_item_type TEXT := lower(trim(COALESCE(p_item_type, '')));
    v_rule_id UUID;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    IF v_clean_item_type NOT IN ('service', 'product', 'package', 'custom') THEN
        RAISE EXCEPTION 'INVALID_INPUT: Unsupported item_type %.', p_item_type;
    END IF;

    IF p_commission_basis_points IS NULL OR p_commission_basis_points < 0 OR p_commission_basis_points > 10000 THEN
        RAISE EXCEPTION 'INVALID_INPUT: commission_basis_points must be an integer between 0 and 10000.';
    END IF;

    -- Resolve caller: ONLY active tenant_owner of the same tenant (NO super_admin bypass)
    SELECT * INTO v_owner_profile
    FROM public.users_profile
    WHERE id = v_caller_uid
      AND role = 'tenant_owner'
      AND active = true;

    IF v_owner_profile.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Only active tenant_owner can manage staff commission rules.';
    END IF;

    SELECT * INTO v_target_staff
    FROM public.staff
    WHERE id = p_staff_id;

    IF v_target_staff.id IS NULL OR v_target_staff.tenant_id <> v_owner_profile.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Target staff not found or cross-tenant access denied.';
    END IF;

    IF v_target_staff.active IS NOT TRUE THEN
        RAISE EXCEPTION 'INVALID_STATE: Target staff member is inactive.';
    END IF;

    INSERT INTO public.staff_commission_rules (
        tenant_id,
        staff_id,
        item_type,
        commission_basis_points,
        active,
        created_by_user_id,
        created_at,
        updated_at
    ) VALUES (
        v_owner_profile.tenant_id,
        p_staff_id,
        v_clean_item_type,
        p_commission_basis_points,
        COALESCE(p_active, true),
        v_caller_uid,
        now(),
        now()
    )
    ON CONFLICT (tenant_id, staff_id, item_type)
    DO UPDATE SET
        commission_basis_points = EXCLUDED.commission_basis_points,
        active = EXCLUDED.active,
        created_by_user_id = EXCLUDED.created_by_user_id,
        updated_at = now()
    RETURNING id INTO v_rule_id;

    RETURN jsonb_build_object(
        'success', true,
        'rule_id', v_rule_id,
        'tenant_id', v_owner_profile.tenant_id,
        'staff_id', p_staff_id,
        'item_type', v_clean_item_type,
        'commission_basis_points', p_commission_basis_points,
        'active', COALESCE(p_active, true)
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_set_staff_commission_rule FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_set_staff_commission_rule TO authenticated, service_role;


-- B. pos_set_tip_allocation: Allocate tips to staff members on open orders
CREATE OR REPLACE FUNCTION public.pos_set_tip_allocation(
    p_order_id UUID,
    p_staff_id UUID,
    p_tip_minor_units INTEGER
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_caller_staff RECORD;
    v_order RECORD;
    v_target_staff RECORD;
    v_new_tip_total INTEGER := 0;
    v_items_total INTEGER := 0;
    v_new_order_total INTEGER := 0;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    IF p_tip_minor_units IS NULL OR p_tip_minor_units < 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: p_tip_minor_units must be non-negative.';
    END IF;

    SELECT s.* INTO v_caller_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_caller_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    IF p_order_id IS NULL THEN
        RAISE EXCEPTION 'INVALID_INPUT: order_id is required.';
    END IF;

    PERFORM pg_advisory_xact_lock(
        hashtextextended('pos_order:' || p_order_id::text, 0)
    );

    SELECT * INTO v_order
    FROM public.pos_orders
    WHERE id = p_order_id
    FOR UPDATE;

    IF v_order.id IS NULL OR v_order.tenant_id <> v_caller_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Order not found or cross-tenant access denied.';
    END IF;

    IF v_order.status <> 'open' THEN
        RAISE EXCEPTION 'INVALID_STATE: Cannot modify tip allocation on order with status %.', v_order.status;
    END IF;

    SELECT * INTO v_target_staff
    FROM public.staff
    WHERE id = p_staff_id;

    IF v_target_staff.id IS NULL OR v_target_staff.tenant_id <> v_caller_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Target staff not found or cross-tenant access denied.';
    END IF;

    IF v_target_staff.active IS NOT TRUE THEN
        RAISE EXCEPTION 'INVALID_STATE: Target staff member is inactive.';
    END IF;

    IF p_tip_minor_units = 0 THEN
        DELETE FROM public.pos_tip_allocations
        WHERE tenant_id = v_caller_staff.tenant_id
          AND order_id = v_order.id
          AND staff_id = p_staff_id;
    ELSE
        INSERT INTO public.pos_tip_allocations (
            tenant_id,
            order_id,
            staff_id,
            amount_minor_units,
            created_at,
            updated_at
        ) VALUES (
            v_caller_staff.tenant_id,
            v_order.id,
            p_staff_id,
            p_tip_minor_units,
            now(),
            now()
        )
        ON CONFLICT (tenant_id, order_id, staff_id)
        DO UPDATE SET
            amount_minor_units = EXCLUDED.amount_minor_units,
            updated_at = now();
    END IF;

    SELECT COALESCE(SUM(amount_minor_units), 0)
    INTO v_new_tip_total
    FROM public.pos_tip_allocations
    WHERE order_id = v_order.id;

    SELECT COALESCE(SUM(line_total_minor_units), 0)
    INTO v_items_total
    FROM public.pos_order_items
    WHERE order_id = v_order.id;

    v_new_order_total := v_items_total + v_new_tip_total;

    UPDATE public.pos_orders
    SET tip_minor_units = v_new_tip_total,
        total_minor_units = v_new_order_total,
        updated_at = now()
    WHERE id = v_order.id;

    RETURN jsonb_build_object(
        'success', true,
        'order_id', v_order.id,
        'staff_id', p_staff_id,
        'allocated_tip_minor_units', p_tip_minor_units,
        'tip_minor_units', v_new_tip_total,
        'total_minor_units', v_new_order_total
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_set_tip_allocation FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_set_tip_allocation TO authenticated, service_role;


-- C. pos_add_cart_item: Hardened with performing_staff_id same-tenant/active validation + schema parity
CREATE OR REPLACE FUNCTION public.pos_add_cart_item(
    p_order_id UUID,
    p_item_type TEXT,
    p_quantity INTEGER,
    p_product_id UUID DEFAULT NULL,
    p_service_id UUID DEFAULT NULL,
    p_package_id UUID DEFAULT NULL,
    p_appointment_id UUID DEFAULT NULL,
    p_performing_staff_id UUID DEFAULT NULL,
    p_custom_name TEXT DEFAULT NULL,
    p_custom_price_minor_units INTEGER DEFAULT NULL,
    p_discount_minor_units INTEGER DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_order RECORD;
    v_product RECORD;
    v_service RECORD;
    v_perf_staff RECORD;
    v_apt RECORD;
    v_pkg_id UUID;
    v_pkg_tenant_id UUID;
    v_pkg_name TEXT;
    v_pkg_price INTEGER;
    v_item_name TEXT;
    v_sku TEXT := NULL;
    v_unit_price INTEGER := 0;
    v_tax_rate INTEGER := 0;
    v_tax_amount INTEGER := 0;
    v_line_total INTEGER := 0;
    v_item_id UUID;
    v_subtotal INTEGER;
    v_total_tax INTEGER;
    v_total_discount INTEGER;
    v_items_line_total INTEGER;
    v_order_total INTEGER;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    IF p_quantity IS NULL OR p_quantity <= 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Quantity must be greater than zero.';
    END IF;

    IF COALESCE(p_discount_minor_units, 0) < 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: discount_minor_units must be non-negative.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    IF p_order_id IS NULL THEN
        RAISE EXCEPTION 'INVALID_INPUT: order_id is required.';
    END IF;

    -- Concurrency lock: serialize cart mutations and tip/checkout operations for this order
    PERFORM pg_advisory_xact_lock(
        hashtextextended('pos_order:' || p_order_id::text, 0)
    );

    SELECT * INTO v_order
    FROM public.pos_orders
    WHERE id = p_order_id
    FOR UPDATE;

    IF v_order.id IS NULL OR v_order.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Order not found or cross-tenant access denied.';
    END IF;

    IF v_order.status <> 'open' THEN
        RAISE EXCEPTION 'INVALID_STATE: Cannot add items to an order with status %.', v_order.status;
    END IF;

    -- NODE 4 HARDENING: When p_performing_staff_id is provided, must be active staff in same tenant
    IF p_performing_staff_id IS NOT NULL THEN
        SELECT * INTO v_perf_staff
        FROM public.staff
        WHERE id = p_performing_staff_id;

        IF v_perf_staff.id IS NULL OR v_perf_staff.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Performing staff not found or cross-tenant access denied.';
        END IF;

        IF v_perf_staff.active IS NOT TRUE THEN
            RAISE EXCEPTION 'INVALID_STATE: Performing staff member is inactive.';
        END IF;
    END IF;

    IF p_appointment_id IS NOT NULL THEN
        SELECT id, tenant_id INTO v_apt
        FROM public.appointments
        WHERE id = p_appointment_id;

        IF v_apt.id IS NULL OR v_apt.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Appointment not found or cross-tenant access denied.';
        END IF;
    END IF;

    IF p_item_type = 'product' THEN
        IF p_product_id IS NULL THEN
            RAISE EXCEPTION 'INVALID_INPUT: product_id is required for product line items.';
        END IF;

        SELECT * INTO v_product
        FROM public.products
        WHERE id = p_product_id;

        IF v_product.id IS NULL OR v_product.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Product not found or cross-tenant access denied.';
        END IF;

        IF v_product.is_active IS NOT TRUE THEN
            RAISE EXCEPTION 'PRODUCT_INACTIVE: Cannot sell an inactive product.';
        END IF;

        IF v_product.currency <> v_order.currency THEN
            RAISE EXCEPTION 'CURRENCY_MISMATCH: Product currency % does not match order currency %.',
                v_product.currency, v_order.currency;
        END IF;

        v_item_name := v_product.name;
        v_sku := v_product.sku;
        v_unit_price := v_product.price_minor_units;
        v_tax_rate := v_product.tax_rate_basis_points;

    ELSIF p_item_type = 'service' THEN
        IF p_service_id IS NULL THEN
            RAISE EXCEPTION 'INVALID_INPUT: service_id is required for service line items.';
        END IF;

        SELECT * INTO v_service
        FROM public.services
        WHERE id = p_service_id;

        IF v_service.id IS NULL OR v_service.tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Service not found or cross-tenant access denied.';
        END IF;

        IF v_service.active IS NOT TRUE THEN
            RAISE EXCEPTION 'SERVICE_INACTIVE: Cannot sell an inactive service.';
        END IF;

        v_item_name := v_service.name;
        v_unit_price := COALESCE(v_service.price, 0) * 100;

    ELSIF p_item_type = 'package' THEN
        IF p_package_id IS NULL THEN
            RAISE EXCEPTION 'INVALID_INPUT: package_id is required for package line items.';
        END IF;

        IF to_regclass('public.service_package_definitions') IS NULL THEN
            RAISE EXCEPTION 'FEATURE_NOT_AVAILABLE: Service package definitions catalog is not yet provisioned.';
        END IF;

        EXECUTE 'SELECT id, tenant_id, name, price_minor_units FROM public.service_package_definitions WHERE id = $1'
            INTO v_pkg_id, v_pkg_tenant_id, v_pkg_name, v_pkg_price
            USING p_package_id;

        IF v_pkg_id IS NULL OR v_pkg_tenant_id <> v_staff.tenant_id THEN
            RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Package not found or cross-tenant access denied.';
        END IF;

        v_item_name := v_pkg_name;
        v_unit_price := COALESCE(v_pkg_price, 0);

    ELSIF p_item_type = 'custom' THEN
        IF p_custom_name IS NULL OR length(trim(p_custom_name)) = 0 THEN
            RAISE EXCEPTION 'INVALID_INPUT: custom_name is required for custom line items.';
        END IF;
        IF p_custom_price_minor_units IS NULL OR p_custom_price_minor_units < 0 THEN
            RAISE EXCEPTION 'INVALID_INPUT: custom_price_minor_units must be non-negative.';
        END IF;

        v_item_name := trim(p_custom_name);
        v_unit_price := p_custom_price_minor_units;
    ELSE
        RAISE EXCEPTION 'INVALID_INPUT: Unsupported item_type %.', p_item_type;
    END IF;

    v_tax_amount := ((v_unit_price * p_quantity) * v_tax_rate) / 10000;
    v_line_total := (v_unit_price * p_quantity) - COALESCE(p_discount_minor_units, 0) + v_tax_amount;
    IF v_line_total < 0 THEN v_line_total := 0; END IF;

    INSERT INTO public.pos_order_items (
        order_id,
        tenant_id,
        item_type,
        service_id,
        product_id,
        package_id,
        appointment_id,
        item_name,
        sku,
        quantity,
        unit_price_minor_units,
        discount_minor_units,
        tax_rate_basis_points,
        tax_minor_units,
        line_total_minor_units,
        performing_staff_id,
        created_at
    ) VALUES (
        v_order.id,
        v_staff.tenant_id,
        p_item_type,
        p_service_id,
        p_product_id,
        p_package_id,
        p_appointment_id,
        v_item_name,
        v_sku,
        p_quantity,
        v_unit_price,
        COALESCE(p_discount_minor_units, 0),
        v_tax_rate,
        v_tax_amount,
        v_line_total,
        p_performing_staff_id,
        now()
    )
    RETURNING id INTO v_item_id;

    SELECT
        COALESCE(sum(unit_price_minor_units * quantity), 0),
        COALESCE(sum(tax_minor_units), 0),
        COALESCE(sum(discount_minor_units), 0),
        COALESCE(sum(line_total_minor_units), 0)
    INTO v_subtotal, v_total_tax, v_total_discount, v_items_line_total
    FROM public.pos_order_items
    WHERE order_id = v_order.id;

    v_order_total := v_items_line_total + COALESCE(v_order.tip_minor_units, 0);

    UPDATE public.pos_orders
    SET subtotal_minor_units = v_subtotal,
        tax_minor_units = v_total_tax,
        discount_minor_units = v_total_discount,
        total_minor_units = v_order_total,
        updated_at = now()
    WHERE id = v_order.id;

    RETURN jsonb_build_object(
        'success', true,
        'item_id', v_item_id,
        'item_name', v_item_name,
        'quantity', p_quantity,
        'line_total_minor_units', v_line_total,
        'order_total_minor_units', v_order_total
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_add_cart_item FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_add_cart_item TO authenticated, service_role;


-- D. pos_checkout_order: Augmented with atomic staff commission and tip earnings ledger materialization
CREATE OR REPLACE FUNCTION public.pos_checkout_order(
    p_order_id UUID,
    p_payment_method TEXT,
    p_amount_paid_minor_units INTEGER,
    p_reference_identifier TEXT DEFAULT NULL,
    p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_order RECORD;
    v_item RECORD;
    v_tip_alloc RECORD;
    v_comm_rule RECORD;
    v_balance RECORD;
    v_prev_stock INTEGER;
    v_new_stock INTEGER;
    v_prod_cost INTEGER;
    v_clean_key TEXT := nullif(trim(COALESCE(p_idempotency_key, '')), '');
    v_norm_reference TEXT := nullif(trim(COALESCE(p_reference_identifier, '')), '');
    v_existing_order RECORD;
    v_existing_payment RECORD;
    v_movement_id UUID;
    v_payment_id UUID;
    v_products_decremented INTEGER := 0;
    v_comm_base INTEGER;
    v_commission_amount INTEGER;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff')
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active authorized staff identity.';
    END IF;

    IF p_order_id IS NULL THEN
        RAISE EXCEPTION 'INVALID_INPUT: order_id is required.';
    END IF;

    IF p_payment_method = 'card_terminal_adapter' THEN
        RAISE EXCEPTION 'EXTERNAL_HOLD: LIVE_POS_TERMINAL_CREDENTIALS_REQUIRED: Live card terminal adapter is classified EXTERNAL_HOLD (zero live charge permitted).';
    END IF;

    IF p_payment_method = 'customer_wallet' THEN
        RAISE EXCEPTION 'EXTERNAL_HOLD: WALLET_LEDGER_DEFERRED_TO_FAZ_D3: Customer wallet tender settlement is deferred until Faz D3 (ADIM-035).';
    END IF;

    IF p_payment_method NOT IN ('cash', 'card_present', 'external') THEN
        RAISE EXCEPTION 'INVALID_INPUT: Unsupported payment method %.', p_payment_method;
    END IF;

    IF p_amount_paid_minor_units IS NULL OR p_amount_paid_minor_units <= 0 THEN
        RAISE EXCEPTION 'INVALID_INPUT: Amount paid must be greater than zero.';
    END IF;

    -- Concurrency lock: serialize operations for this order
    PERFORM pg_advisory_xact_lock(
        hashtextextended('pos_order:' || p_order_id::text, 0)
    );

    -- Check idempotency under lock
    IF v_clean_key IS NOT NULL THEN
        SELECT * INTO v_existing_order
        FROM public.pos_orders
        WHERE tenant_id = v_staff.tenant_id
          AND idempotency_key = v_clean_key;

        IF v_existing_order.id IS NOT NULL THEN
            IF v_existing_order.id <> p_order_id THEN
                RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: Idempotency key already used for a different POS order.';
            END IF;

            SELECT * INTO v_existing_payment
            FROM public.pos_order_payments
            WHERE tenant_id = v_staff.tenant_id
              AND order_id = v_existing_order.id
            ORDER BY created_at DESC
            LIMIT 1;

            IF v_existing_payment.id IS NULL
               OR v_existing_payment.payment_method <> p_payment_method
               OR v_existing_payment.amount_minor_units <> p_amount_paid_minor_units
               OR v_existing_payment.reference_identifier IS DISTINCT FROM v_norm_reference THEN
                RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: Idempotency key already used for a different checkout payment payload.';
            END IF;

            RETURN jsonb_build_object(
                'success', true,
                'idempotent_replay', true,
                'order_id', v_existing_order.id,
                'order_number', v_existing_order.order_number,
                'status', v_existing_order.status,
                'total_minor_units', v_existing_order.total_minor_units
            );
        END IF;
    END IF;

    SELECT * INTO v_order
    FROM public.pos_orders
    WHERE id = p_order_id
    FOR UPDATE;

    IF v_order.id IS NULL OR v_order.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'CROSS_TENANT_VIOLATION: Order not found or cross-tenant access denied.';
    END IF;

    IF v_order.status <> 'open' THEN
        RAISE EXCEPTION 'INVALID_STATE: Order is not open for checkout (current status: %).', v_order.status;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.pos_order_items WHERE order_id = v_order.id) THEN
        RAISE EXCEPTION 'INVALID_STATE: Cannot checkout an order with zero line items.';
    END IF;

    IF p_amount_paid_minor_units < v_order.total_minor_units THEN
        RAISE EXCEPTION 'INSUFFICIENT_PAYMENT: Paid amount % is less than order total %.',
            p_amount_paid_minor_units, v_order.total_minor_units;
    END IF;

    FOR v_item IN
        SELECT * FROM public.pos_order_items
        WHERE order_id = v_order.id
          AND item_type = 'product'
        ORDER BY id
    LOOP
        PERFORM pg_advisory_xact_lock(
            hashtextextended(v_order.branch_id::text || ':' || v_item.product_id::text, 0)
        );

        SELECT * INTO v_balance
        FROM public.inventory_balances
        WHERE branch_id = v_order.branch_id
          AND product_id = v_item.product_id;

        IF v_balance.id IS NULL THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK: No inventory record for product % at branch %.',
                v_item.product_id, v_order.branch_id;
        END IF;

        v_prev_stock := v_balance.on_hand_quantity;

        IF v_prev_stock < v_item.quantity THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK: Product % has % on hand, but % requested in checkout.',
                v_item.item_name, v_prev_stock, v_item.quantity;
        END IF;

        v_new_stock := v_prev_stock - v_item.quantity;

        UPDATE public.inventory_balances
        SET on_hand_quantity = v_new_stock,
            last_movement_at = now(),
            updated_at = now()
        WHERE id = v_balance.id;

        SELECT COALESCE(cost_minor_units, 0) INTO v_prod_cost
        FROM public.products
        WHERE id = v_item.product_id;

        INSERT INTO public.inventory_movements (
            tenant_id,
            branch_id,
            product_id,
            movement_type,
            quantity,
            previous_balance,
            new_balance,
            cost_minor_units,
            currency,
            reference_id,
            reason,
            actor_staff_id,
            idempotency_key,
            created_at
        ) VALUES (
            v_staff.tenant_id,
            v_order.branch_id,
            v_item.product_id,
            'sale',
            v_item.quantity,
            v_prev_stock,
            v_new_stock,
            COALESCE(v_prod_cost, 0),
            v_order.currency,
            v_order.order_number,
            'pos_checkout',
            v_staff.id,
            COALESCE(v_clean_key || ':item:' || v_item.id::text, 'pos_sale:' || v_item.id::text),
            now()
        )
        RETURNING id INTO v_movement_id;

        UPDATE public.pos_order_items
        SET inventory_movement_id = v_movement_id
        WHERE id = v_item.id;

        v_products_decremented := v_products_decremented + 1;
    END LOOP;

    -- NODE 4 EARNINGS MATERIALIZATION: Commissions (tax and tip excluded)
    FOR v_item IN
        SELECT * FROM public.pos_order_items
        WHERE order_id = v_order.id
          AND performing_staff_id IS NOT NULL
        ORDER BY id
    LOOP
        SELECT * INTO v_comm_rule
        FROM public.staff_commission_rules
        WHERE tenant_id = v_order.tenant_id
          AND staff_id = v_item.performing_staff_id
          AND item_type = v_item.item_type
          AND active = true;

        IF v_comm_rule.id IS NOT NULL AND v_comm_rule.commission_basis_points > 0 THEN
            v_comm_base := GREATEST(
                (v_item.unit_price_minor_units * v_item.quantity) - COALESCE(v_item.discount_minor_units, 0),
                0
            );

            v_commission_amount := (v_comm_base::BIGINT * v_comm_rule.commission_basis_points) / 10000;

            IF v_commission_amount > 0 THEN
                INSERT INTO public.staff_earnings_ledger (
                    tenant_id,
                    staff_id,
                    order_id,
                    order_item_id,
                    earning_type,
                    source_amount_minor_units,
                    rate_basis_points,
                    earning_minor_units,
                    currency,
                    idempotency_key,
                    created_at
                ) VALUES (
                    v_order.tenant_id,
                    v_item.performing_staff_id,
                    v_order.id,
                    v_item.id,
                    'commission',
                    v_comm_base,
                    v_comm_rule.commission_basis_points,
                    v_commission_amount,
                    v_order.currency,
                    'commission:' || v_order.id::text || ':' || v_item.id::text,
                    now()
                )
                ON CONFLICT (tenant_id, idempotency_key) DO NOTHING;
            END IF;
        END IF;
    END LOOP;

    -- NODE 4 EARNINGS MATERIALIZATION: Tips
    FOR v_tip_alloc IN
        SELECT * FROM public.pos_tip_allocations
        WHERE order_id = v_order.id
        ORDER BY id
    LOOP
        INSERT INTO public.staff_earnings_ledger (
            tenant_id,
            staff_id,
            order_id,
            order_item_id,
            earning_type,
            source_amount_minor_units,
            rate_basis_points,
            earning_minor_units,
            currency,
            idempotency_key,
            created_at
        ) VALUES (
            v_order.tenant_id,
            v_tip_alloc.staff_id,
            v_order.id,
            NULL,
            'tip',
            v_tip_alloc.amount_minor_units,
            NULL,
            v_tip_alloc.amount_minor_units,
            v_order.currency,
            'tip:' || v_order.id::text || ':' || v_tip_alloc.staff_id::text,
            now()
        )
        ON CONFLICT (tenant_id, idempotency_key) DO NOTHING;
    END LOOP;

    INSERT INTO public.pos_order_payments (
        order_id,
        tenant_id,
        payment_method,
        amount_minor_units,
        currency,
        reference_identifier,
        staff_id,
        notes,
        created_at
    ) VALUES (
        v_order.id,
        v_staff.tenant_id,
        p_payment_method,
        p_amount_paid_minor_units,
        v_order.currency,
        v_norm_reference,
        v_staff.id,
        'checkout_payment',
        now()
    )
    RETURNING id INTO v_payment_id;

    UPDATE public.pos_orders
    SET status = 'completed',
        idempotency_key = v_clean_key,
        completed_at = now(),
        updated_at = now()
    WHERE id = v_order.id;

    RETURN jsonb_build_object(
        'success', true,
        'idempotent_replay', false,
        'order_id', v_order.id,
        'order_number', v_order.order_number,
        'status', 'completed',
        'total_minor_units', v_order.total_minor_units,
        'payment_id', v_payment_id,
        'products_decremented', v_products_decremented
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_checkout_order FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_checkout_order TO authenticated, service_role;


-- E. pos_get_staff_earnings: Read staff earnings breakdown (own staff or same-tenant tenant_owner only)
CREATE OR REPLACE FUNCTION public.pos_get_staff_earnings(
    p_staff_id UUID,
    p_from TIMESTAMPTZ DEFAULT NULL,
    p_to TIMESTAMPTZ DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_target_staff RECORD;
    v_caller_staff RECORD;
    v_caller_owner RECORD;
    v_is_authorized BOOLEAN := false;
    v_commission_total INTEGER := 0;
    v_tip_total INTEGER := 0;
    v_total_earnings INTEGER := 0;
    v_currency VARCHAR(3);
    v_entries JSONB;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT * INTO v_target_staff
    FROM public.staff
    WHERE id = p_staff_id;

    IF v_target_staff.id IS NULL THEN
        RAISE EXCEPTION 'NOT_FOUND: Staff member not found.';
    END IF;

    -- Check if caller is the staff member themselves (active staff + active users_profile)
    SELECT s.* INTO v_caller_staff
    FROM public.staff s
    JOIN public.users_profile up ON up.id = s.user_profile_id
    WHERE s.user_profile_id = v_caller_uid
      AND s.id = p_staff_id
      AND s.tenant_id = v_target_staff.tenant_id
      AND s.active = true
      AND up.active = true
      AND up.tenant_id = s.tenant_id
      AND up.role IN ('tenant_owner', 'staff');

    IF v_caller_staff.id IS NOT NULL THEN
        v_is_authorized := true;
    END IF;

    -- If not self, check if caller is active tenant_owner in the same tenant
    IF NOT v_is_authorized THEN
        SELECT * INTO v_caller_owner
        FROM public.users_profile
        WHERE id = v_caller_uid
          AND tenant_id = v_target_staff.tenant_id
          AND role = 'tenant_owner'
          AND active = true;

        IF v_caller_owner.id IS NOT NULL THEN
            v_is_authorized := true;
        END IF;
    END IF;

    -- NO implicit super_admin authority
    IF NOT v_is_authorized THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller is not authorized to read earnings for target staff.';
    END IF;

    SELECT
        COALESCE(SUM(CASE WHEN earning_type = 'commission' THEN earning_minor_units ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN earning_type = 'tip' THEN earning_minor_units ELSE 0 END), 0),
        COALESCE(SUM(earning_minor_units), 0),
        MAX(currency)
    INTO v_commission_total, v_tip_total, v_total_earnings, v_currency
    FROM public.staff_earnings_ledger
    WHERE tenant_id = v_target_staff.tenant_id
      AND staff_id = p_staff_id
      AND (p_from IS NULL OR created_at >= p_from)
      AND (p_to IS NULL OR created_at <= p_to);

    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', el.id,
            'earning_type', el.earning_type,
            'order_id', el.order_id,
            'order_item_id', el.order_item_id,
            'source_amount_minor_units', el.source_amount_minor_units,
            'rate_basis_points', el.rate_basis_points,
            'earning_minor_units', el.earning_minor_units,
            'currency', el.currency,
            'idempotency_key', el.idempotency_key,
            'created_at', el.created_at
        )
        ORDER BY el.created_at ASC
    ), '[]'::jsonb)
    INTO v_entries
    FROM public.staff_earnings_ledger el
    WHERE el.tenant_id = v_target_staff.tenant_id
      AND el.staff_id = p_staff_id
      AND (p_from IS NULL OR el.created_at >= p_from)
      AND (p_to IS NULL OR el.created_at <= p_to);

    RETURN jsonb_build_object(
        'success', true,
        'staff_id', p_staff_id,
        'tenant_id', v_target_staff.tenant_id,
        'currency', COALESCE(v_currency, 'TRY'),
        'commission_minor_units', v_commission_total,
        'tip_minor_units', v_tip_total,
        'total_earnings_minor_units', v_total_earnings,
        'entries', v_entries
    );
END;
$$;

REVOKE ALL ON FUNCTION public.pos_get_staff_earnings FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.pos_get_staff_earnings TO authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260920_phase3_communications_foundation.sql
-- =============================================================================
-- ===========================================================================
-- Ported from 72911e4: 20260918_phase3_communications_foundation.sql
-- Conflict-free sequential prefix: 20260920 (ADIM-035 / Faz D3)
-- Description: Phase 3 Provider-Neutral Communications Foundation (Reconciled & Hardened)
-- Safety Constraints:
--   - Zero PII browser leakage (direct table access revoked from PUBLIC, anon, authenticated)
--   - Strictly NO_NETWORK_SEND; synthetic_outbox_only preserved
--   - Immutable request fingerprint idempotency with advisory lock protection
-- ===========================================================================

-- =========================================================================
-- 1. Table: public.communication_outbox
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.communication_outbox (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id               TEXT NOT NULL,
    recipient               TEXT,
    channel                 TEXT NOT NULL,
    message                 TEXT,
    status                  TEXT NOT NULL DEFAULT 'queued',
    metadata                JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.communication_outbox
    ADD COLUMN IF NOT EXISTS recipient_address TEXT,
    ADD COLUMN IF NOT EXISTS template_id TEXT,
    ADD COLUMN IF NOT EXISTS payload JSONB DEFAULT '{}'::jsonb,
    ADD COLUMN IF NOT EXISTS request_fingerprint TEXT,
    ADD COLUMN IF NOT EXISTS idempotency_key TEXT,
    ADD COLUMN IF NOT EXISTS attempt_count INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS max_attempts INTEGER NOT NULL DEFAULT 3,
    ADD COLUMN IF NOT EXISTS next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    ADD COLUMN IF NOT EXISTS last_attempt_at TIMESTAMPTZ DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS last_event_timestamp TIMESTAMPTZ DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS locked_by TEXT DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS lease_until TIMESTAMPTZ DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS provider_id TEXT DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS provider_msg_ref TEXT DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS error_code TEXT DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS error_message TEXT DEFAULT NULL;

DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT conname
        FROM pg_constraint
        WHERE conrelid = 'public.communication_outbox'::regclass
          AND contype = 'c'
          AND conname IN ('communication_outbox_channel_check', 'communication_outbox_status_check')
    ) LOOP
        EXECUTE 'ALTER TABLE public.communication_outbox DROP CONSTRAINT IF EXISTS ' || quote_ident(r.conname);
    END LOOP;
END $$;

ALTER TABLE public.communication_outbox
    ADD CONSTRAINT communication_outbox_channel_check
    CHECK (channel IN ('sms', 'whatsapp', 'email', 'otp', 'push', 'webhook'));

ALTER TABLE public.communication_outbox
    ADD CONSTRAINT communication_outbox_status_check
    CHECK (status IN (
        'queued', 'sent', 'failed',
        'processing', 'delivered', 'failed_retryable',
        'failed_terminal', 'dead_letter', 'cancelled'
    ));

UPDATE public.communication_outbox
SET recipient_address = recipient
WHERE recipient_address IS NULL AND recipient IS NOT NULL;

UPDATE public.communication_outbox
SET payload = metadata
WHERE (payload IS NULL OR payload = '{}'::jsonb) AND metadata IS NOT NULL AND metadata != '{}'::jsonb;

UPDATE public.communication_outbox
SET template_id = COALESCE(metadata->>'event_type', 'legacy_message')
WHERE template_id IS NULL;

UPDATE public.communication_outbox
SET request_fingerprint = encode(sha256((COALESCE(channel, '') || ':' || COALESCE(recipient, recipient_address, '') || ':' || COALESCE(message, payload::text, ''))::bytea), 'hex')
WHERE request_fingerprint IS NULL;

UPDATE public.communication_outbox
SET idempotency_key = 'legacy_' || id::text
WHERE idempotency_key IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_comms_outbox_tenant_idempotency_unique
    ON public.communication_outbox (tenant_id, idempotency_key)
    WHERE idempotency_key IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_comms_outbox_queue_dispatch
    ON public.communication_outbox(status, next_attempt_at)
    WHERE status IN ('queued', 'failed_retryable');

CREATE INDEX IF NOT EXISTS idx_comms_outbox_tenant ON public.communication_outbox(tenant_id);
CREATE INDEX IF NOT EXISTS idx_comms_outbox_provider_msg ON public.communication_outbox(provider_id, provider_msg_ref)
    WHERE provider_id IS NOT NULL AND provider_msg_ref IS NOT NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_trigger WHERE tgname = 'update_comms_outbox_modtime'
    ) THEN
DROP TRIGGER IF EXISTS update_comms_outbox_modtime ON public.communication_outbox;
        CREATE TRIGGER update_comms_outbox_modtime
            BEFORE UPDATE ON public.communication_outbox
            FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
    END IF;
END $$;

ALTER TABLE public.communication_outbox ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.communication_outbox FROM PUBLIC;
REVOKE ALL ON public.communication_outbox FROM anon;
REVOKE ALL ON public.communication_outbox FROM authenticated;

-- =========================================================================
-- 2. Table: public.communication_delivery_callbacks
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.communication_delivery_callbacks (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    outbox_id           UUID REFERENCES public.communication_outbox(id) ON DELETE CASCADE,
    provider_id         TEXT NOT NULL,
    provider_msg_ref    TEXT NOT NULL,
    event_type          TEXT NOT NULL CHECK (event_type IN ('delivered', 'rejected', 'failed', 'bounced', 'complaint')),
    event_timestamp     TIMESTAMPTZ NOT NULL,
    replay_token        TEXT NOT NULL,
    raw_payload_hash    TEXT NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT comms_callbacks_replay_unique UNIQUE (provider_id, replay_token)
);

CREATE INDEX IF NOT EXISTS idx_comms_callbacks_outbox ON public.communication_delivery_callbacks(outbox_id);
CREATE INDEX IF NOT EXISTS idx_comms_callbacks_provider_ref ON public.communication_delivery_callbacks(provider_id, provider_msg_ref);

ALTER TABLE public.communication_delivery_callbacks ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.communication_delivery_callbacks FROM PUBLIC;
REVOKE ALL ON public.communication_delivery_callbacks FROM anon;
REVOKE ALL ON public.communication_delivery_callbacks FROM authenticated;

-- =========================================================================
-- 3. Server-Side RPC: enqueue_communication_outbox
-- =========================================================================

CREATE OR REPLACE FUNCTION public.enqueue_communication_outbox(
    p_tenant_id         UUID,
    p_channel           TEXT,
    p_recipient_address TEXT,
    p_template_id       TEXT,
    p_payload           JSONB,
    p_idempotency_key   TEXT,
    p_max_attempts      INTEGER DEFAULT 3
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, extensions
AS $$
DECLARE
    v_clean_recipient   TEXT;
    v_clean_idempotency TEXT;
    v_fingerprint       TEXT;
    v_existing_rec      RECORD;
    v_new_id            UUID;
BEGIN
    v_clean_recipient := trim(COALESCE(p_recipient_address, ''));
    v_clean_idempotency := trim(COALESCE(p_idempotency_key, ''));

    IF length(v_clean_recipient) < 3 THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_RECIPIENT');
    END IF;

    IF length(v_clean_idempotency) < 8 THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_IDEMPOTENCY_KEY');
    END IF;

    IF p_channel NOT IN ('email', 'sms', 'whatsapp', 'otp') THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_CHANNEL');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.tenants WHERE id = p_tenant_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'TENANT_NOT_FOUND');
    END IF;

    PERFORM pg_advisory_xact_lock(
        hashtextextended('comms_outbox:' || p_tenant_id::text || ':' || v_clean_idempotency, 0)
    );

    v_fingerprint := encode(sha256(
        (p_channel || ':' || v_clean_recipient || ':' || COALESCE(p_template_id, '') || ':' || COALESCE(p_payload::text, '{}'))::bytea
    ), 'hex');

    SELECT id, request_fingerprint, status INTO v_existing_rec
    FROM public.communication_outbox
    WHERE tenant_id = p_tenant_id::text AND idempotency_key = v_clean_idempotency;

    IF FOUND THEN
        IF v_existing_rec.request_fingerprint != v_fingerprint THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'IDEMPOTENCY_CONFLICT',
                'message', 'Same idempotency key supplied with differing request payload or parameters'
            );
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'outbox_id', v_existing_rec.id,
            'status', v_existing_rec.status,
            'idempotent_duplicate', true
        );
    END IF;

    INSERT INTO public.communication_outbox (
        tenant_id,
        recipient,
        channel,
        message,
        metadata,
        recipient_address,
        template_id,
        payload,
        request_fingerprint,
        idempotency_key,
        max_attempts,
        status
    ) VALUES (
        p_tenant_id::text,
        v_clean_recipient,
        p_channel,
        COALESCE(p_payload->>'message', p_payload->>'body', p_template_id, ''),
        COALESCE(p_payload, '{}'::jsonb),
        v_clean_recipient,
        p_template_id,
        COALESCE(p_payload, '{}'::jsonb),
        v_fingerprint,
        v_clean_idempotency,
        GREATEST(COALESCE(p_max_attempts, 3), 1),
        'queued'
    )
    RETURNING id INTO v_new_id;

    RETURN jsonb_build_object(
        'success', true,
        'outbox_id', v_new_id,
        'status', 'queued'
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.enqueue_communication_outbox(UUID, TEXT, TEXT, TEXT, JSONB, TEXT, INTEGER) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.enqueue_communication_outbox(UUID, TEXT, TEXT, TEXT, JSONB, TEXT, INTEGER) FROM anon;
REVOKE EXECUTE ON FUNCTION public.enqueue_communication_outbox(UUID, TEXT, TEXT, TEXT, JSONB, TEXT, INTEGER) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.enqueue_communication_outbox(UUID, TEXT, TEXT, TEXT, JSONB, TEXT, INTEGER) TO service_role;

-- =========================================================================
-- 4. Server-Side RPC: claim_outbox_batch
-- =========================================================================

CREATE OR REPLACE FUNCTION public.claim_outbox_batch(
    p_worker_id         TEXT,
    p_batch_size        INTEGER DEFAULT 10,
    p_lease_seconds     INTEGER DEFAULT 300
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, extensions
AS $$
DECLARE
    v_clean_worker_id   TEXT;
    v_bounded_batch     INTEGER;
    v_bounded_lease     INTEGER;
    v_lease_until       TIMESTAMPTZ;
    v_claimed_ids       UUID[];
BEGIN
    v_clean_worker_id := trim(COALESCE(p_worker_id, ''));
    IF length(v_clean_worker_id) < 1 THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_WORKER_ID');
    END IF;

    v_bounded_batch := LEAST(GREATEST(COALESCE(p_batch_size, 10), 1), 100);
    v_bounded_lease := LEAST(GREATEST(COALESCE(p_lease_seconds, 300), 10), 3600);
    v_lease_until := NOW() + (v_bounded_lease || ' seconds')::interval;

    WITH candidates AS (
        SELECT id
        FROM public.communication_outbox
        WHERE (
            status IN ('queued', 'failed_retryable')
            AND next_attempt_at <= NOW()
        ) OR (
            status = 'processing'
            AND lease_until < NOW()
        )
        ORDER BY next_attempt_at ASC
        LIMIT v_bounded_batch
        FOR UPDATE SKIP LOCKED
    ),
    updated AS (
        UPDATE public.communication_outbox co
        SET status = 'processing',
            locked_by = v_clean_worker_id,
            lease_until = v_lease_until,
            last_attempt_at = NOW(),
            attempt_count = co.attempt_count + 1,
            updated_at = NOW()
        FROM candidates c
        WHERE co.id = c.id
        RETURNING co.id
    )
    SELECT array_agg(id) INTO v_claimed_ids FROM updated;

    RETURN jsonb_build_object(
        'success', true,
        'claimed_count', COALESCE(array_length(v_claimed_ids, 1), 0),
        'claimed_ids', COALESCE(v_claimed_ids, '{}'::UUID[])
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.claim_outbox_batch(TEXT, INTEGER, INTEGER) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.claim_outbox_batch(TEXT, INTEGER, INTEGER) FROM anon;
REVOKE EXECUTE ON FUNCTION public.claim_outbox_batch(TEXT, INTEGER, INTEGER) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.claim_outbox_batch(TEXT, INTEGER, INTEGER) TO service_role;

-- =========================================================================
-- 5. Server-Side RPC: record_delivery_callback
-- =========================================================================

CREATE OR REPLACE FUNCTION public.record_delivery_callback(
    p_provider_id       TEXT,
    p_provider_msg_ref  TEXT,
    p_event_type        TEXT,
    p_event_timestamp   TIMESTAMPTZ,
    p_replay_token      TEXT,
    p_raw_payload       TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, extensions
AS $$
DECLARE
    v_clean_provider    TEXT;
    v_clean_msg_ref     TEXT;
    v_clean_replay      TEXT;
    v_payload_hash      TEXT;
    v_inserted_cb_id    UUID;
    v_existing_cb       RECORD;
    v_outbox_rec        RECORD;
BEGIN
    v_clean_provider := trim(COALESCE(p_provider_id, ''));
    v_clean_msg_ref := trim(COALESCE(p_provider_msg_ref, ''));
    v_clean_replay := trim(COALESCE(p_replay_token, ''));

    IF length(v_clean_provider) < 1 OR length(v_clean_msg_ref) < 1 OR length(v_clean_replay) < 1 THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_CALLBACK_IDENTIFIERS');
    END IF;

    IF p_event_type NOT IN ('delivered', 'rejected', 'failed', 'bounced', 'complaint') THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_EVENT_TYPE');
    END IF;

    v_payload_hash := encode(sha256(COALESCE(p_raw_payload, '')::bytea), 'hex');

    INSERT INTO public.communication_delivery_callbacks (
        outbox_id,
        provider_id,
        provider_msg_ref,
        event_type,
        event_timestamp,
        replay_token,
        raw_payload_hash
    ) VALUES (
        (SELECT id FROM public.communication_outbox WHERE provider_id = v_clean_provider AND provider_msg_ref = v_clean_msg_ref LIMIT 1),
        v_clean_provider,
        v_clean_msg_ref,
        p_event_type,
        p_event_timestamp,
        v_clean_replay,
        v_payload_hash
    )
    ON CONFLICT (provider_id, replay_token) DO NOTHING
    RETURNING id INTO v_inserted_cb_id;

    IF v_inserted_cb_id IS NULL THEN
        SELECT id, raw_payload_hash INTO v_existing_cb
        FROM public.communication_delivery_callbacks
        WHERE provider_id = v_clean_provider AND replay_token = v_clean_replay;

        IF v_existing_cb.raw_payload_hash != v_payload_hash THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'EVENT_ID_PAYLOAD_MISMATCH',
                'classification', 'EVENT_ID_PAYLOAD_MISMATCH',
                'message', 'Duplicate event ID received with altered payload digest'
            );
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'duplicate', true,
            'classification', 'DUPLICATE_EXACT',
            'message', 'CALLBACK_ALREADY_PROCESSED'
        );
    END IF;

    SELECT * INTO v_outbox_rec
    FROM public.communication_outbox
    WHERE provider_id = v_clean_provider AND provider_msg_ref = v_clean_msg_ref
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'UNMATCHED_PROVIDER_REFERENCE',
            'classification', 'UNMATCHED_PROVIDER_REFERENCE',
            'provider_id', v_clean_provider,
            'provider_msg_ref', v_clean_msg_ref,
            'message', 'No matching outbox entry found for provider reference; callback audited but delivery state not applied'
        );
    END IF;

    IF v_outbox_rec.status IN ('delivered', 'failed_terminal', 'dead_letter', 'cancelled') THEN
        IF p_event_timestamp > COALESCE(v_outbox_rec.last_event_timestamp, v_outbox_rec.created_at) THEN
            UPDATE public.communication_outbox
            SET last_event_timestamp = p_event_timestamp, updated_at = NOW()
            WHERE id = v_outbox_rec.id;
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'outbox_id', v_outbox_rec.id,
            'status_preserved', v_outbox_rec.status,
            'message', 'TERMINAL_STATE_PRESERVED_AGAINST_REGRESSION'
        );
    END IF;

    IF v_outbox_rec.last_event_timestamp IS NOT NULL AND p_event_timestamp < v_outbox_rec.last_event_timestamp THEN
        RETURN jsonb_build_object(
            'success', true,
            'outbox_id', v_outbox_rec.id,
            'status_preserved', v_outbox_rec.status,
            'message', 'OUT_OF_ORDER_EVENT_IGNORED'
        );
    END IF;

    IF p_event_type = 'delivered' THEN
        UPDATE public.communication_outbox
        SET status = 'delivered',
            last_event_timestamp = p_event_timestamp,
            updated_at = NOW()
        WHERE id = v_outbox_rec.id;
    ELSIF p_event_type IN ('rejected', 'bounced', 'complaint') THEN
        UPDATE public.communication_outbox
        SET status = 'failed_terminal',
            error_code = p_event_type,
            error_message = 'Terminal delivery failure reported by provider callback',
            last_event_timestamp = p_event_timestamp,
            updated_at = NOW()
        WHERE id = v_outbox_rec.id;
    ELSIF p_event_type = 'failed' THEN
        IF v_outbox_rec.attempt_count >= v_outbox_rec.max_attempts THEN
            UPDATE public.communication_outbox
            SET status = 'dead_letter',
                error_code = 'MAX_RETRIES_EXCEEDED',
                last_event_timestamp = p_event_timestamp,
                updated_at = NOW()
            WHERE id = v_outbox_rec.id;
        ELSE
            UPDATE public.communication_outbox
            SET status = 'failed_retryable',
                next_attempt_at = NOW() + interval '5 minutes',
                last_event_timestamp = p_event_timestamp,
                updated_at = NOW()
            WHERE id = v_outbox_rec.id;
        END IF;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'outbox_id', v_outbox_rec.id,
        'status_applied', p_event_type
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.record_delivery_callback(TEXT, TEXT, TEXT, TIMESTAMPTZ, TEXT, TEXT) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.record_delivery_callback(TEXT, TEXT, TEXT, TIMESTAMPTZ, TEXT, TEXT) FROM anon;
REVOKE EXECUTE ON FUNCTION public.record_delivery_callback(TEXT, TEXT, TEXT, TIMESTAMPTZ, TEXT, TEXT) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.record_delivery_callback(TEXT, TEXT, TEXT, TIMESTAMPTZ, TEXT, TEXT) TO service_role;

-- =========================================================================
-- 6. Sanitized Tenant-Scoped Outbox Projection RPC: get_tenant_communication_outbox
-- =========================================================================

CREATE OR REPLACE FUNCTION public.get_tenant_communication_outbox(
    p_tenant_id UUID,
    p_limit     INTEGER DEFAULT 50,
    p_offset    INTEGER DEFAULT 0
)
RETURNS TABLE (
    id                  UUID,
    tenant_id           TEXT,
    recipient           TEXT,
    channel             TEXT,
    message             TEXT,
    status              TEXT,
    metadata            JSONB,
    created_at          TIMESTAMPTZ,
    updated_at          TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, extensions
AS $$
DECLARE
    v_caller_uid UUID;
BEGIN
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
        v_caller_uid := auth.uid();
        IF v_caller_uid IS NULL THEN
            RAISE EXCEPTION 'UNAUTHORIZED: Authentication required' USING ERRCODE = '42501';
        END IF;

        IF NOT EXISTS (
            SELECT 1 FROM public.users_profile up
            WHERE up.id = v_caller_uid
              AND up.active = true
              AND (
                  up.role = 'super_admin'
                  OR (up.role IN ('tenant_owner', 'staff') AND up.tenant_id = p_tenant_id)
              )
        ) THEN
            RAISE EXCEPTION 'FORBIDDEN: Tenant boundary violation' USING ERRCODE = '42501';
        END IF;
    END IF;

    RETURN QUERY
    SELECT
        co.id,
        co.tenant_id,
        co.recipient,
        co.channel,
        co.message,
        co.status,
        co.metadata,
        co.created_at,
        co.updated_at
    FROM public.communication_outbox co
    WHERE co.tenant_id = p_tenant_id::text
    ORDER BY co.created_at DESC
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100)
    OFFSET GREATEST(COALESCE(p_offset, 0), 0);
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_tenant_communication_outbox(UUID, INTEGER, INTEGER) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.get_tenant_communication_outbox(UUID, INTEGER, INTEGER) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_tenant_communication_outbox(UUID, INTEGER, INTEGER) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_tenant_communication_outbox(UUID, INTEGER, INTEGER) TO service_role;

-- =============================================================================
-- SOURCE: 20260921_phase3_provider_neutral_payment_foundation.sql
-- =============================================================================
-- ===========================================================================
-- Ported from 72911e4: 20260919_phase3_provider_neutral_payment_foundation.sql
-- Conflict-free sequential prefix: 20260921 (ADIM-035 / Faz D3)
-- Description: Phase 3 Provider-Neutral Payment Domain Foundation
-- Safety Constraints:
--   - Preserves platform_global_release_control paymentless NO_GO invariants
--   - All financial intent mutations restricted to service_role
--   - Direct table DML revoked from PUBLIC, anon, and authenticated
-- ===========================================================================

-- =========================================================================
-- 1. Table: public.payment_intents (Provider-Neutral Intent Domain)
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.payment_intents (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    purpose             TEXT NOT NULL CHECK (purpose IN ('subscription', 'appointment_deposit', 'invoice', 'custom')),
    resource_id         TEXT DEFAULT NULL,
    amount_minor        BIGINT NOT NULL CHECK (amount_minor > 0),
    currency            VARCHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    status              TEXT NOT NULL DEFAULT 'created'
                        CHECK (status IN (
                            'created',
                            'requires_action',
                            'processing',
                            'succeeded',
                            'failed',
                            'cancelled',
                            'expired'
                        )),
    idempotency_key     TEXT NOT NULL,
    request_fingerprint TEXT NOT NULL,
    provider_id         TEXT DEFAULT NULL,
    provider_reference  TEXT DEFAULT NULL,
    metadata            JSONB NOT NULL DEFAULT '{}'::jsonb,
    error_code          TEXT DEFAULT NULL,
    error_message       TEXT DEFAULT NULL,
    last_applied_event_timestamp TIMESTAMPTZ DEFAULT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT payment_intents_tenant_idempotency_unique UNIQUE (tenant_id, idempotency_key),
    CONSTRAINT uq_payment_intents_id_tenant UNIQUE (id, tenant_id)
);

CREATE INDEX IF NOT EXISTS idx_payment_intents_tenant_status ON public.payment_intents(tenant_id, status);
CREATE UNIQUE INDEX IF NOT EXISTS uq_payment_intents_provider_reference ON public.payment_intents(provider_id, provider_reference)
    WHERE provider_id IS NOT NULL AND provider_reference IS NOT NULL;

DROP TRIGGER IF EXISTS update_payment_intents_modtime ON public.payment_intents;
DROP TRIGGER IF EXISTS update_payment_intents_modtime ON public.payment_intents;
CREATE TRIGGER update_payment_intents_modtime
    BEFORE UPDATE ON public.payment_intents
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE public.payment_intents ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.payment_intents FROM PUBLIC;
REVOKE ALL ON public.payment_intents FROM anon;
REVOKE ALL ON public.payment_intents FROM authenticated;

-- =========================================================================
-- 2. Reconcile & Harden public.payments (Canonical Minor-Units Alignment)
-- =========================================================================

ALTER TABLE public.payments
    ADD COLUMN IF NOT EXISTS intent_id UUID REFERENCES public.payment_intents(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS amount_minor BIGINT DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS last_event_timestamp TIMESTAMPTZ DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS amount_unit_classification TEXT DEFAULT NULL;

UPDATE public.payments
SET amount_unit_classification = 'LEGACY_UNPROVEN_UNIT'
WHERE amount_minor IS NULL AND amount IS NOT NULL AND amount_unit_classification IS NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'chk_payments_amount_minor_positive'
    ) THEN
        ALTER TABLE public.payments
        ADD CONSTRAINT chk_payments_amount_minor_positive CHECK (amount_minor IS NULL OR amount_minor > 0);
    END IF;
END $$;

ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.payments FROM PUBLIC;
REVOKE ALL ON public.payments FROM anon;
REVOKE ALL ON public.payments FROM authenticated;

-- =========================================================================
-- 3. Reconcile & Harden public.payment_events (Provider-Scoped Atomic Replay)
-- =========================================================================

ALTER TABLE public.payment_events
    ADD COLUMN IF NOT EXISTS intent_id UUID REFERENCES public.payment_intents(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS payload_digest TEXT DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS event_timestamp TIMESTAMPTZ DEFAULT NOW();

DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT conname
        FROM pg_constraint
        WHERE conrelid = 'public.payment_events'::regclass
          AND contype = 'u'
          AND conkey = ARRAY[(
              SELECT attnum FROM pg_attribute
              WHERE attrelid = 'public.payment_events'::regclass AND attname = 'provider_event_id'
          )]
    ) LOOP
        EXECUTE 'ALTER TABLE public.payment_events DROP CONSTRAINT IF EXISTS ' || quote_ident(r.conname);
    END LOOP;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'payment_events_provider_event_unique'
    ) THEN
        ALTER TABLE public.payment_events
        ADD CONSTRAINT payment_events_provider_event_unique UNIQUE (provider, provider_event_id);
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_payment_events_intent ON public.payment_events(intent_id);

ALTER TABLE public.payment_events ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.payment_events FROM PUBLIC;
REVOKE ALL ON public.payment_events FROM anon;
REVOKE ALL ON public.payment_events FROM authenticated;

-- =========================================================================
-- 4. Server-Side RPC: create_payment_intent
-- =========================================================================

CREATE OR REPLACE FUNCTION public.create_payment_intent(
    p_tenant_id         UUID,
    p_purpose           TEXT,
    p_amount_minor      BIGINT,
    p_currency          TEXT,
    p_idempotency_key   TEXT,
    p_resource_id       TEXT DEFAULT NULL,
    p_metadata          JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, extensions
AS $$
DECLARE
    v_norm_currency     VARCHAR(3);
    v_clean_key         TEXT;
    v_clean_purpose     TEXT;
    v_fingerprint       TEXT;
    v_existing_intent   RECORD;
    v_new_id            UUID;
BEGIN
    v_clean_key := trim(COALESCE(p_idempotency_key, ''));
    v_clean_purpose := trim(COALESCE(p_purpose, ''));
    v_norm_currency := upper(trim(COALESCE(p_currency, '')));

    IF length(v_clean_key) < 8 THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_IDEMPOTENCY_KEY');
    END IF;

    IF v_clean_purpose NOT IN ('subscription', 'appointment_deposit', 'invoice', 'custom') THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_PURPOSE');
    END IF;

    IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_AMOUNT_MINOR');
    END IF;

    IF v_norm_currency !~ '^[A-Z]{3}$' THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_CURRENCY');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.tenants WHERE id = p_tenant_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'TENANT_NOT_FOUND');
    END IF;

    v_fingerprint := encode(sha256(
        (p_tenant_id::text || ':' || v_clean_purpose || ':' || p_amount_minor::text || ':' || v_norm_currency || ':' || COALESCE(p_resource_id, '') || ':' || COALESCE(p_metadata::text, '{}'))::bytea
    ), 'hex');

    INSERT INTO public.payment_intents (
        tenant_id,
        purpose,
        resource_id,
        amount_minor,
        currency,
        idempotency_key,
        request_fingerprint,
        metadata,
        status
    ) VALUES (
        p_tenant_id,
        v_clean_purpose,
        p_resource_id,
        p_amount_minor,
        v_norm_currency,
        v_clean_key,
        v_fingerprint,
        COALESCE(p_metadata, '{}'::jsonb),
        'created'
    )
    ON CONFLICT (tenant_id, idempotency_key) DO NOTHING
    RETURNING id INTO v_new_id;

    IF v_new_id IS NULL THEN
        SELECT id, request_fingerprint, status, amount_minor, currency INTO v_existing_intent
        FROM public.payment_intents
        WHERE tenant_id = p_tenant_id AND idempotency_key = v_clean_key;

        IF v_existing_intent.request_fingerprint != v_fingerprint THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'IDEMPOTENCY_CONFLICT',
                'message', 'Same idempotency key supplied with altered financial amount, currency, or purpose'
            );
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'intent_id', v_existing_intent.id,
            'status', v_existing_intent.status,
            'amount_minor', v_existing_intent.amount_minor,
            'currency', v_existing_intent.currency,
            'idempotent_duplicate', true
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'intent_id', v_new_id,
        'status', 'created',
        'amount_minor', p_amount_minor,
        'currency', v_norm_currency
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.create_payment_intent(UUID, TEXT, BIGINT, TEXT, TEXT, TEXT, JSONB) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.create_payment_intent(UUID, TEXT, BIGINT, TEXT, TEXT, TEXT, JSONB) FROM anon;
REVOKE EXECUTE ON FUNCTION public.create_payment_intent(UUID, TEXT, BIGINT, TEXT, TEXT, TEXT, JSONB) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.create_payment_intent(UUID, TEXT, BIGINT, TEXT, TEXT, TEXT, JSONB) TO service_role;

-- =========================================================================
-- 5. Server-Side RPC: bind_payment_intent_provider
-- =========================================================================

CREATE OR REPLACE FUNCTION public.bind_payment_intent_provider(
    p_intent_id          UUID,
    p_provider_id        TEXT,
    p_provider_reference TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, extensions
AS $$
DECLARE
    v_clean_provider    TEXT;
    v_clean_ref         TEXT;
    v_intent_rec        RECORD;
BEGIN
    v_clean_provider := trim(COALESCE(p_provider_id, ''));
    v_clean_ref := trim(COALESCE(p_provider_reference, ''));

    IF length(v_clean_provider) < 1 OR length(v_clean_ref) < 1 THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_BINDING_IDENTIFIERS');
    END IF;

    SELECT * INTO v_intent_rec
    FROM public.payment_intents
    WHERE id = p_intent_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'INTENT_NOT_FOUND');
    END IF;

    IF v_intent_rec.provider_id IS NOT NULL AND v_intent_rec.provider_id != v_clean_provider THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'PROVIDER_BINDING_MISMATCH',
            'message', 'Intent is already bound to a different payment provider'
        );
    END IF;

    IF v_intent_rec.provider_reference IS NOT NULL AND v_intent_rec.provider_reference != v_clean_ref THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'PROVIDER_REFERENCE_MISMATCH',
            'message', 'Intent is already bound to a different provider reference'
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.payment_intents
        WHERE provider_id = v_clean_provider
          AND provider_reference = v_clean_ref
          AND id != v_intent_rec.id
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'PROVIDER_REFERENCE_ALREADY_BOUND',
            'message', 'Another payment intent already owns this provider reference'
        );
    END IF;

    UPDATE public.payment_intents
    SET provider_id = v_clean_provider,
        provider_reference = v_clean_ref,
        updated_at = NOW()
    WHERE id = v_intent_rec.id;

    RETURN jsonb_build_object(
        'success', true,
        'intent_id', v_intent_rec.id,
        'provider_id', v_clean_provider,
        'provider_reference', v_clean_ref
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.bind_payment_intent_provider(UUID, TEXT, TEXT) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.bind_payment_intent_provider(UUID, TEXT, TEXT) FROM anon;
REVOKE EXECUTE ON FUNCTION public.bind_payment_intent_provider(UUID, TEXT, TEXT) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.bind_payment_intent_provider(UUID, TEXT, TEXT) TO service_role;

-- =========================================================================
-- 6. Server-Side RPC: process_verified_payment_event
-- =========================================================================

CREATE OR REPLACE FUNCTION public.process_verified_payment_event(
    p_provider          TEXT,
    p_provider_event_id TEXT,
    p_event_type        TEXT,
    p_event_timestamp   TIMESTAMPTZ,
    p_raw_payload_hash  TEXT,
    p_intent_id         UUID DEFAULT NULL,
    p_provider_ref      TEXT DEFAULT NULL,
    p_status            TEXT DEFAULT NULL,
    p_error_code        TEXT DEFAULT NULL,
    p_error_message     TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, extensions
AS $$
DECLARE
    v_clean_provider    TEXT;
    v_clean_event_id    TEXT;
    v_clean_ref         TEXT;
    v_inserted_ev_id    UUID;
    v_existing_ev       RECORD;
    v_intent_rec        RECORD;
    v_has_intent        BOOLEAN := FALSE;
    v_payment_id        UUID;
BEGIN
    v_clean_provider := trim(COALESCE(p_provider, ''));
    v_clean_event_id := trim(COALESCE(p_provider_event_id, ''));
    v_clean_ref := trim(COALESCE(p_provider_ref, ''));

    IF length(v_clean_provider) < 1 OR length(v_clean_event_id) < 1 THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_EVENT_IDENTIFIERS');
    END IF;

    IF p_intent_id IS NOT NULL THEN
        SELECT * INTO v_intent_rec
        FROM public.payment_intents
        WHERE id = p_intent_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'INTENT_NOT_FOUND',
                'message', 'Payment intent specified in callback does not exist'
            );
        END IF;

        IF v_intent_rec.provider_id IS NOT NULL AND v_intent_rec.provider_id != v_clean_provider THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'PROVIDER_BINDING_MISMATCH',
                'classification', 'PROVIDER_BINDING_MISMATCH',
                'message', 'Verified event provider does not match bound intent provider'
            );
        END IF;

        IF v_intent_rec.provider_reference IS NOT NULL AND length(v_clean_ref) > 0 AND v_intent_rec.provider_reference != v_clean_ref THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'PROVIDER_REFERENCE_MISMATCH',
                'classification', 'PROVIDER_REFERENCE_MISMATCH',
                'message', 'Verified event reference does not match bound intent provider reference'
            );
        END IF;

        IF v_intent_rec.provider_id IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'INTENT_NOT_BOUND',
                'classification', 'INTENT_NOT_BOUND',
                'message', 'Payment intent is not bound to a provider; bind_payment_intent_provider must be called first'
            );
        END IF;

        v_has_intent := TRUE;
    END IF;

    INSERT INTO public.payment_events (
        provider,
        provider_event_id,
        event_type,
        event_timestamp,
        payload_digest,
        intent_id,
        status,
        processed_at
    ) VALUES (
        v_clean_provider,
        v_clean_event_id,
        p_event_type,
        p_event_timestamp,
        p_raw_payload_hash,
        p_intent_id,
        p_status,
        NOW()
    )
    ON CONFLICT (provider, provider_event_id) DO NOTHING
    RETURNING id INTO v_inserted_ev_id;

    IF v_inserted_ev_id IS NULL THEN
        SELECT id, payload_digest, status INTO v_existing_ev
        FROM public.payment_events
        WHERE provider = v_clean_provider AND provider_event_id = v_clean_event_id;

        IF p_raw_payload_hash IS NOT NULL AND v_existing_ev.payload_digest IS NOT NULL AND v_existing_ev.payload_digest != p_raw_payload_hash THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'INTEGRITY_CONFLICT',
                'classification', 'INTEGRITY_CONFLICT',
                'message', 'EVENT_ID_PAYLOAD_MISMATCH: Same provider event ID received with altered payload digest'
            );
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'duplicate', true,
            'classification', 'IDEMPOTENT_SUCCESS',
            'message', 'IDEMPOTENT_SUCCESS',
            'event_id', v_existing_ev.id
        );
    END IF;

    IF v_has_intent THEN
        IF v_intent_rec.status IN ('succeeded', 'failed', 'cancelled', 'expired') THEN
            RETURN jsonb_build_object(
                'success', true,
                'intent_id', v_intent_rec.id,
                'status_preserved', v_intent_rec.status,
                'message', 'TERMINAL_STATE_PRESERVED_AGAINST_MUTATION'
            );
        END IF;

        IF v_intent_rec.last_applied_event_timestamp IS NOT NULL AND p_event_timestamp < v_intent_rec.last_applied_event_timestamp THEN
            RETURN jsonb_build_object(
                'success', true,
                'intent_id', v_intent_rec.id,
                'status_preserved', v_intent_rec.status,
                'message', 'STALE_EVENT_IGNORED_AGAINST_NEWER_STATE'
            );
        END IF;

        IF p_status = 'succeeded' THEN
            UPDATE public.payment_intents
            SET status = 'succeeded',
                provider_reference = COALESCE(NULLIF(v_clean_ref, ''), provider_reference),
                last_applied_event_timestamp = p_event_timestamp,
                updated_at = NOW()
            WHERE id = v_intent_rec.id;

            INSERT INTO public.payments (
                tenant_id,
                intent_id,
                amount,
                amount_minor,
                amount_unit_classification,
                currency,
                status,
                provider,
                provider_reference,
                last_event_timestamp,
                paid_at
            ) VALUES (
                v_intent_rec.tenant_id,
                v_intent_rec.id,
                ROUND(v_intent_rec.amount_minor / 100.0, 2),
                v_intent_rec.amount_minor,
                'CANONICAL_MINOR_UNITS',
                v_intent_rec.currency,
                'paid',
                v_clean_provider,
                COALESCE(NULLIF(v_clean_ref, ''), v_intent_rec.provider_reference),
                p_event_timestamp,
                NOW()
            ) RETURNING id INTO v_payment_id;

        ELSIF p_status = 'failed' THEN
            UPDATE public.payment_intents
            SET status = 'failed',
                error_code = p_error_code,
                error_message = p_error_message,
                last_applied_event_timestamp = p_event_timestamp,
                updated_at = NOW()
            WHERE id = v_intent_rec.id;

        ELSIF p_status = 'requires_action' THEN
            UPDATE public.payment_intents
            SET status = 'requires_action',
                last_applied_event_timestamp = p_event_timestamp,
                updated_at = NOW()
            WHERE id = v_intent_rec.id;

        ELSIF p_status = 'processing' THEN
            UPDATE public.payment_intents
            SET status = 'processing',
                last_applied_event_timestamp = p_event_timestamp,
                updated_at = NOW()
            WHERE id = v_intent_rec.id;
        END IF;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'provider', v_clean_provider,
        'provider_event_id', v_clean_event_id,
        'status_applied', p_status
    );
END;
$$;

