-- =============================================================================
-- =========================================================================
-- Ported from 72911e4: 20260924_phase4_deposit_noshow_policy_foundation.sql
-- Conflict-free sequential prefix: 20260923 (ADIM-035 / Faz D3)
-- Description: Phase 4 Node 1 Deposit & No-Show Policy Foundation
-- Safety Constraints:
--   - Provider-neutral policy domain only (NO live payment collection)
--   - Integer minor units only
--   - Direct table DML revoked from PUBLIC, anon, and authenticated
-- =========================================================================

-- 1. Table: public.deposit_policies
CREATE TABLE IF NOT EXISTS public.deposit_policies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    service_id UUID DEFAULT NULL,
    deposit_type TEXT NOT NULL CHECK (deposit_type IN ('fixed_amount', 'percentage', 'none')),
    deposit_value INTEGER NOT NULL DEFAULT 0 CHECK (deposit_value >= 0),
    currency VARCHAR(3) NOT NULL DEFAULT 'TRY',
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT fk_deposit_policies_service_tenant FOREIGN KEY (service_id, tenant_id)
        REFERENCES public.services(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT uq_deposit_policies_tenant_service UNIQUE (tenant_id, service_id),
    CONSTRAINT chk_deposit_percentage_range CHECK (deposit_type <> 'percentage' OR (deposit_value >= 0 AND deposit_value <= 100))
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_deposit_policies_tenant_default
    ON public.deposit_policies (tenant_id)
    WHERE service_id IS NULL;

CREATE INDEX IF NOT EXISTS idx_deposit_policies_tenant ON public.deposit_policies(tenant_id);

ALTER TABLE public.deposit_policies ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.deposit_policies FROM PUBLIC, anon, authenticated;

DROP POLICY IF EXISTS "Tenant staff and admins read deposit_policies" ON public.deposit_policies;
CREATE POLICY "Tenant staff and admins read deposit_policies"
    ON public.deposit_policies FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.users_profile up
            WHERE up.id = auth.uid()
              AND up.active = true
              AND (
                up.role = 'super_admin'
                OR (
                    up.role IN ('tenant_owner', 'staff')
                    AND up.tenant_id = deposit_policies.tenant_id
                )
              )
        )
    );

-- 2. Table: public.no_show_policies
CREATE TABLE IF NOT EXISTS public.no_show_policies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    cancellation_deadline_hours INTEGER NOT NULL DEFAULT 24 CHECK (cancellation_deadline_hours >= 0),
    no_show_consequence TEXT NOT NULL DEFAULT 'forfeit_deposit'
        CHECK (no_show_consequence IN ('forfeit_deposit', 'strike_record', 'block_booking', 'none')),
    late_cancellation_fee_minor_units INTEGER NOT NULL DEFAULT 0 CHECK (late_cancellation_fee_minor_units >= 0),
    refund_eligible_window_hours INTEGER NOT NULL DEFAULT 24 CHECK (refund_eligible_window_hours >= 0),
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_no_show_policies_tenant UNIQUE (tenant_id)
);

ALTER TABLE public.no_show_policies ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.no_show_policies FROM PUBLIC, anon, authenticated;

DROP POLICY IF EXISTS "Tenant staff and admins read no_show_policies" ON public.no_show_policies;
CREATE POLICY "Tenant staff and admins read no_show_policies"
    ON public.no_show_policies FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.users_profile up
            WHERE up.id = auth.uid()
              AND up.active = true
              AND (
                up.role = 'super_admin'
                OR (
                    up.role IN ('tenant_owner', 'staff')
                    AND up.tenant_id = no_show_policies.tenant_id
                )
              )
        )
    );

-- 3. Table: public.appointment_deposits
CREATE TABLE IF NOT EXISTS public.appointment_deposits (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    appointment_id UUID NOT NULL,
    required_minor_units INTEGER NOT NULL CHECK (required_minor_units >= 0),
    currency VARCHAR(3) NOT NULL DEFAULT 'TRY',
    status TEXT NOT NULL DEFAULT 'required'
        CHECK (status IN ('required', 'held', 'applied', 'forfeited', 'refunded', 'waived')),
    payment_intent_id UUID DEFAULT NULL,
    payment_intent_ref TEXT DEFAULT NULL,
    forfeited_reason TEXT DEFAULT NULL,
    refund_eligibility_state TEXT NOT NULL DEFAULT 'eligible_if_cancelled_in_time'
        CHECK (refund_eligibility_state IN ('eligible_if_cancelled_in_time', 'non_refundable', 'refund_issued', 'forfeited')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT fk_appointment_deposits_appointment_tenant FOREIGN KEY (appointment_id, tenant_id)
        REFERENCES public.appointments(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT fk_appointment_deposits_payment_intent_tenant FOREIGN KEY (payment_intent_id, tenant_id)
        REFERENCES public.payment_intents(id, tenant_id) ON DELETE SET NULL,
    CONSTRAINT uq_appointment_deposits_appointment UNIQUE (appointment_id)
);

CREATE INDEX IF NOT EXISTS idx_appointment_deposits_tenant ON public.appointment_deposits(tenant_id);
CREATE INDEX IF NOT EXISTS idx_appointment_deposits_status ON public.appointment_deposits(status);

ALTER TABLE public.appointment_deposits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.appointment_deposits FROM PUBLIC, anon, authenticated;

DROP POLICY IF EXISTS "Tenant staff and admins read appointment_deposits" ON public.appointment_deposits;
CREATE POLICY "Tenant staff and admins read appointment_deposits"
    ON public.appointment_deposits FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.users_profile up
            WHERE up.id = auth.uid()
              AND up.active = true
              AND (
                up.role = 'super_admin'
                OR (
                    up.role IN ('tenant_owner', 'staff')
                    AND up.tenant_id = appointment_deposits.tenant_id
                )
              )
        )
    );

-- =========================================================================
-- 4. Policy Evaluator: public.evaluate_booking_confirmation_deposit_policy
-- =========================================================================

CREATE OR REPLACE FUNCTION public.evaluate_booking_confirmation_deposit_policy(
    p_tenant_id  UUID,
    p_service_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_svc_price         INTEGER;
    v_dep_pol           RECORD;
    v_has_dep_pol       BOOLEAN := FALSE;
    v_ns_pol            RECORD;
    v_has_ns_pol        BOOLEAN := FALSE;
    v_required_amount   INTEGER := 0;
    v_currency          VARCHAR(3) := 'TRY';
BEGIN
    SELECT price INTO v_svc_price
    FROM public.services
    WHERE id = p_service_id AND tenant_id = p_tenant_id AND active = true;

    IF NOT FOUND OR v_svc_price IS NULL THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'invalid_service');
    END IF;

    SELECT * INTO v_dep_pol
    FROM public.deposit_policies
    WHERE tenant_id = p_tenant_id
      AND service_id = p_service_id
      AND is_active = true
    LIMIT 1;
    v_has_dep_pol := FOUND;

    IF NOT v_has_dep_pol THEN
        SELECT * INTO v_dep_pol
        FROM public.deposit_policies
        WHERE tenant_id = p_tenant_id
          AND service_id IS NULL
          AND is_active = true
        LIMIT 1;
        v_has_dep_pol := FOUND;
    END IF;

    IF v_has_dep_pol THEN
        v_currency := v_dep_pol.currency;
        IF v_dep_pol.deposit_type = 'fixed_amount' THEN
            v_required_amount := v_dep_pol.deposit_value;
        ELSIF v_dep_pol.deposit_type = 'percentage' THEN
            RETURN jsonb_build_object(
                'success', false,
                'reason_code', 'PERCENTAGE_DEPOSIT_CALCULATION_UNAVAILABLE',
                'price_units_source_truth', 'CATALOG_PRICE_UNIT_UNRESOLVED',
                'detail', 'Catalog price unit is unproven in repository source truth; percentage conversion suspended'
            );
        END IF;
    END IF;

    SELECT * INTO v_ns_pol
    FROM public.no_show_policies
    WHERE tenant_id = p_tenant_id AND is_active = true
    LIMIT 1;
    v_has_ns_pol := FOUND;

    RETURN jsonb_build_object(
        'success', true,
        'tenant_id', p_tenant_id,
        'service_id', p_service_id,
        'price_units_source_truth', 'CATALOG_PRICE_UNIT_UNRESOLVED',
        'deposit_required', (v_required_amount > 0),
        'deposit_amount_minor_units', v_required_amount,
        'currency', v_currency,
        'no_show_cancellation_deadline_hours', CASE WHEN v_has_ns_pol THEN COALESCE(v_ns_pol.cancellation_deadline_hours, 24) ELSE 24 END,
        'no_show_consequence', CASE WHEN v_has_ns_pol THEN COALESCE(v_ns_pol.no_show_consequence, 'forfeit_deposit') ELSE 'forfeit_deposit' END,
        'refund_eligible_window_hours', CASE WHEN v_has_ns_pol THEN COALESCE(v_ns_pol.refund_eligible_window_hours, 24) ELSE 24 END
    );
END;
$$;

REVOKE ALL ON FUNCTION public.evaluate_booking_confirmation_deposit_policy(UUID, UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.evaluate_booking_confirmation_deposit_policy(UUID, UUID) TO anon, authenticated, service_role;

-- =========================================================================
-- 5. Management RPCs: Deposit & No-Show Policy Administration
-- =========================================================================

CREATE OR REPLACE FUNCTION public.admin_set_deposit_policy(
    p_tenant_id    UUID,
    p_service_id   UUID DEFAULT NULL,
    p_deposit_type TEXT DEFAULT 'fixed_amount',
    p_deposit_val  INTEGER DEFAULT 0,
    p_currency     TEXT DEFAULT 'TRY',
    p_is_active    BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user RECORD;
    v_id   UUID;
BEGIN
    SELECT role, tenant_id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND (v_user.role <> 'tenant_owner' OR v_user.tenant_id <> p_tenant_id) THEN
        RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE = '42501';
    END IF;

    IF p_service_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.services WHERE id = p_service_id AND tenant_id = p_tenant_id) THEN
        RAISE EXCEPTION 'INVALID_SERVICE' USING ERRCODE = '23503';
    END IF;

    IF p_deposit_type = 'percentage' AND (p_deposit_val < 0 OR p_deposit_val > 100) THEN
        RAISE EXCEPTION 'INVALID_PERCENTAGE: Must be between 0 and 100' USING ERRCODE = '22003';
    END IF;

    IF p_service_id IS NULL THEN
        SELECT id INTO v_id
        FROM public.deposit_policies
        WHERE tenant_id = p_tenant_id AND service_id IS NULL;

        IF v_id IS NOT NULL THEN
            UPDATE public.deposit_policies
            SET deposit_type  = p_deposit_type,
                deposit_value = GREATEST(0, COALESCE(p_deposit_val, 0)),
                currency      = upper(COALESCE(p_currency, 'TRY')),
                is_active     = COALESCE(p_is_active, true),
                updated_at    = now()
            WHERE id = v_id;
        ELSE
            INSERT INTO public.deposit_policies (tenant_id, service_id, deposit_type, deposit_value, currency, is_active)
            VALUES (p_tenant_id, NULL, p_deposit_type, GREATEST(0, COALESCE(p_deposit_val, 0)), upper(COALESCE(p_currency, 'TRY')), COALESCE(p_is_active, true))
            RETURNING id INTO v_id;
        END IF;
    ELSE
        INSERT INTO public.deposit_policies (tenant_id, service_id, deposit_type, deposit_value, currency, is_active)
        VALUES (p_tenant_id, p_service_id, p_deposit_type, GREATEST(0, COALESCE(p_deposit_val, 0)), upper(COALESCE(p_currency, 'TRY')), COALESCE(p_is_active, true))
        ON CONFLICT (tenant_id, service_id) DO UPDATE
        SET deposit_type  = EXCLUDED.deposit_type,
            deposit_value = EXCLUDED.deposit_value,
            currency      = EXCLUDED.currency,
            is_active     = EXCLUDED.is_active,
            updated_at    = now()
        RETURNING id INTO v_id;
    END IF;

    RETURN jsonb_build_object('success', true, 'deposit_policy_id', v_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_set_no_show_policy(
    p_tenant_id        UUID,
    p_deadline_hours   INTEGER DEFAULT 24,
    p_consequence      TEXT DEFAULT 'forfeit_deposit',
    p_late_fee_minor   INTEGER DEFAULT 0,
    p_refund_win_hours INTEGER DEFAULT 24,
    p_is_active        BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user RECORD;
    v_id   UUID;
BEGIN
    SELECT role, tenant_id INTO v_user
    FROM public.users_profile
    WHERE id = auth.uid() AND active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
    END IF;

    IF v_user.role <> 'super_admin' AND (v_user.role <> 'tenant_owner' OR v_user.tenant_id <> p_tenant_id) THEN
        RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE = '42501';
    END IF;

    INSERT INTO public.no_show_policies (
        tenant_id, cancellation_deadline_hours, no_show_consequence,
        late_cancellation_fee_minor_units, refund_eligible_window_hours, is_active
    ) VALUES (
        p_tenant_id, GREATEST(0, COALESCE(p_deadline_hours, 24)), p_consequence,
        GREATEST(0, COALESCE(p_late_fee_minor, 0)), GREATEST(0, COALESCE(p_refund_win_hours, 24)), COALESCE(p_is_active, true)
    )
    ON CONFLICT (tenant_id) DO UPDATE
    SET cancellation_deadline_hours = EXCLUDED.cancellation_deadline_hours,
        no_show_consequence         = EXCLUDED.no_show_consequence,
        late_cancellation_fee_minor_units = EXCLUDED.late_cancellation_fee_minor_units,
        refund_eligible_window_hours = EXCLUDED.refund_eligible_window_hours,
        is_active                   = EXCLUDED.is_active,
        updated_at                  = now()
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('success', true, 'no_show_policy_id', v_id);
END;
$$;

REVOKE ALL ON FUNCTION public.admin_set_deposit_policy(UUID, UUID, TEXT, INTEGER, TEXT, BOOLEAN) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_set_no_show_policy(UUID, INTEGER, TEXT, INTEGER, INTEGER, BOOLEAN) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.admin_set_deposit_policy(UUID, UUID, TEXT, INTEGER, TEXT, BOOLEAN) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_set_no_show_policy(UUID, INTEGER, TEXT, INTEGER, INTEGER, BOOLEAN) TO authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260924_phase4_loyalty_reactivation_foundation.sql
-- =============================================================================
-- ==============================================================================
-- Ported from 72911e4: 20260925_phase4_loyalty_reactivation_foundation.sql
-- Conflict-free sequential prefix: 20260924 (ADIM-035 / Faz D3)
-- Description: Phase 4 Loyalty & Automated Client Reactivation Foundation
-- Production Status: NO_GO
-- Safety Constraints:
--   1. Reuses canonical public.customers(id), tenants, and appointments models.
--   2. Direct mutation access revoked from PUBLIC, anon, and authenticated browser roles.
--   3. All loyalty ledger events are monotonic and append-only (BEFORE UPDATE OR DELETE trigger).
--   4. Advisory locking + FOR UPDATE + idempotency conflict guards on earn & redeem.
--   5. Strictly NO_NETWORK_SEND; reactivation queues via enqueue_communication_outbox only.
-- ==============================================================================

-- 1. LOYALTY PROGRAM CONFIGURATION PER TENANT
CREATE TABLE IF NOT EXISTS public.tenant_loyalty_configs (
    tenant_id UUID PRIMARY KEY REFERENCES public.tenants(id) ON DELETE CASCADE,
    is_active BOOLEAN NOT NULL DEFAULT true,
    points_per_completed_appointment INTEGER NOT NULL DEFAULT 50,
    points_per_minor_unit NUMERIC(10, 4) NOT NULL DEFAULT 0.0100,
    minor_units_per_point NUMERIC(10, 4) NOT NULL DEFAULT 1.0000,
    minimum_points_redemption INTEGER NOT NULL DEFAULT 100,
    reactivation_inactivity_days INTEGER NOT NULL DEFAULT 60,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 2. CUSTOMER LOYALTY LEDGER (APPEND-ONLY EVENT SOURCED LEDGER)
CREATE TABLE IF NOT EXISTS public.customer_loyalty_ledger (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_id UUID NOT NULL,
    appointment_id UUID DEFAULT NULL,
    entry_type TEXT NOT NULL CHECK (entry_type IN ('earned_appointment', 'redeemed_appointment', 'manual_adjustment', 'reactivation_bonus', 'expired')),
    points_delta INTEGER NOT NULL,
    running_balance INTEGER NOT NULL CHECK (running_balance >= 0),
    description TEXT,
    idempotency_key TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT uq_loyalty_tenant_idempotency UNIQUE (tenant_id, idempotency_key),
    CONSTRAINT fk_customer_loyalty_ledger_customer_tenant FOREIGN KEY (customer_id, tenant_id)
        REFERENCES public.customers(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT fk_customer_loyalty_ledger_appointment_tenant FOREIGN KEY (appointment_id, tenant_id)
        REFERENCES public.appointments(id, tenant_id) ON DELETE SET NULL
);

CREATE OR REPLACE FUNCTION public.prevent_loyalty_ledger_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
    RAISE EXCEPTION 'LOYALTY_LEDGER_IMMUTABLE: Updates and deletes are forbidden'
        USING ERRCODE = '23514';
END;
$$;

DROP TRIGGER IF EXISTS trg_prevent_loyalty_ledger_mutation ON public.customer_loyalty_ledger;
DROP TRIGGER IF EXISTS trg_prevent_loyalty_ledger_mutation ON public.customer_loyalty_ledger;
CREATE TRIGGER trg_prevent_loyalty_ledger_mutation
    BEFORE UPDATE OR DELETE ON public.customer_loyalty_ledger
    FOR EACH ROW
    EXECUTE FUNCTION public.prevent_loyalty_ledger_mutation();

-- 3. CUSTOMER LOYALTY BALANCES (AGGREGATE ROW CACHE WITH LOCKING SUPPORT)
CREATE TABLE IF NOT EXISTS public.customer_loyalty_balances (
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_id UUID NOT NULL,
    current_balance INTEGER NOT NULL DEFAULT 0 CHECK (current_balance >= 0),
    lifetime_earned INTEGER NOT NULL DEFAULT 0 CHECK (lifetime_earned >= 0),
    lifetime_redeemed INTEGER NOT NULL DEFAULT 0 CHECK (lifetime_redeemed >= 0),
    last_earned_at TIMESTAMPTZ,
    last_redeemed_at TIMESTAMPTZ,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    PRIMARY KEY (tenant_id, customer_id),
    CONSTRAINT fk_customer_loyalty_balances_customer_tenant FOREIGN KEY (customer_id, tenant_id)
        REFERENCES public.customers(id, tenant_id) ON DELETE CASCADE
);

-- 4. AUTOMATED REACTIVATION CAMPAIGN QUEUE
CREATE TABLE IF NOT EXISTS public.customer_reactivation_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_id UUID NOT NULL,
    cohort_code TEXT NOT NULL CHECK (cohort_code IN ('inactive_60d', 'inactive_90d')),
    last_appointment_at TIMESTAMPTZ NOT NULL,
    inactivity_days INTEGER NOT NULL,
    status TEXT NOT NULL DEFAULT 'detected'
        CHECK (status IN ('detected', 'queued_outbox', 'suppressed', 'converted')),
    suppression_reason TEXT DEFAULT NULL,
    outbox_id UUID DEFAULT NULL,
    bonus_points_offered INTEGER NOT NULL DEFAULT 50,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT uq_reactivation_cohort_event UNIQUE (tenant_id, customer_id, last_appointment_at, cohort_code),
    CONSTRAINT fk_customer_reactivation_customer_tenant FOREIGN KEY (customer_id, tenant_id)
        REFERENCES public.customers(id, tenant_id) ON DELETE CASCADE
);

ALTER TABLE public.tenant_loyalty_configs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.customer_loyalty_ledger ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.customer_loyalty_balances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.customer_reactivation_events ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.tenant_loyalty_configs FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.customer_loyalty_ledger FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.customer_loyalty_balances FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.customer_reactivation_events FROM PUBLIC, anon, authenticated;

GRANT ALL ON public.tenant_loyalty_configs TO service_role;
GRANT ALL ON public.customer_loyalty_ledger TO service_role;
GRANT ALL ON public.customer_loyalty_balances TO service_role;
GRANT ALL ON public.customer_reactivation_events TO service_role;

-- 5. SERVER-AUTHORITATIVE RPC: EARN LOYALTY POINTS ON COMPLETED APPOINTMENT
CREATE OR REPLACE FUNCTION public.earn_loyalty_points_for_appointment(
    p_tenant_id UUID,
    p_customer_id UUID,
    p_appointment_id UUID,
    p_amount_minor_units BIGINT DEFAULT NULL,
    p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_config RECORD;
    v_appt RECORD;
    v_existing RECORD;
    v_idem_key TEXT;
    v_points_to_award INTEGER;
    v_new_balance INTEGER;
    v_new_lifetime_earned INTEGER;
    v_ledger_id UUID;
BEGIN
    SELECT * INTO v_config FROM public.tenant_loyalty_configs WHERE tenant_id = p_tenant_id;
    IF NOT FOUND OR NOT v_config.is_active THEN
        RETURN jsonb_build_object('success', false, 'reason', 'LOYALTY_DISABLED_OR_NOT_CONFIGURED');
    END IF;

    SELECT * INTO v_appt
    FROM public.appointments
    WHERE id = p_appointment_id AND tenant_id = p_tenant_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'reason', 'APPOINTMENT_NOT_FOUND_IN_TENANT');
    END IF;

    IF v_appt.customer_id <> p_customer_id THEN
        RETURN jsonb_build_object('success', false, 'reason', 'APPOINTMENT_CUSTOMER_MISMATCH');
    END IF;

    IF v_appt.status <> 'completed' THEN
        RETURN jsonb_build_object('success', false, 'reason', 'APPOINTMENT_NOT_COMPLETED');
    END IF;

    v_idem_key := COALESCE(NULLIF(trim(COALESCE(p_idempotency_key, '')), ''), 'earn_appt:' || p_appointment_id::text);

    PERFORM pg_advisory_xact_lock(
        hashtextextended('loyalty_bal:' || p_tenant_id::text || ':' || p_customer_id::text, 0)
    );

    SELECT * INTO v_existing
    FROM public.customer_loyalty_ledger
    WHERE tenant_id = p_tenant_id AND idempotency_key = v_idem_key;

    IF FOUND THEN
        IF v_existing.customer_id <> p_customer_id
           OR v_existing.appointment_id IS DISTINCT FROM p_appointment_id
           OR v_existing.entry_type <> 'earned_appointment' THEN
            RETURN jsonb_build_object('success', false, 'reason', 'IDEMPOTENCY_CONFLICT');
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'idempotent_replay', true,
            'reason', 'IDEMPOTENCY_KEY_ALREADY_PROCESSED',
            'ledger_id', v_existing.id,
            'current_balance', v_existing.running_balance
        );
    END IF;

    v_points_to_award := COALESCE(v_config.points_per_completed_appointment, 50);
    IF v_points_to_award <= 0 THEN
        v_points_to_award := 50;
    END IF;

    INSERT INTO public.customer_loyalty_balances (tenant_id, customer_id, current_balance, lifetime_earned, lifetime_redeemed, last_earned_at, updated_at)
    VALUES (p_tenant_id, p_customer_id, v_points_to_award, v_points_to_award, 0, timezone('utc'::text, now()), timezone('utc'::text, now()))
    ON CONFLICT (tenant_id, customer_id)
    DO UPDATE SET
        current_balance = customer_loyalty_balances.current_balance + v_points_to_award,
        lifetime_earned = customer_loyalty_balances.lifetime_earned + v_points_to_award,
        last_earned_at = timezone('utc'::text, now()),
        updated_at = timezone('utc'::text, now())
    RETURNING current_balance, lifetime_earned INTO v_new_balance, v_new_lifetime_earned;

    INSERT INTO public.customer_loyalty_ledger (
        tenant_id, customer_id, appointment_id, entry_type, points_delta, running_balance, description, idempotency_key
    ) VALUES (
        p_tenant_id, p_customer_id, p_appointment_id, 'earned_appointment', v_points_to_award, v_new_balance,
        format('Earned from completed appointment %s', p_appointment_id), v_idem_key
    ) RETURNING id INTO v_ledger_id;

    RETURN jsonb_build_object(
        'success', true,
        'points_awarded', v_points_to_award,
        'current_balance', v_new_balance,
        'lifetime_earned', v_new_lifetime_earned,
        'ledger_id', v_ledger_id
    );
END;
$$;

-- 6. SERVER-AUTHORITATIVE RPC: REDEEM LOYALTY POINTS AT APPOINTMENT CHECKOUT
CREATE OR REPLACE FUNCTION public.redeem_loyalty_points_for_appointment(
    p_tenant_id UUID,
    p_customer_id UUID,
    p_appointment_id UUID,
    p_points_to_redeem INTEGER,
    p_idempotency_key TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_config RECORD;
    v_current_bal RECORD;
    v_existing RECORD;
    v_idem_key TEXT;
    v_new_balance INTEGER;
    v_discount_minor_units BIGINT;
    v_ledger_id UUID;
    v_appt RECORD;
BEGIN
    IF p_points_to_redeem IS NULL OR p_points_to_redeem <= 0 THEN
        RETURN jsonb_build_object('success', false, 'reason', 'INVALID_POINTS_AMOUNT');
    END IF;

    v_idem_key := NULLIF(trim(COALESCE(p_idempotency_key, '')), '');
    IF v_idem_key IS NULL THEN
        RETURN jsonb_build_object('success', false, 'reason', 'INVALID_IDEMPOTENCY_KEY');
    END IF;

    SELECT * INTO v_config FROM public.tenant_loyalty_configs WHERE tenant_id = p_tenant_id;
    IF NOT FOUND OR NOT v_config.is_active THEN
        RETURN jsonb_build_object('success', false, 'reason', 'LOYALTY_DISABLED');
    END IF;

    IF p_points_to_redeem < v_config.minimum_points_redemption THEN
        RETURN jsonb_build_object('success', false, 'reason', 'BELOW_MINIMUM_REDEMPTION_THRESHOLD');
    END IF;

    IF p_appointment_id IS NOT NULL THEN
        SELECT * INTO v_appt
        FROM public.appointments
        WHERE id = p_appointment_id AND tenant_id = p_tenant_id;

        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'reason', 'APPOINTMENT_NOT_FOUND_IN_TENANT');
        END IF;

        IF v_appt.customer_id <> p_customer_id THEN
            RETURN jsonb_build_object('success', false, 'reason', 'APPOINTMENT_CUSTOMER_MISMATCH');
        END IF;
    END IF;

    PERFORM pg_advisory_xact_lock(
        hashtextextended('loyalty_bal:' || p_tenant_id::text || ':' || p_customer_id::text, 0)
    );

    SELECT * INTO v_existing
    FROM public.customer_loyalty_ledger
    WHERE tenant_id = p_tenant_id AND idempotency_key = v_idem_key;

    IF FOUND THEN
        IF v_existing.customer_id <> p_customer_id
           OR v_existing.appointment_id IS DISTINCT FROM p_appointment_id
           OR v_existing.points_delta <> -p_points_to_redeem
           OR v_existing.entry_type <> 'redeemed_appointment' THEN
            RETURN jsonb_build_object('success', false, 'reason', 'IDEMPOTENCY_CONFLICT');
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'idempotent_replay', true,
            'reason', 'IDEMPOTENCY_KEY_ALREADY_PROCESSED',
            'ledger_id', v_existing.id,
            'remaining_balance', v_existing.running_balance
        );
    END IF;

    SELECT * INTO v_current_bal
    FROM public.customer_loyalty_balances
    WHERE tenant_id = p_tenant_id AND customer_id = p_customer_id
    FOR UPDATE;

    IF NOT FOUND OR v_current_bal.current_balance < p_points_to_redeem THEN
        RETURN jsonb_build_object('success', false, 'reason', 'INSUFFICIENT_LOYALTY_BALANCE');
    END IF;

    v_discount_minor_units := ROUND(p_points_to_redeem * v_config.minor_units_per_point);

    UPDATE public.customer_loyalty_balances
    SET
        current_balance = current_balance - p_points_to_redeem,
        lifetime_redeemed = lifetime_redeemed + p_points_to_redeem,
        last_redeemed_at = timezone('utc'::text, now()),
        updated_at = timezone('utc'::text, now())
    WHERE tenant_id = p_tenant_id AND customer_id = p_customer_id
    RETURNING current_balance INTO v_new_balance;

    INSERT INTO public.customer_loyalty_ledger (
        tenant_id, customer_id, appointment_id, entry_type, points_delta, running_balance, description, idempotency_key
    ) VALUES (
        p_tenant_id, p_customer_id, p_appointment_id, 'redeemed_appointment', -p_points_to_redeem, v_new_balance,
        format('Redeemed on appointment %s', p_appointment_id), v_idem_key
    ) RETURNING id INTO v_ledger_id;

    RETURN jsonb_build_object(
        'success', true,
        'points_redeemed', p_points_to_redeem,
        'discount_minor_units', v_discount_minor_units,
        'remaining_balance', v_new_balance,
        'ledger_id', v_ledger_id
    );
END;
$$;

-- 7. SANITIZED READ RPC: GET CUSTOMER LOYALTY PROFILE
CREATE OR REPLACE FUNCTION public.get_customer_loyalty_profile(
    p_tenant_id UUID,
    p_customer_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user        RECORD;
    v_balance     RECORD;
    v_config      RECORD;
    v_has_config  BOOLEAN := FALSE;
    v_has_balance BOOLEAN := FALSE;
BEGIN
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
        SELECT role, tenant_id INTO v_user
        FROM public.users_profile
        WHERE id = auth.uid() AND active = true;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
        END IF;

        IF v_user.role <> 'super_admin' AND (v_user.role NOT IN ('tenant_owner', 'staff') OR v_user.tenant_id <> p_tenant_id) THEN
            RAISE EXCEPTION 'PERMISSION_DENIED: Tenant staff or owner access required' USING ERRCODE = '42501';
        END IF;
    END IF;

    SELECT * INTO v_config FROM public.tenant_loyalty_configs WHERE tenant_id = p_tenant_id;
    v_has_config := FOUND;
    SELECT * INTO v_balance FROM public.customer_loyalty_balances WHERE tenant_id = p_tenant_id AND customer_id = p_customer_id;
    v_has_balance := FOUND;

    RETURN jsonb_build_object(
        'tenant_id', p_tenant_id,
        'customer_id', p_customer_id,
        'is_active', CASE WHEN v_has_config THEN COALESCE(v_config.is_active, false) ELSE false END,
        'current_balance', CASE WHEN v_has_balance THEN COALESCE(v_balance.current_balance, 0) ELSE 0 END,
        'lifetime_earned', CASE WHEN v_has_balance THEN COALESCE(v_balance.lifetime_earned, 0) ELSE 0 END,
        'lifetime_redeemed', CASE WHEN v_has_balance THEN COALESCE(v_balance.lifetime_redeemed, 0) ELSE 0 END,
        'last_earned_at', CASE WHEN v_has_balance THEN v_balance.last_earned_at ELSE NULL END,
        'last_redeemed_at', CASE WHEN v_has_balance THEN v_balance.last_redeemed_at ELSE NULL END
    );
END;
$$;

-- 8. AUTOMATED REACTIVATION SCAN
CREATE OR REPLACE FUNCTION public.scan_customer_reactivation_cohorts(
    p_tenant_id UUID,
    p_inactivity_days INTEGER DEFAULT 60
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user RECORD;
    v_cohort_code TEXT;
    v_cand RECORD;
    v_detected_count INTEGER := 0;
    v_queued_count INTEGER := 0;
    v_suppressed_count INTEGER := 0;
    v_current_consent BOOLEAN;
    v_event_id UUID;
    v_idempotency_key TEXT;
    v_recipient TEXT;
    v_channel TEXT;
    v_payload JSONB;
    v_outbox_res JSONB;
    v_recent_reactivation_exists BOOLEAN;
    v_bonus_pts INTEGER := 50;
    v_max_created_at TIMESTAMPTZ;
    v_granted_count INTEGER;
    v_revoked_count INTEGER;
BEGIN
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
        SELECT role, tenant_id INTO v_user
        FROM public.users_profile
        WHERE id = auth.uid() AND active = true;

        IF NOT FOUND OR (v_user.role <> 'super_admin' AND (v_user.role NOT IN ('tenant_owner', 'staff') OR v_user.tenant_id <> p_tenant_id)) THEN
            RAISE EXCEPTION 'PERMISSION_DENIED: Tenant staff or owner access required' USING ERRCODE = '42501';
        END IF;
    END IF;

    IF p_inactivity_days = 60 THEN
        v_cohort_code := 'inactive_60d';
    ELSIF p_inactivity_days = 90 THEN
        v_cohort_code := 'inactive_90d';
    ELSE
        RETURN jsonb_build_object(
            'success', false,
            'tenant_id', p_tenant_id,
            'error', 'INVALID_COHORT_INACTIVITY_BOUNDARY',
            'message', 'Cohort boundary must be exactly 60 or 90 days',
            'detected_customers', 0,
            'queued_outbox_count', 0,
            'suppressed_count', 0
        );
    END IF;

    FOR v_cand IN
        SELECT
            a.customer_id,
            MAX(a.appointment_date + a.appointment_time) AS last_appt,
            EXTRACT(DAY FROM (now() - MAX(a.appointment_date + a.appointment_time)))::INTEGER AS days_inactive,
            c.name AS customer_name,
            c.email AS customer_email,
            c.phone AS customer_phone
        FROM public.appointments a
        JOIN public.customers c ON c.id = a.customer_id AND c.tenant_id = a.tenant_id
        WHERE a.tenant_id = p_tenant_id
          AND a.status = 'completed'
        GROUP BY a.customer_id, c.name, c.email, c.phone
        HAVING (now() - MAX(a.appointment_date + a.appointment_time)) >= (p_inactivity_days || ' days')::INTERVAL
    LOOP
        SELECT id INTO v_event_id
        FROM public.customer_reactivation_events
        WHERE tenant_id = p_tenant_id
          AND customer_id = v_cand.customer_id
          AND last_appointment_at = v_cand.last_appt
          AND cohort_code = v_cohort_code;

        IF FOUND THEN
            CONTINUE;
        END IF;

        v_detected_count := v_detected_count + 1;

        SELECT MAX(created_at) INTO v_max_created_at
        FROM public.consent_ledger
        WHERE tenant_id = p_tenant_id::text
          AND customer_id = v_cand.customer_id::text
          AND consent_type = 'marketing';

        IF v_max_created_at IS NULL THEN
            INSERT INTO public.customer_reactivation_events (
                tenant_id, customer_id, cohort_code, last_appointment_at, inactivity_days,
                status, suppression_reason, bonus_points_offered
            ) VALUES (
                p_tenant_id, v_cand.customer_id, v_cohort_code, v_cand.last_appt, v_cand.days_inactive,
                'suppressed', 'SUPPRESSED_NO_CURRENT_MARKETING_CONSENT', v_bonus_pts
            );
            v_suppressed_count := v_suppressed_count + 1;
            CONTINUE;
        END IF;

        SELECT
            COUNT(*) FILTER (WHERE is_granted IS TRUE),
            COUNT(*) FILTER (WHERE is_granted IS NOT TRUE)
        INTO v_granted_count, v_revoked_count
        FROM public.consent_ledger
        WHERE tenant_id = p_tenant_id::text
          AND customer_id = v_cand.customer_id::text
          AND consent_type = 'marketing'
          AND created_at = v_max_created_at;

        IF v_granted_count > 0 AND v_revoked_count > 0 THEN
            INSERT INTO public.customer_reactivation_events (
                tenant_id, customer_id, cohort_code, last_appointment_at, inactivity_days,
                status, suppression_reason, bonus_points_offered
            ) VALUES (
                p_tenant_id, v_cand.customer_id, v_cohort_code, v_cand.last_appt, v_cand.days_inactive,
                'suppressed', 'SUPPRESSED_AMBIGUOUS_MARKETING_CONSENT', v_bonus_pts
            );
            v_suppressed_count := v_suppressed_count + 1;
            CONTINUE;
        ELSIF v_granted_count > 0 AND v_revoked_count = 0 THEN
            v_current_consent := true;
        ELSE
            v_current_consent := false;
        END IF;

        IF v_current_consent IS NOT TRUE THEN
            INSERT INTO public.customer_reactivation_events (
                tenant_id, customer_id, cohort_code, last_appointment_at, inactivity_days,
                status, suppression_reason, bonus_points_offered
            ) VALUES (
                p_tenant_id, v_cand.customer_id, v_cohort_code, v_cand.last_appt, v_cand.days_inactive,
                'suppressed', 'SUPPRESSED_NO_CURRENT_MARKETING_CONSENT', v_bonus_pts
            );
            v_suppressed_count := v_suppressed_count + 1;
            CONTINUE;
        END IF;

        SELECT EXISTS (
            SELECT 1 FROM public.customer_reactivation_events
            WHERE tenant_id = p_tenant_id
              AND customer_id = v_cand.customer_id
              AND status = 'queued_outbox'
              AND created_at > (now() - INTERVAL '30 days')
        ) INTO v_recent_reactivation_exists;

        IF v_recent_reactivation_exists THEN
            INSERT INTO public.customer_reactivation_events (
                tenant_id, customer_id, cohort_code, last_appointment_at, inactivity_days,
                status, suppression_reason, bonus_points_offered
            ) VALUES (
                p_tenant_id, v_cand.customer_id, v_cohort_code, v_cand.last_appt, v_cand.days_inactive,
                'suppressed', 'SUPPRESSED_COOLDOWN_ACTIVE', v_bonus_pts
            );
            v_suppressed_count := v_suppressed_count + 1;
            CONTINUE;
        END IF;

        IF v_cand.customer_email IS NOT NULL AND length(trim(v_cand.customer_email)) >= 3 THEN
            v_channel := 'email';
            v_recipient := trim(v_cand.customer_email);
        ELSIF v_cand.customer_phone IS NOT NULL AND length(trim(v_cand.customer_phone)) >= 3 THEN
            v_channel := 'sms';
            v_recipient := trim(v_cand.customer_phone);
        ELSE
            INSERT INTO public.customer_reactivation_events (
                tenant_id, customer_id, cohort_code, last_appointment_at, inactivity_days,
                status, suppression_reason, bonus_points_offered
            ) VALUES (
                p_tenant_id, v_cand.customer_id, v_cohort_code, v_cand.last_appt, v_cand.days_inactive,
                'suppressed', 'SUPPRESSED_NO_VALID_RECIPIENT_ADDRESS', v_bonus_pts
            );
            v_suppressed_count := v_suppressed_count + 1;
            CONTINUE;
        END IF;

        v_idempotency_key := 'reactivation:' || p_tenant_id::text || ':' || v_cand.customer_id::text || ':' || v_cohort_code || ':' || EXTRACT(EPOCH FROM v_cand.last_appt)::BIGINT::text;

        v_payload := jsonb_build_object(
            'customer_name', v_cand.customer_name,
            'cohort_code', v_cohort_code,
            'days_inactive', v_cand.days_inactive,
            'bonus_points_offered', v_bonus_pts,
            'message', 'We miss you! Book your next visit and receive ' || v_bonus_pts || ' bonus loyalty points.'
        );

        v_outbox_res := public.enqueue_communication_outbox(
            p_tenant_id         => p_tenant_id,
            p_channel           => v_channel,
            p_recipient_address => v_recipient,
            p_template_id       => 'customer_reactivation_' || v_cohort_code,
            p_payload           => v_payload,
            p_idempotency_key   => v_idempotency_key,
            p_max_attempts      => 3
        );

        IF (v_outbox_res->>'success')::BOOLEAN IS TRUE THEN
            INSERT INTO public.customer_reactivation_events (
                tenant_id, customer_id, cohort_code, last_appointment_at, inactivity_days,
                status, outbox_id, bonus_points_offered
            ) VALUES (
                p_tenant_id, v_cand.customer_id, v_cohort_code, v_cand.last_appt, v_cand.days_inactive,
                'queued_outbox', (v_outbox_res->>'outbox_id')::UUID, v_bonus_pts
            );
            v_queued_count := v_queued_count + 1;
        ELSE
            INSERT INTO public.customer_reactivation_events (
                tenant_id, customer_id, cohort_code, last_appointment_at, inactivity_days,
                status, suppression_reason, bonus_points_offered
            ) VALUES (
                p_tenant_id, v_cand.customer_id, v_cohort_code, v_cand.last_appt, v_cand.days_inactive,
                'suppressed', 'OUTBOX_ENQUEUE_FAILED:' || COALESCE(v_outbox_res->>'error', 'UNKNOWN'), v_bonus_pts
            );
            v_suppressed_count := v_suppressed_count + 1;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'tenant_id', p_tenant_id,
        'cohort_code', v_cohort_code,
        'cohort_inactivity_days', p_inactivity_days,
        'detected_customers', v_detected_count,
        'queued_outbox_count', v_queued_count,
        'suppressed_count', v_suppressed_count
    );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.earn_loyalty_points_for_appointment(UUID, UUID, UUID, BIGINT, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.redeem_loyalty_points_for_appointment(UUID, UUID, UUID, INTEGER, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.get_customer_loyalty_profile(UUID, UUID) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.scan_customer_reactivation_cohorts(UUID, INTEGER) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.earn_loyalty_points_for_appointment(UUID, UUID, UUID, BIGINT, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.redeem_loyalty_points_for_appointment(UUID, UUID, UUID, INTEGER, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_customer_loyalty_profile(UUID, UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.scan_customer_reactivation_cohorts(UUID, INTEGER) TO authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260925_phase4_packages_memberships_foundation.sql
-- =============================================================================
-- =========================================================================
-- Ported from 72911e4: 20260925_phase4_packages_memberships_foundation.sql
-- Conflict-free sequential prefix: 20260925 (ADIM-035 / Faz D3)
-- Description: Phase 4 Node 2 Service Packages & Memberships Foundation
-- Safety Constraints:
--   - Integer minor units for package pricing
--   - Advisory lock + SELECT ... FOR UPDATE + idempotency conflict verification
--   - Immutable redemption ledger (BEFORE UPDATE OR DELETE trigger)
--   - NO billing provider activation
-- =========================================================================

-- 1. Table: public.service_package_definitions
CREATE TABLE IF NOT EXISTS public.service_package_definitions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    price_minor_units INTEGER NOT NULL CHECK (price_minor_units >= 0),
    currency VARCHAR(3) NOT NULL DEFAULT 'TRY',
    total_credits INTEGER NOT NULL CHECK (total_credits > 0),
    validity_days INTEGER NOT NULL CHECK (validity_days > 0),
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_pkg_def_tenant_name UNIQUE (tenant_id, name),
    CONSTRAINT uq_pkg_def_id_tenant UNIQUE (id, tenant_id)
);

CREATE INDEX IF NOT EXISTS idx_pkg_def_tenant ON public.service_package_definitions(tenant_id);

-- 2. Table: public.service_package_eligibility
CREATE TABLE IF NOT EXISTS public.service_package_eligibility (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    package_definition_id UUID NOT NULL,
    service_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_pkg_eligibility UNIQUE (package_definition_id, service_id),
    CONSTRAINT fk_pkg_eligibility_pkg_tenant FOREIGN KEY (package_definition_id, tenant_id)
        REFERENCES public.service_package_definitions(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT fk_pkg_eligibility_service_tenant FOREIGN KEY (service_id, tenant_id)
        REFERENCES public.services(id, tenant_id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_pkg_eligibility_pkg ON public.service_package_eligibility(package_definition_id);
CREATE INDEX IF NOT EXISTS idx_pkg_eligibility_svc ON public.service_package_eligibility(service_id);

-- 3. Table: public.customer_packages
CREATE TABLE IF NOT EXISTS public.customer_packages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_id UUID NOT NULL,
    package_definition_id UUID NOT NULL,
    initial_credits INTEGER NOT NULL CHECK (initial_credits > 0),
    remaining_credits INTEGER NOT NULL CHECK (remaining_credits >= 0),
    expires_at TIMESTAMPTZ NOT NULL,
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'exhausted', 'expired', 'revoked')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_customer_packages_id_tenant UNIQUE (id, tenant_id),
    CONSTRAINT fk_customer_packages_customer_tenant FOREIGN KEY (customer_id, tenant_id)
        REFERENCES public.customers(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT fk_customer_packages_pkg_def_tenant FOREIGN KEY (package_definition_id, tenant_id)
        REFERENCES public.service_package_definitions(id, tenant_id) ON DELETE RESTRICT,
    CONSTRAINT chk_customer_package_credits CHECK (remaining_credits <= initial_credits)
);

CREATE INDEX IF NOT EXISTS idx_customer_packages_lookup
    ON public.customer_packages(tenant_id, customer_id, status);

-- 4. Table: public.customer_package_redemption_ledger
CREATE TABLE IF NOT EXISTS public.customer_package_redemption_ledger (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_package_id UUID NOT NULL,
    appointment_id UUID DEFAULT NULL,
    service_id UUID NOT NULL,
    credits_debited INTEGER NOT NULL CHECK (credits_debited > 0),
    credits_after INTEGER NOT NULL CHECK (credits_after >= 0),
    idempotency_key TEXT NOT NULL,
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_pkg_redemption_idempotency UNIQUE (tenant_id, idempotency_key),
    CONSTRAINT fk_pkg_redemption_customer_pkg_tenant FOREIGN KEY (customer_package_id, tenant_id)
        REFERENCES public.customer_packages(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT fk_pkg_redemption_appointment_tenant FOREIGN KEY (appointment_id, tenant_id)
        REFERENCES public.appointments(id, tenant_id) ON DELETE SET NULL,
    CONSTRAINT fk_pkg_redemption_service_tenant FOREIGN KEY (service_id, tenant_id)
        REFERENCES public.services(id, tenant_id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_pkg_redemption_pkg ON public.customer_package_redemption_ledger(customer_package_id);
CREATE INDEX IF NOT EXISTS idx_pkg_redemption_appt ON public.customer_package_redemption_ledger(appointment_id);

CREATE OR REPLACE FUNCTION public.prevent_redemption_ledger_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
    RAISE EXCEPTION 'REDEMPTION_LEDGER_IMMUTABLE: Updates and deletes are forbidden'
        USING ERRCODE = '23514';
END;
$$;

DROP TRIGGER IF EXISTS trg_prevent_redemption_ledger_mutation ON public.customer_package_redemption_ledger;
DROP TRIGGER IF EXISTS trg_prevent_redemption_ledger_mutation ON public.customer_package_redemption_ledger;
CREATE TRIGGER trg_prevent_redemption_ledger_mutation
    BEFORE UPDATE OR DELETE ON public.customer_package_redemption_ledger
    FOR EACH ROW
    EXECUTE FUNCTION public.prevent_redemption_ledger_mutation();

-- 5. Table: public.membership_plans
CREATE TABLE IF NOT EXISTS public.membership_plans (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    price_minor_units INTEGER NOT NULL CHECK (price_minor_units >= 0),
    currency VARCHAR(3) NOT NULL DEFAULT 'TRY',
    interval_unit TEXT NOT NULL CHECK (interval_unit IN ('month', 'quarter', 'year')),
    interval_count INTEGER NOT NULL DEFAULT 1 CHECK (interval_count > 0),
    entitlement_config JSONB NOT NULL DEFAULT '{}'::jsonb,
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_membership_plans_name UNIQUE (tenant_id, name),
    CONSTRAINT uq_membership_plans_id_tenant UNIQUE (id, tenant_id)
);

CREATE INDEX IF NOT EXISTS idx_membership_plans_tenant ON public.membership_plans(tenant_id);

-- 6. Table: public.customer_memberships
CREATE TABLE IF NOT EXISTS public.customer_memberships (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_id UUID NOT NULL,
    membership_plan_id UUID NOT NULL,
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'cancelled', 'expired')),
    activation_mode TEXT NOT NULL DEFAULT 'manual_test' CHECK (activation_mode IN ('manual_test', 'comped', 'admin_granted')),
    start_date TIMESTAMPTZ NOT NULL DEFAULT now(),
    end_date TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT fk_customer_memberships_customer_tenant FOREIGN KEY (customer_id, tenant_id)
        REFERENCES public.customers(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT fk_customer_memberships_plan_tenant FOREIGN KEY (membership_plan_id, tenant_id)
        REFERENCES public.membership_plans(id, tenant_id) ON DELETE RESTRICT
);

