-- =========================================================================
-- 5. RPC: transact_wallet_balance
-- =========================================================================

CREATE OR REPLACE FUNCTION public.transact_wallet_balance(
    p_tenant_id        UUID,
    p_customer_id      UUID,
    p_amount_minor     INTEGER,
    p_operation        TEXT,
    p_currency         TEXT DEFAULT 'TRY',
    p_appointment_id   UUID DEFAULT NULL,
    p_idempotency_key  TEXT DEFAULT NULL,
    p_description      TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user         RECORD;
    v_wallet       RECORD;
    v_existing     RECORD;
    v_existing_wal RECORD;
    v_appt         RECORD;
    v_new_bal      INTEGER;
    v_ledger_id    UUID;
    v_idem_key     TEXT;
    v_curr         VARCHAR(3);
    v_cust_exists  BOOLEAN;
BEGIN
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
        SELECT role, tenant_id INTO v_user
        FROM public.users_profile
        WHERE id = auth.uid() AND active = true;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
        END IF;

        IF v_user.role <> 'super_admin' AND (v_user.role <> 'tenant_owner' OR v_user.tenant_id <> p_tenant_id) THEN
            RAISE EXCEPTION 'PERMISSION_DENIED: Stored-value financial mutation requires tenant_owner or super_admin'
                USING ERRCODE = '42501';
        END IF;
    END IF;

    IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'invalid_amount');
    END IF;

    IF p_operation NOT IN ('debit', 'credit') THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'invalid_operation');
    END IF;

    v_curr := upper(trim(COALESCE(p_currency, 'TRY')));
    IF v_curr !~ '^[A-Z]{3}$' THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'invalid_currency');
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM public.customers WHERE id = p_customer_id AND tenant_id = p_tenant_id
    ) INTO v_cust_exists;

    IF NOT v_cust_exists THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'customer_not_found_in_tenant');
    END IF;

    IF p_appointment_id IS NOT NULL THEN
        SELECT * INTO v_appt
        FROM public.appointments
        WHERE id = p_appointment_id AND tenant_id = p_tenant_id;

        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'reason_code', 'appointment_not_found_in_tenant');
        END IF;

        IF v_appt.customer_id IS NOT NULL AND v_appt.customer_id <> p_customer_id THEN
            RETURN jsonb_build_object('success', false, 'reason_code', 'appointment_customer_mismatch');
        END IF;
    END IF;

    v_idem_key := COALESCE(NULLIF(trim(COALESCE(p_idempotency_key, '')), ''), gen_random_uuid()::text);

    PERFORM pg_advisory_xact_lock(
        hashtextextended('wallet:' || p_tenant_id::text || ':' || p_customer_id::text || ':' || v_curr, 0)
    );

    SELECT * INTO v_existing
    FROM public.client_wallet_ledger
    WHERE tenant_id = p_tenant_id AND idempotency_key = v_idem_key;

    IF FOUND THEN
        SELECT * INTO v_existing_wal
        FROM public.client_wallets
        WHERE id = v_existing.wallet_id;

        IF v_existing_wal.customer_id <> p_customer_id
           OR v_existing.entry_type <> p_operation
           OR v_existing.amount_minor_units <> p_amount_minor
           OR v_existing.currency <> v_curr
           OR v_existing.appointment_id IS DISTINCT FROM p_appointment_id THEN
            RETURN jsonb_build_object('success', false, 'reason_code', 'IDEMPOTENCY_CONFLICT');
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'is_idempotent_replay', true,
            'ledger_id', v_existing.id,
            'balance_after_minor_units', v_existing.balance_after_minor_units
        );
    END IF;

    SELECT * INTO v_wallet
    FROM public.client_wallets
    WHERE tenant_id = p_tenant_id AND customer_id = p_customer_id AND currency = v_curr
    FOR UPDATE;

    IF NOT FOUND THEN
        INSERT INTO public.client_wallets (tenant_id, customer_id, currency, balance_minor_units)
        VALUES (p_tenant_id, p_customer_id, v_curr, 0)
        RETURNING * INTO v_wallet;
    END IF;

    IF NOT v_wallet.is_active THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'wallet_inactive');
    END IF;

    IF p_operation = 'debit' THEN
        IF v_wallet.balance_minor_units < p_amount_minor THEN
            RETURN jsonb_build_object(
                'success', false,
                'reason_code', 'insufficient_funds',
                'current_balance_minor_units', v_wallet.balance_minor_units,
                'requested_debit_minor_units', p_amount_minor
            );
        END IF;
        v_new_bal := v_wallet.balance_minor_units - p_amount_minor;
    ELSE
        v_new_bal := v_wallet.balance_minor_units + p_amount_minor;
    END IF;

    UPDATE public.client_wallets
    SET balance_minor_units = v_new_bal,
        updated_at = now()
    WHERE id = v_wallet.id;

    INSERT INTO public.client_wallet_ledger (
        tenant_id, wallet_id, entry_type, amount_minor_units,
        balance_before_minor_units, balance_after_minor_units, currency,
        appointment_id, idempotency_key, description, metadata
    ) VALUES (
        p_tenant_id, v_wallet.id, p_operation, p_amount_minor,
        v_wallet.balance_minor_units, v_new_bal, v_curr,
        p_appointment_id, v_idem_key, p_description,
        jsonb_build_object('operator_id', auth.uid())
    )
    RETURNING id INTO v_ledger_id;

    RETURN jsonb_build_object(
        'success', true,
        'is_idempotent_replay', false,
        'ledger_id', v_ledger_id,
        'balance_before_minor_units', v_wallet.balance_minor_units,
        'balance_after_minor_units', v_new_bal,
        'operation', p_operation,
        'currency', v_curr
    );
END;
$$;

REVOKE ALL ON FUNCTION public.transact_wallet_balance(UUID, UUID, INTEGER, TEXT, TEXT, UUID, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.transact_wallet_balance(UUID, UUID, INTEGER, TEXT, TEXT, UUID, TEXT, TEXT) TO authenticated, service_role;

-- =========================================================================
-- 6. RPC: redeem_gift_card
-- =========================================================================

CREATE OR REPLACE FUNCTION public.redeem_gift_card(
    p_tenant_id       UUID,
    p_code_hash       TEXT,
    p_amount_minor    INTEGER,
    p_customer_id     UUID DEFAULT NULL,
    p_appointment_id  UUID DEFAULT NULL,
    p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user       RECORD;
    v_card       RECORD;
    v_has_card   BOOLEAN := FALSE;
    v_existing   RECORD;
    v_new_bal    INTEGER;
    v_new_status TEXT;
    v_redemp_id  UUID;
    v_idem_key   TEXT;
    v_clean_hash TEXT;
BEGIN
    IF auth.role() IS DISTINCT FROM 'service_role' THEN
        SELECT role, tenant_id INTO v_user
        FROM public.users_profile
        WHERE id = auth.uid() AND active = true;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'UNAUTHORIZED' USING ERRCODE = '42501';
        END IF;

        IF v_user.role <> 'super_admin' AND (v_user.role NOT IN ('tenant_owner', 'staff') OR v_user.tenant_id <> p_tenant_id) THEN
            RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE = '42501';
        END IF;
    END IF;

    v_clean_hash := trim(COALESCE(p_code_hash, ''));
    IF length(v_clean_hash) = 0 THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'invalid_code_hash');
    END IF;

    IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'invalid_amount');
    END IF;

    IF p_customer_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.customers WHERE id = p_customer_id AND tenant_id = p_tenant_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'customer_not_found_in_tenant');
    END IF;

    IF p_appointment_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.appointments WHERE id = p_appointment_id AND tenant_id = p_tenant_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'appointment_not_found_in_tenant');
    END IF;

    v_idem_key := COALESCE(NULLIF(trim(COALESCE(p_idempotency_key, '')), ''), gen_random_uuid()::text);

    PERFORM pg_advisory_xact_lock(
        hashtextextended('gift_card:' || p_tenant_id::text || ':' || v_clean_hash, 0)
    );

    SELECT * INTO v_card
    FROM public.gift_cards
    WHERE tenant_id = p_tenant_id AND code_hash = v_clean_hash
    FOR UPDATE;
    v_has_card := FOUND;

    SELECT * INTO v_existing
    FROM public.gift_card_redemptions
    WHERE tenant_id = p_tenant_id AND idempotency_key = v_idem_key;

    IF FOUND THEN
        IF NOT v_has_card
           OR v_existing.gift_card_id <> v_card.id
           OR v_existing.redeemed_minor_units <> p_amount_minor
           OR v_existing.customer_id IS DISTINCT FROM p_customer_id
           OR v_existing.appointment_id IS DISTINCT FROM p_appointment_id THEN
            RETURN jsonb_build_object('success', false, 'reason_code', 'IDEMPOTENCY_CONFLICT');
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'is_idempotent_replay', true,
            'redemption_id', v_existing.id,
            'remaining_balance_minor_units', v_existing.remaining_balance_minor_units
        );
    END IF;

    IF NOT v_has_card THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'gift_card_not_found');
    END IF;

    IF v_card.status <> 'active' THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'gift_card_not_active', 'status', v_card.status);
    END IF;

    IF v_card.expires_at < now() THEN
        UPDATE public.gift_cards SET status = 'expired', updated_at = now() WHERE id = v_card.id;
        RETURN jsonb_build_object('success', false, 'reason_code', 'gift_card_expired');
    END IF;

    IF v_card.current_balance_minor_units < p_amount_minor THEN
        RETURN jsonb_build_object(
            'success', false,
            'reason_code', 'insufficient_balance',
            'current_balance_minor_units', v_card.current_balance_minor_units,
            'requested_minor_units', p_amount_minor
        );
    END IF;

    v_new_bal := v_card.current_balance_minor_units - p_amount_minor;
    v_new_status := CASE WHEN v_new_bal = 0 THEN 'redeemed' ELSE 'active' END;

    UPDATE public.gift_cards
    SET current_balance_minor_units = v_new_bal,
        status = v_new_status,
        updated_at = now()
    WHERE id = v_card.id;

    INSERT INTO public.gift_card_redemptions (
        tenant_id, gift_card_id, customer_id, appointment_id,
        redeemed_minor_units, remaining_balance_minor_units, idempotency_key
    ) VALUES (
        p_tenant_id, v_card.id, p_customer_id, p_appointment_id,
        p_amount_minor, v_new_bal, v_idem_key
    )
    RETURNING id INTO v_redemp_id;

    RETURN jsonb_build_object(
        'success', true,
        'is_idempotent_replay', false,
        'redemption_id', v_redemp_id,
        'gift_card_id', v_card.id,
        'redeemed_minor_units', p_amount_minor,
        'remaining_balance_minor_units', v_new_bal,
        'status', v_new_status
    );
END;
$$;

REVOKE ALL ON FUNCTION public.redeem_gift_card(UUID, TEXT, INTEGER, UUID, UUID, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.redeem_gift_card(UUID, TEXT, INTEGER, UUID, UUID, TEXT) TO authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260927_commercial_lifecycle_eligibility_alignment.sql
-- =============================================================================
-- =========================================================================
-- Ported from 72911e4: 20260908_commercial_lifecycle_eligibility_alignment.sql
-- Conflict-free sequential prefix: 20260927 (ADIM-036 / Faz E1)
-- Description:
--   Forward-redefines resolve_tenant_commercial_eligibility and
--   resolve_effective_tenant_entitlements to establish canonical
--   commercial lifecycle semantics across active, manual_active, comped,
--   trialing (trial_end authority), and past_due (grace_until authority),
--   while preserving H1C plan_version/integer compatibility.
-- =========================================================================

-- 1. Redefine resolve_tenant_commercial_eligibility
CREATE OR REPLACE FUNCTION public.resolve_tenant_commercial_eligibility(
    p_tenant_id UUID,
    p_at TIMESTAMPTZ DEFAULT now()
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_sub RECORD;
BEGIN
    IF p_tenant_id IS NULL THEN
        RETURN jsonb_build_object('eligible', false, 'reason_code', 'commercial_tenant_not_found');
    END IF;

    -- Check tenant exists
    IF NOT EXISTS (SELECT 1 FROM public.tenants WHERE id = p_tenant_id) THEN
        RETURN jsonb_build_object('eligible', false, 'reason_code', 'commercial_tenant_not_found');
    END IF;

    -- Get most recent subscription
    SELECT * INTO v_sub
    FROM public.subscriptions
    WHERE tenant_id = p_tenant_id
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_sub.id IS NULL THEN
        RETURN jsonb_build_object('eligible', false, 'reason_code', 'commercial_subscription_missing');
    END IF;

    IF v_sub.plan_version_id IS NULL THEN
        RETURN jsonb_build_object('eligible', false, 'reason_code', 'commercial_plan_version_missing');
    END IF;

    -- Validate plan version is published
    IF NOT EXISTS (
        SELECT 1 FROM public.plan_versions
        WHERE id = v_sub.plan_version_id AND lifecycle_status = 'published'
    ) THEN
        RETURN jsonb_build_object('eligible', false, 'reason_code', 'commercial_plan_version_not_effective');
    END IF;

    -- Lifecycle status check
    IF v_sub.status IN ('active', 'manual_active', 'comped') THEN
        RETURN jsonb_build_object(
            'eligible', true, 'reason_code', 'commercial_allowed',
            'subscription_id', v_sub.id, 'plan_version_id', v_sub.plan_version_id,
            'status', v_sub.status
        );
    END IF;

    IF v_sub.status = 'trialing' THEN
        IF v_sub.trial_end IS NULL OR NOT (v_sub.trial_end > COALESCE(p_at, now())) THEN
            RETURN jsonb_build_object('eligible', false, 'reason_code', 'commercial_trial_expired');
        END IF;
        RETURN jsonb_build_object(
            'eligible', true, 'reason_code', 'commercial_allowed',
            'subscription_id', v_sub.id, 'plan_version_id', v_sub.plan_version_id,
            'status', v_sub.status, 'trial_end', v_sub.trial_end
        );
    END IF;

    IF v_sub.status = 'past_due' THEN
        IF v_sub.grace_until IS NULL OR NOT (v_sub.grace_until > COALESCE(p_at, now())) THEN
            RETURN jsonb_build_object('eligible', false, 'reason_code', 'commercial_grace_expired');
        END IF;
        RETURN jsonb_build_object(
            'eligible', true, 'reason_code', 'commercial_allowed',
            'subscription_id', v_sub.id, 'plan_version_id', v_sub.plan_version_id,
            'status', v_sub.status, 'grace_until', v_sub.grace_until
        );
    END IF;

    -- All other statuses: denied
    RETURN jsonb_build_object('eligible', false, 'reason_code', 'commercial_status_not_eligible');
END;
$$;

REVOKE EXECUTE ON FUNCTION public.resolve_tenant_commercial_eligibility(UUID, TIMESTAMPTZ) FROM PUBLIC, anon, authenticated;

-- 2. Redefine resolve_effective_tenant_entitlements
CREATE OR REPLACE FUNCTION public.resolve_effective_tenant_entitlements(
    p_tenant_id UUID,
    p_at TIMESTAMPTZ DEFAULT now()
)
RETURNS TABLE (
    feature_key TEXT,
    value_type TEXT,
    boolean_value BOOLEAN,
    integer_value BIGINT,
    text_value TEXT,
    "json_value" JSONB,
    is_unlimited BOOLEAN,
    source TEXT,
    plan_version_id UUID,
    override_id UUID
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_effective_at        TIMESTAMPTZ := COALESCE(p_at, now());
    v_eligibility         JSONB;
    v_is_eligible         BOOLEAN := false;
    v_sub_plan_version_id UUID;
BEGIN
    IF p_tenant_id IS NULL THEN
        RETURN;
    END IF;

    -- Resolve canonical commercial eligibility and plan_version_id at v_effective_at
    v_eligibility := public.resolve_tenant_commercial_eligibility(p_tenant_id, v_effective_at);
    v_is_eligible := COALESCE((v_eligibility->>'eligible')::boolean, false);

    IF v_is_eligible THEN
        v_sub_plan_version_id := NULLIF(v_eligibility->>'plan_version_id', '')::uuid;
    ELSE
        v_sub_plan_version_id := NULL;
    END IF;

    RETURN QUERY
    WITH all_keys AS (
        SELECT f.feature_key AS fkey, f.value_type AS vtype
        FROM public.commercial_feature_definitions f
    ),
    -- Level 1: Platform / System Restriction (Highest Precedence)
    platform_rest AS (
        SELECT DISTINCT ON (pr.feature_key)
            pr.feature_key AS fkey
        FROM public.platform_system_restrictions pr
        WHERE (pr.tenant_id = p_tenant_id OR pr.tenant_id IS NULL)
          AND pr.is_restricted = true
          AND pr.starts_at <= v_effective_at
          AND (pr.expires_at IS NULL OR pr.expires_at > v_effective_at)
        ORDER BY pr.feature_key, pr.tenant_id NULLS LAST, pr.starts_at DESC
    ),
    -- Level 2: Active Tenant Override (applied when tenant is commercially eligible,
    -- or for structural/onboarding quota overrides on an active tenant with no subscription row yet)
    active_overrides AS (
        SELECT DISTINCT ON (o.feature_key)
            o.id AS ovr_id,
            o.feature_key AS fkey,
            o.value_type AS vtype,
            o.boolean_value AS bval,
            o.integer_value AS ival,
            o.text_value AS tval,
            o.json_value AS jval,
            o.is_unlimited AS unlim
        FROM public.tenant_entitlement_overrides o
        WHERE (
              v_is_eligible = true
              OR (
                  v_eligibility->>'reason_code' = 'commercial_subscription_missing'
                  AND o.feature_key IN ('max_branches', 'max_services', 'max_staff')
                  AND EXISTS (
                      SELECT 1
                      FROM public.tenants t
                      WHERE t.id = p_tenant_id
                        AND t.status IN ('active', 'manual_active')
                  )
              )
          )
          AND o.tenant_id = p_tenant_id
          AND o.starts_at <= v_effective_at
          AND (o.expires_at IS NULL OR o.expires_at > v_effective_at)
          AND o.revoked_at IS NULL
        ORDER BY o.feature_key, o.starts_at DESC, o.created_at DESC
    ),
    -- Level 3: Assigned Plan Version Default
    plan_defaults AS (
        SELECT
            pe.feature_key AS fkey,
            pe.value_type AS vtype,
            pe.boolean_value AS bval,
            pe.integer_value AS ival,
            pe.text_value AS tval,
            pe.json_value AS jval,
            pe.is_unlimited AS unlim
        FROM public.plan_entitlements pe
        WHERE pe.plan_version_id = v_sub_plan_version_id
    )
    SELECT
        k.fkey AS feature_key,
        k.vtype AS value_type,
        CASE
            WHEN pr.fkey IS NOT NULL AND k.vtype = 'boolean' THEN false
            WHEN pr.fkey IS NOT NULL THEN NULL
            WHEN o.ovr_id IS NOT NULL THEN o.bval
            WHEN pd.fkey IS NOT NULL THEN pd.bval
            WHEN k.vtype = 'boolean' THEN false
            ELSE NULL
        END AS boolean_value,
        CASE
            WHEN pr.fkey IS NOT NULL THEN 0::bigint
            WHEN o.ovr_id IS NOT NULL THEN o.ival
            WHEN pd.fkey IS NOT NULL THEN pd.ival
            WHEN k.vtype = 'integer' THEN 0::bigint
            ELSE NULL
        END AS integer_value,
        CASE
            WHEN pr.fkey IS NOT NULL THEN NULL
            WHEN o.ovr_id IS NOT NULL THEN o.tval
            WHEN pd.fkey IS NOT NULL THEN pd.tval
            ELSE NULL
        END AS text_value,
        CASE
            WHEN pr.fkey IS NOT NULL THEN NULL
            WHEN o.ovr_id IS NOT NULL THEN o.jval
            WHEN pd.fkey IS NOT NULL THEN pd.jval
            ELSE NULL
        END AS "json_value",
        CASE
            WHEN pr.fkey IS NOT NULL THEN false
            WHEN o.ovr_id IS NOT NULL THEN o.unlim
            WHEN pd.fkey IS NOT NULL THEN pd.unlim
            ELSE false
        END AS is_unlimited,
        CASE
            WHEN pr.fkey IS NOT NULL THEN 'platform_restriction'
            WHEN o.ovr_id IS NOT NULL THEN 'tenant_override'
            WHEN pd.fkey IS NOT NULL THEN 'plan_version'
            ELSE 'default_deny'
        END AS source,
        v_sub_plan_version_id AS plan_version_id,
        o.ovr_id AS override_id
    FROM all_keys k
    LEFT JOIN platform_rest pr ON pr.fkey = k.fkey
    LEFT JOIN active_overrides o ON o.fkey = k.fkey
    LEFT JOIN plan_defaults pd ON pd.fkey = k.fkey;
END;
$$;

REVOKE ALL ON FUNCTION public.resolve_effective_tenant_entitlements(UUID, TIMESTAMPTZ) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.resolve_effective_tenant_entitlements(UUID, TIMESTAMPTZ) TO authenticated, service_role;

-- =============================================================================
-- SOURCE: 20260928_lari_clinic_domain_server_authority.sql
-- =============================================================================
-- =========================================================================
-- Ported from 72911e4: 20260905_lari_clinic_domain_server_authority.sql
-- Conflict-free sequential prefix: 20260928 (ADIM-036 / Faz E1)
-- Description: Foundational Clinical Domain & Server Authority for LARİ Clinic V1
-- Security Hardening:
--   - Direct table DML & SELECT revoked from PUBLIC, anon, authenticated.
--   - Append-only immutability trigger on public.clinic_encounter_notes.
--   - Composite tenant-scoped FKs enforced.
-- =========================================================================

-- 1. CLINIC STAFF PROFILES TABLE
CREATE TABLE IF NOT EXISTS public.clinic_staff_profiles (
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    staff_id UUID PRIMARY KEY REFERENCES public.staff(id) ON DELETE CASCADE,
    practitioner_type TEXT NULL,
    specialty TEXT NULL,
    medical_license_number TEXT NULL,
    can_manage_patient_profiles BOOLEAN NOT NULL DEFAULT false,
    can_view_clinical_records BOOLEAN NOT NULL DEFAULT false,
    can_write_clinical_notes BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_clinic_staff_profiles_staff_tenant UNIQUE (staff_id, tenant_id),
    CONSTRAINT chk_clinic_staff_note_view_dependency CHECK (
        can_write_clinical_notes = false OR can_view_clinical_records = true
    )
);

CREATE INDEX IF NOT EXISTS idx_clinic_staff_profiles_tenant_id ON public.clinic_staff_profiles(tenant_id);

-- Enforce composite tenant alignment with public.staff (id, tenant_id)
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'uq_staff_id_tenant'
    ) THEN
        IF NOT EXISTS (
            SELECT 1 FROM pg_constraint WHERE conname = 'fk_clinic_staff_profiles_staff_tenant'
        ) THEN
            ALTER TABLE public.clinic_staff_profiles
            ADD CONSTRAINT fk_clinic_staff_profiles_staff_tenant
            FOREIGN KEY (staff_id, tenant_id)
            REFERENCES public.staff(id, tenant_id)
            ON DELETE CASCADE;
        END IF;
    END IF;
END $$;

DROP TRIGGER IF EXISTS update_clinic_staff_profiles_modtime ON public.clinic_staff_profiles;
CREATE TRIGGER update_clinic_staff_profiles_modtime
BEFORE UPDATE ON public.clinic_staff_profiles
FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE public.clinic_staff_profiles ENABLE ROW LEVEL SECURITY;


-- 2. CLINIC PATIENT PROFILES TABLE
CREATE TABLE IF NOT EXISTS public.clinic_patient_profiles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    customer_id UUID NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE,
    date_of_birth DATE NULL,
    sex_at_birth TEXT NULL,
    emergency_contact_name TEXT NULL,
    emergency_contact_phone TEXT NULL,
    emergency_contact_relationship TEXT NULL,
    blood_type TEXT NULL,
    allergies TEXT NULL,
    chronic_conditions TEXT NULL,
    created_by UUID NULL REFERENCES public.users_profile(id) ON DELETE SET NULL,
    updated_by UUID NULL REFERENCES public.users_profile(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_clinic_patient_profiles_tenant_customer UNIQUE (tenant_id, customer_id)
);

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'uq_customers_id_tenant'
    ) THEN
        IF NOT EXISTS (
            SELECT 1 FROM pg_constraint WHERE conname = 'fk_clinic_patient_profiles_customer_tenant'
        ) THEN
            ALTER TABLE public.clinic_patient_profiles
            ADD CONSTRAINT fk_clinic_patient_profiles_customer_tenant
            FOREIGN KEY (customer_id, tenant_id)
            REFERENCES public.customers(id, tenant_id)
            ON DELETE CASCADE;
        END IF;
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_clinic_patient_profiles_tenant_customer ON public.clinic_patient_profiles(tenant_id, customer_id);

DROP TRIGGER IF EXISTS update_clinic_patient_profiles_modtime ON public.clinic_patient_profiles;
CREATE TRIGGER update_clinic_patient_profiles_modtime
BEFORE UPDATE ON public.clinic_patient_profiles
FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE public.clinic_patient_profiles ENABLE ROW LEVEL SECURITY;


-- 3. CLINIC ENCOUNTERS TABLE
CREATE TABLE IF NOT EXISTS public.clinic_encounters (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    appointment_id UUID NOT NULL REFERENCES public.appointments(id) ON DELETE CASCADE,
    customer_id UUID NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE,
    practitioner_staff_id UUID NOT NULL REFERENCES public.staff(id) ON DELETE RESTRICT,
    branch_id UUID NOT NULL REFERENCES public.branches(id) ON DELETE RESTRICT,
    status TEXT NOT NULL,
    reason_for_visit TEXT NULL,
    started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at TIMESTAMPTZ NULL,
    created_by UUID NOT NULL REFERENCES public.users_profile(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_clinic_encounters_status CHECK (status IN ('open', 'completed', 'voided')),
    CONSTRAINT uq_clinic_encounters_appointment UNIQUE (appointment_id)
);

CREATE INDEX IF NOT EXISTS idx_clinic_encounters_tenant_id ON public.clinic_encounters(tenant_id);
CREATE INDEX IF NOT EXISTS idx_clinic_encounters_customer_id ON public.clinic_encounters(customer_id);
CREATE INDEX IF NOT EXISTS idx_clinic_encounters_practitioner ON public.clinic_encounters(practitioner_staff_id);

DROP TRIGGER IF EXISTS update_clinic_encounters_modtime ON public.clinic_encounters;
CREATE TRIGGER update_clinic_encounters_modtime
BEFORE UPDATE ON public.clinic_encounters
FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE public.clinic_encounters ENABLE ROW LEVEL SECURITY;


-- 4. CLINIC ENCOUNTER NOTES TABLE (APPEND-ONLY & VERSIONED)
CREATE TABLE IF NOT EXISTS public.clinic_encounter_notes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    encounter_id UUID NOT NULL REFERENCES public.clinic_encounters(id) ON DELETE CASCADE,
    author_staff_id UUID NOT NULL REFERENCES public.staff(id) ON DELETE RESTRICT,
    version INTEGER NOT NULL,
    subjective TEXT NULL,
    objective TEXT NULL,
    assessment TEXT NULL,
    plan TEXT NULL,
    note_status TEXT NOT NULL DEFAULT 'draft',
    supersedes_note_id UUID NULL REFERENCES public.clinic_encounter_notes(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_clinic_encounter_notes_status CHECK (note_status IN ('draft', 'final')),
    CONSTRAINT chk_clinic_encounter_notes_version CHECK (version > 0),
    CONSTRAINT uq_clinic_encounter_notes_encounter_version UNIQUE (encounter_id, version)
);

CREATE INDEX IF NOT EXISTS idx_clinic_encounter_notes_encounter ON public.clinic_encounter_notes(encounter_id, version DESC);

CREATE OR REPLACE FUNCTION public.prevent_clinic_encounter_notes_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
    RAISE EXCEPTION 'CLINIC_ENCOUNTER_NOTES_IMMUTABLE: Clinical encounter notes are strictly append-only.';
END;
$$;

DROP TRIGGER IF EXISTS trg_prevent_clinic_encounter_notes_mutation ON public.clinic_encounter_notes;
DROP TRIGGER IF EXISTS trg_prevent_clinic_encounter_notes_mutation ON public.clinic_encounter_notes;
CREATE TRIGGER trg_prevent_clinic_encounter_notes_mutation
BEFORE UPDATE OR DELETE ON public.clinic_encounter_notes
FOR EACH ROW EXECUTE FUNCTION public.prevent_clinic_encounter_notes_mutation();

ALTER TABLE public.clinic_encounter_notes ENABLE ROW LEVEL SECURITY;


-- =========================================================================
-- 5. RLS POLICIES & PRIVILEGE HARDENING
-- Direct browser table access is revoked; all mutations/reads use SECURITY DEFINER RPCs.
-- =========================================================================

REVOKE ALL ON TABLE public.clinic_staff_profiles FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.clinic_patient_profiles FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.clinic_encounters FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.clinic_encounter_notes FROM PUBLIC, anon, authenticated;

GRANT ALL ON TABLE public.clinic_staff_profiles TO service_role;
GRANT ALL ON TABLE public.clinic_patient_profiles TO service_role;
GRANT ALL ON TABLE public.clinic_encounters TO service_role;
GRANT ALL ON TABLE public.clinic_encounter_notes TO service_role;

-- public.clinic_staff_profiles RLS
DROP POLICY IF EXISTS "No anon access on clinic_staff_profiles" ON public.clinic_staff_profiles;
DROP POLICY IF EXISTS "Authorized tenant owner can manage clinic staff profiles" ON public.clinic_staff_profiles;
DROP POLICY IF EXISTS "Authorized tenant staff can read clinic staff profiles" ON public.clinic_staff_profiles;

DROP POLICY IF EXISTS "Authorized tenant staff can read clinic staff profiles" ON public.clinic_staff_profiles;
CREATE POLICY "Authorized tenant staff can read clinic staff profiles"
ON public.clinic_staff_profiles
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = clinic_staff_profiles.tenant_id
          AND s.active = true
    )
);


-- public.clinic_patient_profiles RLS
DROP POLICY IF EXISTS "Authorized staff can read clinic_patient_profiles" ON public.clinic_patient_profiles;

DROP POLICY IF EXISTS "Authorized staff can read clinic_patient_profiles" ON public.clinic_patient_profiles;
CREATE POLICY "Authorized staff can read clinic_patient_profiles"
ON public.clinic_patient_profiles
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.clinic_staff_profiles csp ON csp.staff_id = s.id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = clinic_patient_profiles.tenant_id
          AND s.active = true
          AND (csp.can_manage_patient_profiles = true OR csp.can_view_clinical_records = true)
    )
);


-- public.clinic_encounters RLS
DROP POLICY IF EXISTS "Authorized staff can read clinic_encounters" ON public.clinic_encounters;

DROP POLICY IF EXISTS "Authorized staff can read clinic_encounters" ON public.clinic_encounters;
CREATE POLICY "Authorized staff can read clinic_encounters"
ON public.clinic_encounters
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.clinic_staff_profiles csp ON csp.staff_id = s.id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = clinic_encounters.tenant_id
          AND s.active = true
          AND csp.can_view_clinical_records = true
    )
);


-- public.clinic_encounter_notes RLS
DROP POLICY IF EXISTS "Authorized staff can read clinic_encounter_notes" ON public.clinic_encounter_notes;

DROP POLICY IF EXISTS "Authorized staff can read clinic_encounter_notes" ON public.clinic_encounter_notes;
CREATE POLICY "Authorized staff can read clinic_encounter_notes"
ON public.clinic_encounter_notes
FOR SELECT
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM public.staff s
        JOIN public.clinic_staff_profiles csp ON csp.staff_id = s.id
        WHERE s.user_profile_id = auth.uid()
          AND s.tenant_id = clinic_encounter_notes.tenant_id
          AND s.active = true
          AND csp.can_view_clinical_records = true
    )
);


-- =========================================================================
-- 6. SERVER-AUTHORITATIVE RPC CONTRACTS
-- =========================================================================

-- A. clinic_set_staff_profile
CREATE OR REPLACE FUNCTION public.clinic_set_staff_profile(
    p_staff_id UUID,
    p_practitioner_type TEXT DEFAULT NULL,
    p_specialty TEXT DEFAULT NULL,
    p_medical_license_number TEXT DEFAULT NULL,
    p_can_manage_patient_profiles BOOLEAN DEFAULT false,
    p_can_view_clinical_records BOOLEAN DEFAULT false,
    p_can_write_clinical_notes BOOLEAN DEFAULT false
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_caller_up RECORD;
    v_target_staff RECORD;
    v_can_view BOOLEAN := p_can_view_clinical_records;
    v_res RECORD;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT * INTO v_target_staff
    FROM public.staff
    WHERE id = p_staff_id;

    IF v_target_staff.id IS NULL THEN
        RAISE EXCEPTION 'NOT_FOUND: Staff member not found.';
    END IF;

    IF v_target_staff.active IS NOT TRUE THEN
        RAISE EXCEPTION 'INVALID_STATE: Target staff member is inactive and cannot receive Clinic capabilities.';
    END IF;

    SELECT * INTO v_caller_up
    FROM public.users_profile
    WHERE id = v_caller_uid
      AND tenant_id = v_target_staff.tenant_id
      AND role = 'tenant_owner'
      AND active = true;

    IF v_caller_up.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Only active tenant owner of the exact tenant can set Clinic staff profile.';
    END IF;

    IF p_can_write_clinical_notes = true THEN
        v_can_view := true;
    END IF;

    INSERT INTO public.clinic_staff_profiles (
        tenant_id,
        staff_id,
        practitioner_type,
        specialty,
        medical_license_number,
        can_manage_patient_profiles,
        can_view_clinical_records,
        can_write_clinical_notes,
        updated_at
    ) VALUES (
        v_target_staff.tenant_id,
        p_staff_id,
        p_practitioner_type,
        p_specialty,
        p_medical_license_number,
        p_can_manage_patient_profiles,
        v_can_view,
        p_can_write_clinical_notes,
        now()
    )
    ON CONFLICT (staff_id) DO UPDATE SET
        practitioner_type = EXCLUDED.practitioner_type,
        specialty = EXCLUDED.specialty,
        medical_license_number = EXCLUDED.medical_license_number,
        can_manage_patient_profiles = EXCLUDED.can_manage_patient_profiles,
        can_view_clinical_records = EXCLUDED.can_view_clinical_records,
        can_write_clinical_notes = EXCLUDED.can_write_clinical_notes,
        updated_at = now()
    RETURNING * INTO v_res;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_target_staff.tenant_id::text,
        v_caller_uid::text,
        'tenant_owner',
        'clinic_staff_profile_changed',
        'clinic_staff_profiles',
        p_staff_id::text,
        jsonb_build_object(
            'staff_id', p_staff_id,
            'can_manage_patient_profiles', p_can_manage_patient_profiles,
            'can_view_clinical_records', v_can_view,
            'can_write_clinical_notes', p_can_write_clinical_notes
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'staff_id', v_res.staff_id,
        'tenant_id', v_res.tenant_id,
        'can_manage_patient_profiles', v_res.can_manage_patient_profiles,
        'can_view_clinical_records', v_res.can_view_clinical_records,
        'can_write_clinical_notes', v_res.can_write_clinical_notes
    );
END;
$$;


-- B. clinic_upsert_patient_profile
CREATE OR REPLACE FUNCTION public.clinic_upsert_patient_profile(
    p_customer_id UUID,
    p_date_of_birth DATE DEFAULT NULL,
    p_sex_at_birth TEXT DEFAULT NULL,
    p_emergency_contact_name TEXT DEFAULT NULL,
    p_emergency_contact_phone TEXT DEFAULT NULL,
    p_emergency_contact_relationship TEXT DEFAULT NULL,
    p_blood_type TEXT DEFAULT NULL,
    p_allergies TEXT DEFAULT NULL,
    p_chronic_conditions TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_csp RECORD;
    v_customer RECORD;
    v_res RECORD;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active staff identity.';
    END IF;

    SELECT * INTO v_csp
    FROM public.clinic_staff_profiles
    WHERE staff_id = v_staff.id;

    IF v_csp.staff_id IS NULL OR (v_csp.can_manage_patient_profiles = false AND v_csp.can_view_clinical_records = false) THEN
        RAISE EXCEPTION 'FORBIDDEN: Insufficient Clinic permissions to manage patient profiles.';
    END IF;

    SELECT * INTO v_customer
    FROM public.customers
    WHERE id = p_customer_id
      AND tenant_id = v_staff.tenant_id;

    IF v_customer.id IS NULL THEN
        RAISE EXCEPTION 'NOT_FOUND: Customer not found or tenant mismatch.';
    END IF;

    INSERT INTO public.clinic_patient_profiles (
        tenant_id,
        customer_id,
        date_of_birth,
        sex_at_birth,
        emergency_contact_name,
        emergency_contact_phone,
        emergency_contact_relationship,
        blood_type,
        allergies,
        chronic_conditions,
        created_by,
        updated_by,
        updated_at
    ) VALUES (
        v_staff.tenant_id,
        p_customer_id,
        p_date_of_birth,
        p_sex_at_birth,
        p_emergency_contact_name,
        p_emergency_contact_phone,
        p_emergency_contact_relationship,
        p_blood_type,
        p_allergies,
        p_chronic_conditions,
        v_caller_uid,
        v_caller_uid,
        now()
    )
    ON CONFLICT (tenant_id, customer_id) DO UPDATE SET
        date_of_birth = EXCLUDED.date_of_birth,
        sex_at_birth = EXCLUDED.sex_at_birth,
        emergency_contact_name = EXCLUDED.emergency_contact_name,
        emergency_contact_phone = EXCLUDED.emergency_contact_phone,
        emergency_contact_relationship = EXCLUDED.emergency_contact_relationship,
        blood_type = EXCLUDED.blood_type,
        allergies = EXCLUDED.allergies,
        chronic_conditions = EXCLUDED.chronic_conditions,
        updated_by = v_caller_uid,
        updated_at = now()
    RETURNING * INTO v_res;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_staff.tenant_id::text,
        v_caller_uid::text,
        'staff',
        'clinic_patient_profile_changed',
        'clinic_patient_profiles',
        v_res.id::text,
        jsonb_build_object(
            'customer_id', p_customer_id,
            'patient_profile_id', v_res.id,
            'staff_id', v_staff.id
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'patient_profile_id', v_res.id,
        'customer_id', v_res.customer_id,
        'tenant_id', v_res.tenant_id
    );
END;
$$;


-- C. clinic_start_encounter
CREATE OR REPLACE FUNCTION public.clinic_start_encounter(
    p_appointment_id UUID,
    p_reason_for_visit TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_csp RECORD;
    v_appointment RECORD;
    v_existing_encounter RECORD;
    v_encounter RECORD;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(p_appointment_id::text, 0));

    SELECT s.* INTO v_staff
    FROM public.staff s
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active staff identity.';
    END IF;

    SELECT * INTO v_csp
    FROM public.clinic_staff_profiles
    WHERE staff_id = v_staff.id;

    IF v_csp.staff_id IS NULL OR v_csp.can_write_clinical_notes = false THEN
        RAISE EXCEPTION 'FORBIDDEN: Practitioner lacks can_write_clinical_notes capability.';
    END IF;

    SELECT * INTO v_appointment
    FROM public.appointments
    WHERE id = p_appointment_id;

    IF v_appointment.id IS NULL THEN
        RAISE EXCEPTION 'NOT_FOUND: Appointment not found.';
    END IF;

    IF v_appointment.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'FORBIDDEN: Tenant mismatch on appointment.';
    END IF;

    IF v_appointment.staff_id <> v_staff.id THEN
        RAISE EXCEPTION 'FORBIDDEN: Only the practitioner assigned to the appointment can start the encounter.';
    END IF;

    IF v_appointment.customer_id IS NULL THEN
        RAISE EXCEPTION 'INVALID_STATE: Appointment has no registered customer.';
    END IF;

    SELECT * INTO v_existing_encounter
    FROM public.clinic_encounters
    WHERE appointment_id = p_appointment_id;

    IF v_existing_encounter.id IS NOT NULL THEN
        RAISE EXCEPTION 'ALREADY_EXISTS: An encounter already exists for this appointment.';
    END IF;

    INSERT INTO public.clinic_encounters (
        tenant_id,
        appointment_id,
        customer_id,
        practitioner_staff_id,
        branch_id,
        status,
        reason_for_visit,
        started_at,
        created_by,
        created_at,
        updated_at
    ) VALUES (
        v_staff.tenant_id,
        p_appointment_id,
        v_appointment.customer_id,
        v_staff.id,
        v_appointment.branch_id,
        'open',
        p_reason_for_visit,
        now(),
        v_caller_uid,
        now(),
        now()
    )
    RETURNING * INTO v_encounter;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_staff.tenant_id::text,
        v_caller_uid::text,
        'staff',
        'clinic_encounter_started',
        'clinic_encounters',
        v_encounter.id::text,
        jsonb_build_object(
            'encounter_id', v_encounter.id,
            'appointment_id', p_appointment_id,
            'customer_id', v_appointment.customer_id,
            'practitioner_staff_id', v_staff.id
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'encounter_id', v_encounter.id,
        'appointment_id', v_encounter.appointment_id,
        'status', v_encounter.status,
        'started_at', v_encounter.started_at
    );
END;
$$;


-- D. clinic_save_encounter_note
CREATE OR REPLACE FUNCTION public.clinic_save_encounter_note(
    p_encounter_id UUID,
    p_subjective TEXT DEFAULT NULL,
    p_objective TEXT DEFAULT NULL,
    p_assessment TEXT DEFAULT NULL,
    p_plan TEXT DEFAULT NULL,
    p_note_status TEXT DEFAULT 'draft'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_csp RECORD;
    v_vert_ctx JSONB;
    v_encounter RECORD;
    v_latest_note RECORD;
    v_next_version INTEGER := 1;
    v_new_note RECORD;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    IF p_note_status NOT IN ('draft', 'final') THEN
        RAISE EXCEPTION 'INVALID_ARGUMENT: Allowed note_status values are draft or final.';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(p_encounter_id::text, 0));

    SELECT s.* INTO v_staff
    FROM public.staff s
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active staff identity.';
    END IF;

    SELECT * INTO v_csp
    FROM public.clinic_staff_profiles
    WHERE staff_id = v_staff.id;

    IF v_csp.staff_id IS NULL OR v_csp.can_write_clinical_notes = false THEN
        RAISE EXCEPTION 'FORBIDDEN: Practitioner lacks can_write_clinical_notes capability.';
    END IF;

    v_vert_ctx := public.resolve_tenant_vertical_context(v_staff.tenant_id);
    IF (v_vert_ctx->>'eligible')::boolean IS NOT TRUE
       OR (v_vert_ctx->'verticals'->>'clinic_enabled')::boolean IS NOT TRUE THEN
        RAISE EXCEPTION 'FORBIDDEN: Clinic workspace vertical is not currently eligible or enabled (%).',
            COALESCE(v_vert_ctx->>'reason_code', 'INELIGIBLE');
    END IF;

    SELECT * INTO v_encounter
    FROM public.clinic_encounters
    WHERE id = p_encounter_id;

    IF v_encounter.id IS NULL THEN
        RAISE EXCEPTION 'NOT_FOUND: Encounter not found.';
    END IF;

    IF v_encounter.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'FORBIDDEN: Tenant mismatch on encounter.';
    END IF;

    IF v_encounter.practitioner_staff_id <> v_staff.id THEN
        RAISE EXCEPTION 'FORBIDDEN: Only the practitioner assigned to the encounter can save clinical notes.';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.staff_branches sb
        WHERE sb.tenant_id = v_staff.tenant_id
          AND sb.staff_id = v_staff.id
          AND sb.branch_id = v_encounter.branch_id
    ) THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller staff is not currently assigned to the encounter branch.';
    END IF;

    IF v_encounter.status = 'completed' OR v_encounter.status = 'voided' THEN
        RAISE EXCEPTION 'INVALID_STATE: Cannot add or update notes on a completed or voided encounter.';
    END IF;

    SELECT * INTO v_latest_note
    FROM public.clinic_encounter_notes
    WHERE encounter_id = p_encounter_id
    ORDER BY version DESC
    LIMIT 1;

    IF v_latest_note.id IS NOT NULL THEN
        v_next_version := v_latest_note.version + 1;
    END IF;

    INSERT INTO public.clinic_encounter_notes (
        tenant_id,
        encounter_id,
        author_staff_id,
        version,
        subjective,
        objective,
        assessment,
        plan,
        note_status,
        supersedes_note_id,
        created_at
    ) VALUES (
        v_staff.tenant_id,
        p_encounter_id,
        v_staff.id,
        v_next_version,
        p_subjective,
        p_objective,
        p_assessment,
        p_plan,
        p_note_status,
        v_latest_note.id,
        now()
    )
    RETURNING * INTO v_new_note;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_staff.tenant_id::text,
        v_caller_uid::text,
        'staff',
        'clinic_encounter_note_version_created',
        'clinic_encounter_notes',
        v_new_note.id::text,
        jsonb_build_object(
            'encounter_id', p_encounter_id,
            'note_id', v_new_note.id,
            'version', v_next_version,
            'note_status', p_note_status,
            'author_staff_id', v_staff.id
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'note_id', v_new_note.id,
        'encounter_id', v_new_note.encounter_id,
        'version', v_new_note.version,
        'note_status', v_new_note.note_status,
        'created_at', v_new_note.created_at
    );
END;
$$;


-- E. clinic_complete_encounter
CREATE OR REPLACE FUNCTION public.clinic_complete_encounter(
    p_encounter_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_csp RECORD;
    v_encounter RECORD;
    v_res RECORD;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(p_encounter_id::text, 0));

    SELECT s.* INTO v_staff
    FROM public.staff s
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active staff identity.';
    END IF;

    SELECT * INTO v_csp
    FROM public.clinic_staff_profiles
    WHERE staff_id = v_staff.id;

    IF v_csp.staff_id IS NULL OR v_csp.can_write_clinical_notes = false THEN
        RAISE EXCEPTION 'FORBIDDEN: Practitioner lacks write capability.';
    END IF;

    SELECT * INTO v_encounter
    FROM public.clinic_encounters
    WHERE id = p_encounter_id;

    IF v_encounter.id IS NULL THEN
        RAISE EXCEPTION 'NOT_FOUND: Encounter not found.';
    END IF;

    IF v_encounter.tenant_id <> v_staff.tenant_id THEN
        RAISE EXCEPTION 'FORBIDDEN: Tenant mismatch on encounter.';
    END IF;

    IF v_encounter.practitioner_staff_id <> v_staff.id THEN
        RAISE EXCEPTION 'FORBIDDEN: Only assigned practitioner can complete the encounter.';
    END IF;

    IF v_encounter.status <> 'open' THEN
        RAISE EXCEPTION 'INVALID_STATE: Encounter is not in open status.';
    END IF;

    UPDATE public.clinic_encounters
    SET status = 'completed',
        completed_at = now(),
        updated_at = now()
    WHERE id = p_encounter_id
    RETURNING * INTO v_res;

    INSERT INTO public.audit_events (
        tenant_id,
        actor_id,
        actor_role,
        action,
        resource_type,
        resource_id,
        payload
    ) VALUES (
        v_staff.tenant_id::text,
        v_caller_uid::text,
        'staff',
        'clinic_encounter_completed',
        'clinic_encounters',
        p_encounter_id::text,
        jsonb_build_object(
            'encounter_id', p_encounter_id,
            'appointment_id', v_res.appointment_id,
            'completed_at', v_res.completed_at
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'encounter_id', v_res.id,
        'status', v_res.status,
        'completed_at', v_res.completed_at
    );
END;
$$;


-- F. clinic_get_patient_history
CREATE OR REPLACE FUNCTION public.clinic_get_patient_history(
    p_customer_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_caller_uid UUID := auth.uid();
    v_staff RECORD;
    v_csp RECORD;
    v_customer RECORD;
    v_patient_profile RECORD;
    v_encounters JSONB;
BEGIN
    IF v_caller_uid IS NULL THEN
        RAISE EXCEPTION 'UNAUTHENTICATED: Authentication required.';
    END IF;

    SELECT s.* INTO v_staff
    FROM public.staff s
    WHERE s.user_profile_id = v_caller_uid
      AND s.active = true;

    IF v_staff.id IS NULL THEN
        RAISE EXCEPTION 'FORBIDDEN: Caller has no active staff identity.';
    END IF;

    SELECT * INTO v_csp
    FROM public.clinic_staff_profiles
    WHERE staff_id = v_staff.id;

    IF v_csp.staff_id IS NULL OR v_csp.can_view_clinical_records = false THEN
        RAISE EXCEPTION 'FORBIDDEN: Staff lacks can_view_clinical_records capability.';
    END IF;

    SELECT * INTO v_customer
    FROM public.customers
    WHERE id = p_customer_id
      AND tenant_id = v_staff.tenant_id;

    IF v_customer.id IS NULL THEN
        RAISE EXCEPTION 'NOT_FOUND: Customer not found or cross-tenant access denied.';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.staff_branches sb
        WHERE sb.tenant_id = v_staff.tenant_id
          AND sb.staff_id = v_staff.id
          AND (
              EXISTS (
                  SELECT 1
                  FROM public.appointments a
                  WHERE a.tenant_id = v_staff.tenant_id
                    AND a.customer_id = p_customer_id
                    AND a.branch_id = sb.branch_id
              )
              OR EXISTS (
                  SELECT 1
                  FROM public.clinic_encounters e
                  WHERE e.tenant_id = v_staff.tenant_id
                    AND e.customer_id = p_customer_id
                    AND e.branch_id = sb.branch_id
              )
          )
    ) THEN
        RAISE EXCEPTION 'FORBIDDEN: Customer has no appointment or encounter in caller''s permitted branches.';
    END IF;

    SELECT * INTO v_patient_profile
    FROM public.clinic_patient_profiles
    WHERE customer_id = p_customer_id
      AND tenant_id = v_staff.tenant_id;

    SELECT coalesce(jsonb_agg(
        jsonb_build_object(
            'id', e.id,
            'appointment_id', e.appointment_id,
            'branch_id', e.branch_id,
            'practitioner_staff_id', e.practitioner_staff_id,
            'status', e.status,
            'reason_for_visit', e.reason_for_visit,
            'started_at', e.started_at,
            'completed_at', e.completed_at,
            'notes', (
                SELECT coalesce(jsonb_agg(
                    jsonb_build_object(
                        'id', n.id,
                        'version', n.version,
                        'author_staff_id', n.author_staff_id,
                        'subjective', n.subjective,
                        'objective', n.objective,
                        'assessment', n.assessment,
                        'plan', n.plan,
                        'note_status', n.note_status,
                        'supersedes_note_id', n.supersedes_note_id,
                        'created_at', n.created_at
                    ) ORDER BY n.version ASC
                ), '[]'::jsonb)
                FROM public.clinic_encounter_notes n
                WHERE n.encounter_id = e.id
            )
        ) ORDER BY e.started_at DESC
    ), '[]'::jsonb) INTO v_encounters
    FROM public.clinic_encounters e
    WHERE e.customer_id = p_customer_id
      AND e.tenant_id = v_staff.tenant_id
      AND EXISTS (
          SELECT 1
          FROM public.staff_branches sb
          WHERE sb.tenant_id = v_staff.tenant_id
            AND sb.staff_id = v_staff.id
            AND sb.branch_id = e.branch_id
      );

    RETURN jsonb_build_object(
        'success', true,
        'customer_id', p_customer_id,
        'tenant_id', v_staff.tenant_id,
        'patient_profile', CASE WHEN v_patient_profile.id IS NOT NULL THEN jsonb_build_object(
            'id', v_patient_profile.id,
            'date_of_birth', v_patient_profile.date_of_birth,
            'sex_at_birth', v_patient_profile.sex_at_birth,
            'emergency_contact_name', v_patient_profile.emergency_contact_name,
            'emergency_contact_phone', v_patient_profile.emergency_contact_phone,
            'emergency_contact_relationship', v_patient_profile.emergency_contact_relationship,
            'blood_type', v_patient_profile.blood_type,
            'allergies', v_patient_profile.allergies,
            'chronic_conditions', v_patient_profile.chronic_conditions,
            'updated_at', v_patient_profile.updated_at
        ) ELSE NULL END,
        'encounters', v_encounters
    );
END;
$$;


