-- 3. SEED PUBLISHED VERSION 1 FOR VERTICAL PLANS
DO $$
DECLARE
    v_clinic_starter_id    UUID;
    v_clinic_pro_id        UUID;
    v_ht_starter_id        UUID;
    v_ht_enterprise_id     UUID;

    v_clinic_starter_ver_id UUID;
