GRANT EXECUTE ON FUNCTION public.get_discovery_marketplace_detail(TEXT) TO anon, authenticated, service_role;

-- =============================================================================
-- SOURCE: 20261010_phase7_node3_favorites_fast_rebooking.sql
-- =============================================================================
-- =========================================================================
-- MIGRATION 20261010_phase7_node3_favorites_fast_rebooking.sql
-- Description: Phase 7 Node 3 — Favorites and Fast-Rebooking Server Foundation
-- Canonical Migration Number: 96
-- Program: LARI-V2-EXPANSION-ADIM-037
-- Production: NO_GO
--
-- This migration adds only:
--   1. an authenticated user's relationship to an existing canonical tenant;
--   2. a manage-token-authorized projection of current booking inputs.
--
-- It does not create customer, business, service, staff, or booking truth. It
-- does not create appointments. A fast-rebooking caller must select a current
-- slot through evaluate_booking_slot and create the appointment through the
-- canonical create_public_booking transaction.
-- =========================================================================

-- =========================================================================
-- 1. FAVORITES RELATIONSHIP
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.customer_favorites (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    customer_user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    tenant_id        UUID NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_customer_favorites_user_tenant UNIQUE (customer_user_id, tenant_id)
);

CREATE INDEX IF NOT EXISTS idx_customer_favorites_user_id
    ON public.customer_favorites(customer_user_id);

CREATE INDEX IF NOT EXISTS idx_customer_favorites_tenant_id
    ON public.customer_favorites(tenant_id);

ALTER TABLE public.customer_favorites ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS customer_favorites_select_own ON public.customer_favorites;
CREATE POLICY customer_favorites_select_own
    ON public.customer_favorites
    FOR SELECT
    TO authenticated
    USING ((SELECT auth.uid()) IS NOT NULL AND customer_user_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS customer_favorites_insert_own ON public.customer_favorites;
CREATE POLICY customer_favorites_insert_own
    ON public.customer_favorites
    FOR INSERT
    TO authenticated
    WITH CHECK ((SELECT auth.uid()) IS NOT NULL AND customer_user_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS customer_favorites_delete_own ON public.customer_favorites;
CREATE POLICY customer_favorites_delete_own
    ON public.customer_favorites
    FOR DELETE
    TO authenticated
    USING ((SELECT auth.uid()) IS NOT NULL AND customer_user_id = (SELECT auth.uid()));

REVOKE ALL ON TABLE public.customer_favorites FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public.customer_favorites TO service_role;

CREATE OR REPLACE FUNCTION public.set_customer_favorite(
    p_tenant_id   UUID,
    p_is_favorite BOOLEAN DEFAULT true
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user_id          UUID;
    v_favorite_id      UUID;
    v_target_eligible  BOOLEAN := false;
    v_action           TEXT;
BEGIN
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'UNAUTHENTICATED');
    END IF;

    IF p_tenant_id IS NULL OR p_is_favorite IS NULL THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'INVALID_ARGUMENTS');
    END IF;

    IF p_is_favorite THEN
        SELECT EXISTS (
            SELECT 1
            FROM public.tenants t
            JOIN public.tenant_business_profiles bp ON bp.tenant_id = t.id
            WHERE t.id = p_tenant_id
              AND t.status IN ('active', 'manual_active')
              AND t.onboarding_status = 'completed'
              AND t.public_site_status = 'published'
              AND bp.is_public_profile_enabled IS TRUE
              AND COALESCE(
                    (public.evaluate_public_booking_eligibility_internal(t.id, t.slug)->>'bookable')::BOOLEAN,
                    false
                  ) IS TRUE
        ) INTO v_target_eligible;

        IF NOT v_target_eligible THEN
            RETURN jsonb_build_object('success', false, 'reason_code', 'TARGET_NOT_ELIGIBLE');
        END IF;

        INSERT INTO public.customer_favorites (customer_user_id, tenant_id)
        VALUES (v_user_id, p_tenant_id)
        ON CONFLICT (customer_user_id, tenant_id) DO NOTHING
        RETURNING id INTO v_favorite_id;

        IF v_favorite_id IS NULL THEN
            SELECT cf.id
            INTO v_favorite_id
            FROM public.customer_favorites cf
            WHERE cf.customer_user_id = v_user_id
              AND cf.tenant_id = p_tenant_id;
            v_action := 'UNCHANGED';
        ELSE
            v_action := 'ADDED';
        END IF;

        RETURN jsonb_build_object(
            'success', true,
            'reason_code', 'OK',
            'action', v_action,
            'favorite_id', v_favorite_id,
            'is_favorite', true
        );
    END IF;

    DELETE FROM public.customer_favorites cf
    WHERE cf.customer_user_id = v_user_id
      AND cf.tenant_id = p_tenant_id
    RETURNING cf.id INTO v_favorite_id;

    v_action := CASE WHEN v_favorite_id IS NULL THEN 'UNCHANGED' ELSE 'REMOVED' END;

    RETURN jsonb_build_object(
        'success', true,
        'reason_code', 'OK',
        'action', v_action,
        'favorite_id', v_favorite_id,
        'is_favorite', false
    );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_customer_favorites(
    p_limit  INTEGER DEFAULT 50,
    p_offset INTEGER DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_user_id     UUID;
    v_eff_limit   INTEGER;
    v_eff_offset  INTEGER;
    v_favorites   JSONB;
    v_total       INTEGER;
BEGIN
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'UNAUTHENTICATED');
    END IF;

    v_eff_limit := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
    v_eff_offset := GREATEST(COALESCE(p_offset, 0), 0);

    WITH eligible AS (
        SELECT cf.id, cf.tenant_id, cf.created_at, t.slug, t.name
        FROM public.customer_favorites cf
        JOIN public.tenants t ON t.id = cf.tenant_id
        JOIN public.tenant_business_profiles bp ON bp.tenant_id = t.id
        WHERE cf.customer_user_id = v_user_id
          AND t.status IN ('active', 'manual_active')
          AND t.onboarding_status = 'completed'
          AND t.public_site_status = 'published'
          AND bp.is_public_profile_enabled IS TRUE
          AND COALESCE(
                (public.evaluate_public_booking_eligibility_internal(t.id, t.slug)->>'bookable')::BOOLEAN,
                false
              ) IS TRUE
    )
    SELECT COUNT(*)::INTEGER
    INTO v_total
    FROM eligible;

    WITH eligible AS (
        SELECT cf.id, cf.tenant_id, cf.created_at, t.slug, t.name
        FROM public.customer_favorites cf
        JOIN public.tenants t ON t.id = cf.tenant_id
        JOIN public.tenant_business_profiles bp ON bp.tenant_id = t.id
        WHERE cf.customer_user_id = v_user_id
          AND t.status IN ('active', 'manual_active')
          AND t.onboarding_status = 'completed'
          AND t.public_site_status = 'published'
          AND bp.is_public_profile_enabled IS TRUE
          AND COALESCE(
                (public.evaluate_public_booking_eligibility_internal(t.id, t.slug)->>'bookable')::BOOLEAN,
                false
              ) IS TRUE
        ORDER BY cf.created_at DESC, cf.id
        LIMIT v_eff_limit OFFSET v_eff_offset
    )
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'favorite_id', e.id,
                'tenant_id', e.tenant_id,
                'tenant_slug', e.slug,
                'tenant_name', e.name,
                'created_at', e.created_at
            ) ORDER BY e.created_at DESC, e.id
        ),
        '[]'::JSONB
    )
    INTO v_favorites
    FROM eligible e;

    RETURN jsonb_build_object(
        'success', true,
        'reason_code', 'OK',
        'total', v_total,
        'limit', v_eff_limit,
        'offset', v_eff_offset,
        'favorites', v_favorites
    );
END;
$$;

-- =========================================================================
-- 2. FAST-REBOOKING SEED
-- =========================================================================

CREATE OR REPLACE FUNCTION public.get_fast_rebooking_seed_by_manage_token(
    p_manage_token TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    v_token_hash       TEXT;
    v_history          RECORD;
    v_tenant           RECORD;
    v_service          RECORD;
    v_staff            RECORD;
    v_branch           RECORD;
    v_booking_eligible BOOLEAN := false;
BEGIN
    IF p_manage_token IS NULL
       OR length(trim(p_manage_token)) < 32
       OR length(trim(p_manage_token)) > 128 THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'INVALID_TOKEN');
    END IF;

    v_token_hash := encode(sha256(trim(p_manage_token)::bytea), 'hex');

    SELECT
        a.id,
        a.tenant_id,
        a.branch_id,
        a.service_id,
        a.staff_id,
        a.status
    INTO v_history
    FROM public.appointment_access_tokens tok
    JOIN public.appointments a
      ON a.id = tok.appointment_id
     AND a.tenant_id::TEXT = tok.tenant_id
    WHERE tok.token_hash = v_token_hash
      AND tok.used_at IS NULL
      AND tok.expires_at > now()
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'INVALID_TOKEN');
    END IF;

    IF v_history.status <> 'completed' THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'APPOINTMENT_NOT_REBOOKABLE');
    END IF;

    SELECT t.id, t.slug, t.status, t.onboarding_status, t.public_site_status
    INTO v_tenant
    FROM public.tenants t
    JOIN public.tenant_business_profiles bp
      ON bp.tenant_id = t.id
     AND bp.is_public_profile_enabled IS TRUE
    WHERE t.id = v_history.tenant_id
      AND t.status IN ('active', 'manual_active')
      AND t.onboarding_status = 'completed'
      AND t.public_site_status = 'published';

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'TENANT_RESELECTION_REQUIRED');
    END IF;

    v_booking_eligible := COALESCE(
        (public.evaluate_public_booking_eligibility_internal(v_tenant.id, v_tenant.slug)->>'bookable')::BOOLEAN,
        false
    );

    IF NOT v_booking_eligible THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'TENANT_RESELECTION_REQUIRED');
    END IF;

    SELECT s.id, s.tenant_id, s.name, s.price, s.duration
    INTO v_service
    FROM public.services s
    WHERE s.id = v_history.service_id
      AND s.tenant_id = v_history.tenant_id
      AND s.active IS TRUE
      AND s.duration > 0;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'SERVICE_RESELECTION_REQUIRED');
    END IF;

    SELECT st.id, st.tenant_id, st.name
    INTO v_staff
    FROM public.staff st
    WHERE st.id = v_history.staff_id
      AND st.tenant_id = v_history.tenant_id
      AND st.active IS TRUE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'STAFF_RESELECTION_REQUIRED');
    END IF;

    SELECT b.id, b.tenant_id, b.name, b.timezone
    INTO v_branch
    FROM public.branches b
    WHERE b.id = v_history.branch_id
      AND b.tenant_id = v_history.tenant_id
      AND b.is_active IS TRUE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'BRANCH_RESELECTION_REQUIRED');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.staff_services ss
        WHERE ss.staff_id = v_staff.id
          AND ss.service_id = v_service.id
    ) THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'STAFF_RESELECTION_REQUIRED');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.service_branches sb
        WHERE sb.tenant_id = v_history.tenant_id
          AND sb.service_id = v_service.id
          AND sb.branch_id = v_branch.id
    ) THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'BRANCH_RESELECTION_REQUIRED');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.staff_branches stb
        WHERE stb.tenant_id = v_history.tenant_id
          AND stb.staff_id = v_staff.id
          AND stb.branch_id = v_branch.id
    ) THEN
        RETURN jsonb_build_object('success', false, 'reason_code', 'BRANCH_RESELECTION_REQUIRED');
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'reason_code', 'OK',
        'seed', jsonb_build_object(
            'source_appointment_id', v_history.id,
            'tenant_slug', v_tenant.slug,
            'branch_id', v_branch.id,
            'service_id', v_service.id,
            'service_name', v_service.name,
            'current_service_price', v_service.price,
            'current_service_duration_minutes', v_service.duration,
            'staff_id', v_staff.id,
            'staff_name', v_staff.name,
            'requires_current_availability_selection', true,
            'availability_authority', 'evaluate_booking_slot',
            'booking_authority', 'create_public_booking',
            'canonical_booking_required', true
        )
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'reason_code', 'TEMPORARY_FAILURE');
END;
$$;

-- =========================================================================
-- 3. MINIMAL FUNCTION PRIVILEGES
-- =========================================================================

REVOKE ALL ON FUNCTION public.set_customer_favorite(UUID, BOOLEAN)
    FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.set_customer_favorite(UUID, BOOLEAN)
    TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.get_customer_favorites(INTEGER, INTEGER)
    FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_customer_favorites(INTEGER, INTEGER)
    TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.get_fast_rebooking_seed_by_manage_token(TEXT)
    FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_fast_rebooking_seed_by_manage_token(TEXT)
    TO anon, authenticated, service_role;

-- =============================================================================
-- SOURCE: 20261011_program_v2_security_surface_hardening.sql
-- =============================================================================
-- ===========================================================================
-- Ported from 72911e4: 20261007_program_v2_security_surface_hardening.sql
-- Conflict-free sequential prefix: 20261011 (ADIM-039 / Faz H1)
-- Description: Program V2 Security Surface Hardening Forward Migration.
-- Hardens ht_rate_limit_buckets RLS and privileges, sets fixed safe search_path
-- and strict execute privileges for security definer identity helpers and triggers.
-- ===========================================================================

-- =========================================================================
-- Finding S-01: Hardening public.ht_rate_limit_buckets table & RLS
-- =========================================================================
-- Revoke all direct privileges on table from public and non-admin roles
REVOKE ALL PRIVILEGES ON TABLE public.ht_rate_limit_buckets FROM PUBLIC;
REVOKE ALL PRIVILEGES ON TABLE public.ht_rate_limit_buckets FROM anon;
REVOKE ALL PRIVILEGES ON TABLE public.ht_rate_limit_buckets FROM authenticated;

-- Enable RLS to enforce no direct browser/REST access by default
ALTER TABLE public.ht_rate_limit_buckets ENABLE ROW LEVEL SECURITY;

-- Preserve service_role and postgres privileges for administration & maintenance
GRANT ALL PRIVILEGES ON TABLE public.ht_rate_limit_buckets TO service_role;
GRANT ALL PRIVILEGES ON TABLE public.ht_rate_limit_buckets TO postgres;

-- =========================================================================
-- Finding S-02: Identity Helper Metadata Disclosure Hardening
-- =========================================================================
-- Recreate get_user_role with fixed search_path = pg_catalog, public
CREATE OR REPLACE FUNCTION public.get_user_role(user_id uuid)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    u_role text;
BEGIN
    SELECT role INTO u_role FROM public.users_profile WHERE id = user_id AND active = true;
    RETURN u_role;
END;
$$;

REVOKE ALL ON FUNCTION public.get_user_role(uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.get_user_role(uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_user_role(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_user_role(uuid) TO service_role;

-- Recreate get_user_tenant_id with fixed search_path = pg_catalog, public
CREATE OR REPLACE FUNCTION public.get_user_tenant_id(user_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    u_tenant_id uuid;
BEGIN
    SELECT tenant_id INTO u_tenant_id FROM public.users_profile WHERE id = user_id AND active = true;
    RETURN u_tenant_id;
END;
$$;

REVOKE ALL ON FUNCTION public.get_user_tenant_id(uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.get_user_tenant_id(uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_user_tenant_id(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_user_tenant_id(uuid) TO service_role;

-- =========================================================================
-- Finding S-03: Super Admin Validation Helper Hardening
-- =========================================================================
-- Recreate is_super_admin with fixed search_path = pg_catalog, public and active = true check
CREATE OR REPLACE FUNCTION public.is_super_admin(user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM public.users_profile
        WHERE id = user_id AND role = 'super_admin' AND active = true
    );
END;
$$;

REVOKE ALL ON FUNCTION public.is_super_admin(uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.is_super_admin(uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.is_super_admin(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_super_admin(uuid) TO service_role;

-- =========================================================================
-- Finding S-04: Trigger Helper search_path Hardening
-- =========================================================================
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.update_tenant_business_profiles_updated_at_column()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;

-- =============================================================================
-- SOURCE: 20261012_appointment_access_tokens_table_access_hardening.sql
-- =============================================================================
-- ===========================================================================
-- Ported from 72911e4: 20261011155623_appointment_access_tokens_table_access_hardening.sql
-- Conflict-free sequential prefix: 20261012 (ADIM-039 / Faz H1)
-- Description: Forward-only hardening for the public appointment-management token table.
-- Direct browser access is removed; existing SECURITY DEFINER RPCs remain the
-- public management boundary and existing authenticated owner/admin RLS stays intact.
-- ===========================================================================

DO $migration_guard$
DECLARE
    v_table_oid oid;
    v_relkind "char";
    v_owner text;
    v_rls_enabled boolean;
    v_missing_or_changed_columns text[];
    v_policy_command text;
    v_policy_roles name[];
    v_policy_qual text;
BEGIN
    SELECT c.oid, c.relkind, pg_get_userbyid(c.relowner), c.relrowsecurity
      INTO v_table_oid, v_relkind, v_owner, v_rls_enabled
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'public'
       AND c.relname = 'appointment_access_tokens';

    IF v_table_oid IS NULL THEN
        RAISE EXCEPTION 'UNEXPECTED_SCHEMA_IDENTITY: public.appointment_access_tokens is missing';
    END IF;
    IF v_relkind <> 'r' THEN
        RAISE EXCEPTION 'UNEXPECTED_SCHEMA_IDENTITY: public.appointment_access_tokens is not a table';
    END IF;
    IF v_owner <> 'postgres' THEN
        RAISE EXCEPTION 'UNEXPECTED_SCHEMA_IDENTITY: public.appointment_access_tokens owner is %, expected postgres', v_owner;
    END IF;
    IF NOT v_rls_enabled THEN
        RAISE EXCEPTION 'UNEXPECTED_SCHEMA_IDENTITY: RLS is not enabled on public.appointment_access_tokens';
    END IF;

    WITH expected(attname, type_name) AS (
        VALUES
            ('id', 'uuid'),
            ('tenant_id', 'text'),
            ('appointment_id', 'uuid'),
            ('token_hash', 'text'),
            ('expires_at', 'timestamp with time zone'),
            ('created_at', 'timestamp with time zone'),
            ('used_at', 'timestamp with time zone')
    )
    SELECT array_agg(expected.attname ORDER BY expected.attname)
      INTO v_missing_or_changed_columns
      FROM expected
      LEFT JOIN pg_catalog.pg_attribute attribute
        ON attribute.attrelid = v_table_oid
       AND attribute.attname = expected.attname
       AND attribute.attnum > 0
       AND NOT attribute.attisdropped
     WHERE attribute.attname IS NULL
        OR pg_catalog.format_type(attribute.atttypid, attribute.atttypmod) <> expected.type_name;

    IF v_missing_or_changed_columns IS NOT NULL THEN
        RAISE EXCEPTION
            'UNEXPECTED_SCHEMA_IDENTITY: public.appointment_access_tokens columns missing or changed: %',
            v_missing_or_changed_columns;
    END IF;

    SELECT policy.cmd, policy.roles, policy.qual
      INTO v_policy_command, v_policy_roles, v_policy_qual
      FROM pg_catalog.pg_policies policy
     WHERE policy.schemaname = 'public'
       AND policy.tablename = 'appointment_access_tokens'
       AND policy.policyname = 'Allow public select by token hash';

    IF FOUND AND (
        v_policy_command <> 'SELECT'
        OR v_policy_roles <> ARRAY['public']::name[]
        OR v_policy_qual NOT IN ('true', '(true)')
    ) THEN
        RAISE EXCEPTION
            'UNEXPECTED_SCHEMA_IDENTITY: permissive token policy exists with an unexpected definition';
    END IF;
END;
$migration_guard$;

REVOKE ALL PRIVILEGES ON TABLE public.appointment_access_tokens FROM PUBLIC, anon;

DROP POLICY IF EXISTS "Allow public select by token hash"
    ON public.appointment_access_tokens;

DO $migration_postcondition$
DECLARE
    v_privilege text;
BEGIN
    FOREACH v_privilege IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE']
    LOOP
        IF pg_catalog.has_table_privilege(
            'anon',
            'public.appointment_access_tokens',
            v_privilege
        ) THEN
            RAISE EXCEPTION
                'TOKEN_TABLE_HARDENING_FAILED: anon still has % on public.appointment_access_tokens',
                v_privilege;
        END IF;
    END LOOP;

    IF EXISTS (
        SELECT 1
          FROM pg_catalog.pg_policies
         WHERE schemaname = 'public'
           AND tablename = 'appointment_access_tokens'
           AND policyname = 'Allow public select by token hash'
    ) THEN
        RAISE EXCEPTION
            'TOKEN_TABLE_HARDENING_FAILED: permissive public token policy still exists';
    END IF;
END;
$migration_postcondition$;

-- =============================================================================
-- SECTION FINAL (ADIM-041B P0): consent_ledger & policy_acceptances Hardening
-- =============================================================================
-- Eliminates permissive anon/public WITH CHECK (true) INSERT policies flagged
-- by Controller P0 Security Finding while preserving SECURITY DEFINER RPC writes
-- (create_public_booking, join_booking_waitlist) and tenant-scoped owner reads.

ALTER TABLE public.consent_ledger ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.policy_acceptances ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public insert to consent ledger" ON public.consent_ledger;
DROP POLICY IF EXISTS "Tenant Staff - Read own consents" ON public.consent_ledger;
DROP POLICY IF EXISTS "Tenant owners can read/write ledger" ON public.consent_ledger;
DROP POLICY IF EXISTS "Allow public insertion during checkout" ON public.consent_ledger;
DROP POLICY IF EXISTS "Owner/Admin manage consent ledger" ON public.consent_ledger;
DROP POLICY IF EXISTS "consent_ledger_tenant_select" ON public.consent_ledger;

DROP POLICY IF EXISTS "Allow public insert to policy acceptances" ON public.policy_acceptances;
DROP POLICY IF EXISTS "Tenant Staff - Read own policy acceptances" ON public.policy_acceptances;
DROP POLICY IF EXISTS "Allow select acceptances for reporting" ON public.policy_acceptances;
DROP POLICY IF EXISTS "Allow public insert acceptances" ON public.policy_acceptances;
DROP POLICY IF EXISTS "Owner/Admin view policy acceptances" ON public.policy_acceptances;
DROP POLICY IF EXISTS "policy_acceptances_tenant_select" ON public.policy_acceptances;

REVOKE ALL PRIVILEGES ON TABLE public.consent_ledger FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.consent_ledger TO authenticated;
GRANT ALL PRIVILEGES ON TABLE public.consent_ledger TO service_role;

REVOKE ALL PRIVILEGES ON TABLE public.policy_acceptances FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.policy_acceptances TO authenticated;
GRANT ALL PRIVILEGES ON TABLE public.policy_acceptances TO service_role;

CREATE POLICY "consent_ledger_tenant_select"
  ON public.consent_ledger
  FOR SELECT
  TO authenticated
  USING (
    CASE
      WHEN tenant_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN public.current_user_can_access_tenant(tenant_id::uuid)
      ELSE false
    END
  );

CREATE POLICY "policy_acceptances_tenant_select"
  ON public.policy_acceptances
  FOR SELECT
  TO authenticated
  USING (
    (
      CASE
        WHEN tenant_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN public.current_user_can_access_tenant(tenant_id::uuid)
        ELSE false
      END
    )
    OR (user_id IS NOT NULL AND user_id = (SELECT auth.uid())::text)
  );

-- Harden default privileges safety net: ensure direct table writes & PG17 MAINTAIN
-- are explicitly denied on appointment_access_tokens even with default privileges.
REVOKE ALL PRIVILEGES ON TABLE public.appointment_access_tokens FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.appointment_access_tokens TO authenticated;

COMMIT;
